local config = {
  ui_story_5022_50220101_1_dialog_content = "ng... Vice...",
  ui_story_5022_50220101_2_dialog_content = "Vice... Te necesito aquí...",
  ui_story_5022_50220101_3_dialog_content = "(Si tan solo me hubiera disculpado con ella en ese entonces...)",
  ui_story_5022_50220101_4_dialog_content = "<color=#e8d9bb>Hace unos días...</color>",
  ui_story_5022_50220101_5_dialog_content = "<size=45>¡Toma esto!</size>",
  ui_story_5022_50220101_6_dialog_content = "Vaya, ¿cuándo lo hiciste...? Maldición, ¡¿qué tipo de técnica de curvas es esa?!",
  ui_story_5022_50220101_7_dialog_content = "Je, todavía tengo mucho más bajo la manga! Ya estamos a mitad de camino de la meta... ¡Esta carrera es tan buena como la mía!",
  ui_story_5022_50220101_8_dialog_content = "Debo admitir que eres bueno en los juegos de carreras, ¡pero todavía es demasiado pronto para que estés celebrando!",
  ui_story_5022_50220101_9_dialog_content = "¡Derecha! Es hora de mostrarte la técnica de carrera secreta de Rediesel Wrench:",
  ui_story_5022_50220101_10_dialog_content = "...Hey!",
  ui_story_5022_50220101_11_dialog_content = "V-Vice? ¡¿Por qué apagaste la terminal?! Yo también estaba a punto de ganar...",
  ui_story_5022_50220101_12_dialog_content = "¿Realmente necesitas que te explique?",
  ui_story_5022_50220101_13_dialog_content = "Dejando de lado el hecho de que estás jugando con los programas de entrenamiento de Colossus como si fueran videojuegos... ¿Te has olvidado por completo de esta lista?",
  ui_story_5022_50220101_14_dialog_content = "¿Qué lista? Déjame echar un vistazo... ¿\"Regimiento de autoentrenamiento\"?",
  ui_story_5022_50220101_15_dialog_content = "\"Mañanas: 100 flexiones. Tardes: 100 abdominales. Noches: 100 sentadillas. Carreras diarias de larga distancia...\"",
  ui_story_5022_50220101_16_dialog_content = "Santo cielo, ese es un plan ambicioso el que tienes ahí, chico...",
  ui_story_5022_50220101_17_dialog_content = "Ahora dime, PlayerName, ¿cuántos de estos has hecho realmente?",
  ui_story_5022_50220101_18_dialog_content = "Uh... B-Bueno, ¡hice abdominales esta tarde! Quiero decir, técnicamente estuve acostado durante mucho tiempo y me senté una vez, pero...",
  ui_story_5022_50220101_19_dialog_content = "Levantarse de la siesta de la tarde no cuenta!!",
  ui_story_5022_50220101_20_dialog_content = "Hiciste un plan tan ambicioso para ti, pero cada vez que te reviso, no hay más que juegos, juegos y más juegos...",
  ui_story_5022_50220101_21_dialog_content = "De la mañana a la noche, ¡eso es todo lo que has estado haciendo últimamente!",
  ui_story_5022_50220101_22_dialog_content = "S-Sí, pero... ¡Los videojuegos son como entrenar si lo piensas bien! ¡Mis manos están firmes ahora y mis reflejos nunca han sido mejores!",
  ui_story_5022_50220101_23_dialog_content = "Derecha, Sinsa?",
  ui_story_5022_50220101_24_dialog_content = "R-Claro! ¡Esa técnica de giro de hace un momento fue una locura!",
  ui_story_5022_50220101_25_dialog_content = "Uf… ¿Sabes qué?",
  ui_story_5022_50220101_26_dialog_content = "¡Puedes olvidarte de que nunca más te ayudaré con algo! A partir de ahora, ¡usted está solo!",
  ui_story_5022_50220101_27_dialog_content = "Ya terminé... ¿Qué se supone que debo hacer si ella no está allí para recordarme mis deberes? ¡A veces puedo olvidarme mucho de las cosas!",
  ui_story_5022_50220101_28_dialog_content = "¿A quién diablos se le ocurrió un plan de entrenamiento tan loco?",
  ui_story_5022_50220101_29_dialog_content = "... Muy bien, sí, fui yo.",
  ui_story_5022_50220101_30_dialog_content = "Me pregunto si es demasiado tarde para disculparse.",
  ui_story_5022_50220101_31_dialog_content = "¿Qué pasa si trata de obligarme a terminar todos mis entrenamientos del día como castigo?",
  ui_story_5022_50220101_32_dialog_content = "Estaría perdido, eso es seguro...",
  ui_story_5022_50220101_33_dialog_content = "Sí, no es broma.",
  ui_story_5022_50220101_34_dialog_content = "Mirar, Vice está realmente molesto en este momento. ¿Por qué no esperar hasta que se calme un poco antes de intentar hacer las paces? ¿Quién sabe? ¡Incluso podría dejarte libre de culpa por completo!",
  ui_story_5022_50220101_35_dialog_content = "Tienes razón... Espera, ¿por qué pareces tan familiarizado con este tipo de cosas?",
  ui_story_5022_50220101_36_dialog_content = "Je, tener una hermanita te enseña un par de cosas... De todos modos, por el momento, trata de no mostrar tu cara cerca de ella.",
  ui_story_5022_50220101_37_dialog_content = "Pero estamos en el Coloso... ¿Dónde se supone que debo ir?",
  ui_story_5022_50220101_38_dialog_content = "¡Espera, acabo de recordar! ¡Ya casi es esa época del año!",
  ui_story_5022_50220101_39_dialog_content = "Oye, PlayerName... ¿Quieres ver cómo es una carrera real?",
  ui_story_5022_50220101_40_dialog_content = "Nunca esperé ver algo así en el desierto... ¿Qué es este lugar?",
  ui_story_5022_50220101_41_dialog_content = "Bienvenido a <color=#FFB400>Oasis</color>, uno de los principales baluartes de Rediesel Wrench!",
  ui_story_5022_50220101_42_dialog_content = "La visibilidad por aquí es bastante mala, ¿verdad? Incluso con Lepidoz, no podíamos ver a más de dos metros debido a toda la arena y el viento... Que es exactamente lo que queremos.",
  ui_story_5022_50220101_43_dialog_content = "El terreno por aquí es bastante complejo, y el clima es igual de impredecible. Somos los únicos que sabemos cómo encontrar este lugar.",
  ui_story_5022_50220101_44_dialog_content = "Bueno, para ser justos, a veces también nos cuesta encontrarlo...",
  ui_story_5022_50220101_45_dialog_content = "\"Oasis\"...",
  ui_story_5022_50220101_46_dialog_content = "¿Ves ese taller de ahí? Reparamos nuestros vehículos y armas allí cuando uno o dos buenos golpes ya no los arreglan.",
  ui_story_5022_50220101_47_dialog_content = "Y esa casa del árbol de ahí es perfecta para dormir bien. Las paredes evitan que la arena se meta en tu ropa, pero todo el lugar tiende a balancearse cuando el viento es particularmente fuerte.",
  ui_story_5022_50220101_48_dialog_content = "Puedes comprar pasteles de dátiles arenosos en este lugar, y su pastel de escorpión rojo es bastante decente.",
  ui_story_5022_50220101_49_dialog_content = "¡Y solo veinte o treinta personas se enferman cada mes por comerlos! ¡Es lo más seguro posible! ¿Tú también puedes probar suerte, si quieres? Ah, y por allá...",
  ui_story_5022_50220101_50_dialog_content = "Ey, Sinsa! ¡Bienvenido de nuevo!",
  ui_story_5022_50220101_51_dialog_content = "Acabamos de descargar los últimos productos del lagarto gigante.",
  ui_story_5022_50220101_52_dialog_content = "Escuché que Azure fue quien abrió el camino esta vez. ¡No es un mal recorrido!",
  ui_story_5022_50220101_53_dialog_content = "Estamos en camino para entregarlo en el almacén, ahora que terminaron de hacer el inventario. Cuidado para echar un vistazo, Sinsa?",
  ui_story_5022_50220101_54_dialog_content = "No, puedes dejar todo eso de los números para Roy. Hablando de eso, ¿lo han visto por aquí?",
  ui_story_5022_50220101_55_dialog_content = "—¡Oh, poderoso aventurero de una tierra lejana! Puedo ver que la carga del destino pesa mucho sobre tus hombros...",
  ui_story_5022_50220101_56_dialog_content = "¿También necesitas la guía del viento?",
  ui_story_5022_50220101_57_dialog_content = "Aventurero...?",
  ui_story_5022_50220101_58_dialog_content = "¡Hola Zeta! Ha pasado un tiempo, ¿eh? ¡Sigo jugando a la fantasía, por lo que veo!",
  ui_story_5022_50220101_59_dialog_content = "M... ¿Fantasía...?",
  ui_story_5022_50220101_60_dialog_content = "Ah, ya veo...",
  ui_story_5022_50220101_61_dialog_content = "Después de que la cruel mano del destino nos obligara a separarnos, la reacción violenta del poder del dios maligno hizo que perdieras tus recuerdos y olvidaras tu destino...",
  ui_story_5022_50220101_62_dialog_content = "Pero no te preocupes, porque estoy aquí. No hay nada que temer ahora.",
  ui_story_5022_50220101_63_dialog_content = "¡Despierta, oh guerrero maldito! ¡Despierta, berserker solitario y tres veces divorciado, condenado a vagar por las tierras sin un lugar al que llamar hogar!",
  ui_story_5022_50220101_64_dialog_content = "Eh...? Oh sí, supongo que algo de eso tiene sentido...",
  ui_story_5022_50220101_65_option_content = "¿\"guerrero maldito\"?",
  ui_story_5022_50220101_66_dialog_content = "Ah, es solo parte del juego de fantasía de Zeta. Ella inventó una personalidad completa solo para mí.",
  ui_story_5022_50220101_67_dialog_content = "Ahora, ¿cómo te fue...? Estaba vagando por la tierra en busca de poder, y luego... algo en mi alma...",
  ui_story_5022_50220101_68_dialog_content = "¡Fuiste a las ruinas de Ishradi y ofreciste tu alma al antiguo dios del mal, Y'noth-raz!",
  ui_story_5022_50220101_69_option_content = "¿Ya te has divorciado tres veces?",
  ui_story_5022_50220101_70_dialog_content = "¡Diablos no!",
  ui_story_5022_50220101_71_dialog_content = "Todo es parte de, eh... ¿Cómo se llama? ...¡Oh sí! ¡Un \"juego de rol\"! Zeta inventó un personaje completo solo para mí.",
  ui_story_5022_50220101_72_dialog_content = "La cuestión es que sigue cambiando partes de la historia, así que no estoy muy seguro de dónde estamos ahora...",
  ui_story_5022_50220101_73_dialog_content = "¡Estabas vagando por la tierra en busca de mayor poder y, después de llegar a las ruinas de Ishradi, ofreciste tu alma al antiguo dios del mal, Y'noth-raz!",
  ui_story_5022_50220101_74_dialog_content = "Pero poco después, te diste cuenta de que era un poder maldito, y así... Comenzaste tu viaje para derrotar al rey demonio...",
  ui_story_5022_50220101_75_dialog_content = "¡Oh sí! ¡Ahora recuerdo!",
  ui_story_5022_50220101_76_dialog_content = "Gracias a Dios que has vuelto a tus sentidos. Ahora, oh poderoso berserker, puedo preguntar amablemente... ¿Quién es ese que está a tu lado?",
  ui_story_5022_50220101_77_option_content = "N-Encantado de conocerte! Me llamo PlayerName!",
  ui_story_5022_50220101_78_dialog_content = "PlayerName, ¿tu dices? Hmm... Puedo sentir un poder antiguo y misterioso que yacía latente en lo más profundo de ti...",
  ui_story_5022_50220101_79_dialog_content = "Podría ser porque soy Caelestita... ¿Has oído hablar de nosotros? ¡Una raza de personas que pueden ver a Lumina, además de pilotar el gran Coloso!",
  ui_story_5022_50220101_80_option_content = "¡Soy el último de los Caelestites! ¡El Navegante del Coloso, y el guía de la luz!",
  ui_story_5022_50220101_81_dialog_content = "<size=45>El... ¡¡¡El último de los Caelestites!!!</size>",
  ui_story_5022_50220101_82_dialog_content = "Ese título... ¡Ese título es absolutamente lo mejor que he escuchado!",
  ui_story_5022_50220101_83_dialog_content = "¡No digas eso! Me estás avergonzando...",
  ui_story_5022_50220101_84_dialog_content = "Ejem... Me disculpo por el arrebato innecesario de hace un momento.",
  ui_story_5022_50220101_85_dialog_content = "Parece que todavía tengo mucho entrenamiento por hacer si deseo convertirme en un guerrero de Astra.",
  ui_story_5022_50220101_86_dialog_content = "Por favor, permítanme guiar el camino hacia la princesa. May los vientos nos guían...",
  ui_story_5022_50220101_87_dialog_content = "... Y ahí es donde están las cosas en este momento. Enviaré un mensaje a través de Courier Union de inmediato si algo cambia.",
  ui_story_5022_50220101_88_dialog_content = "Claro, pero... ¿estás seguro de que no necesitas más gente? Azure?",
  ui_story_5022_50220101_89_dialog_content = "Esos tipos en Umbraton causaron un verdadero lío con esas drogas ilícitas la última vez.",
  ui_story_5022_50220101_90_dialog_content = "Esto no otra vez... Te lo dije antes, prefiero trabajar solo. Cualquier otra persona se interpondría en mi camino.",
  ui_story_5022_50220101_91_dialog_content = "Deja de tratarme como a un niño.",
  ui_story_5022_50220101_92_dialog_content = "¡Sé que sé! es solo...",
  ui_story_5022_50220101_93_dialog_content = "¡Ayudar! ¡Creo que algo anda mal con mi bomba de alarma! No está explotando como antes...",
  ui_story_5022_50220101_94_dialog_content = "Déjame echar un vistazo... Saca el fusible así, dale una o dos palmaditas y... Ahí, como nuevo.",
  ui_story_5022_50220101_95_dialog_content = "¿Ya llegaron los snacks para Lepidoz?",
  ui_story_5022_50220101_96_dialog_content = "Brock y Fleur estaban ayudando a entregarlos. Si aún no lo han logrado... Lo más probable es que, Brock se los comió mientras nadie miraba.",
  ui_story_5022_50220101_97_dialog_content = "Si ese es el caso, solo alimenta Brock a Lepidoz. Estoy seguro de que no le importará.",
  ui_story_5022_50220101_98_dialog_content = "¡Necesitamos expandir el almacén aquí en Oasis! ¡Casi no tengo espacio para almacenar las piezas de mi máquina!",
  ui_story_5022_50220101_99_dialog_content = "¿Por qué no pruebas a colgar algunas de tus piezas del techo? Acabamos de conseguir una cuerda bonita y resistente, justo allí.",
  ui_story_5022_50220101_100_dialog_content = "O bien, puede usarlo para atar Jomu durante unos días, hasta que acceda a hacerte un espacio.",
  ui_story_5022_50220101_101_dialog_content = "Sobre ese envío de hace dos días...",
  ui_story_5022_50220101_102_dialog_content = "Almacén 6, en un cajón cubierto por una lona. Intenta tener cuidado, ¿quieres? Esos bichos muerden, y su veneno tampoco es broma.",
  ui_story_5022_50220101_103_dialog_content = "En cuanto a los suministros de hoy...",
  ui_story_5022_50220101_104_dialog_content = "La lista está en la pared de allí. Voy a echar un vistazo más tarde.",
  ui_story_5022_50220101_105_dialog_content = "eh... lo siento Azure, Apenas tengo la oportunidad de hablar contigo y aquí estoy... ¿De qué estábamos hablando hace un momento?",
  ui_story_5022_50220101_106_dialog_content = "¡Princesa! ¡Tu guerrero más estimado ha regresado!",
  ui_story_5022_50220101_107_dialog_content = "Y ahora soy una princesa, eh... Este día no se está volviendo más fácil...",
  ui_story_5022_50220101_108_dialog_content = "Ejem... Alaba la guía del viento por llevarte de regreso a mi lado, noble guerrero. ¿Qué pasa con la lucha en las fronteras de nuestro reino?",
  ui_story_5022_50220101_109_dialog_content = "Las fuerzas demoníacas han sido descaradas en sus ataques a las aldeas fronterizas, pero no se preocupe, Su Alteza. ¡Mis compañeros de confianza y yo hicimos un trabajo rápido con los viles demonios!",
  ui_story_5022_50220101_110_dialog_content = "Como muestra de su gratitud, muchas de las doncellas del pueblo nos ofrecieron dulces para protegerlas del mal.",
  ui_story_5022_50220101_111_dialog_content = "Ya veo... Entonces los Eclipsites han sido derrotados por el momento.",
  ui_story_5022_50220101_112_dialog_content = "Han surgido varias aldeas en la zona desde que acordamos ayudar a proteger la fuente de agua local. ¿Podrían los ataques de Eclipsite tener algo que ver con esto...?",
  ui_story_5022_50220101_113_dialog_content = "Parece preocupado, Su Alteza. ¿Cómo puedo ser de ayuda?",
  ui_story_5022_50220101_114_dialog_content = "Me parte el corazón ver un rostro tan bello empañado por la angustia...",
  ui_story_5022_50220101_115_dialog_content = "F-Justo...? Er... Ya has hecho más que suficiente, mi valiente héroe.",
  ui_story_5022_50220101_116_dialog_content = "La mano del destino te recomienda quitarte el cansancio de tus viajes y disfrutar de un merecido descanso. Mi ayuda siempre está disponible si necesita que alguien le trence el cabello.",
  ui_story_5022_50220101_117_dialog_content = "Bueno, mírate. ¡Seguro que te ganaste la aprobación de mami hoy, Zeta! ¡No esta mal, no está mal!",
  ui_story_5022_50220101_X117_dialog_content = "Mamá... ¿Te refieres a mí?",
  ui_story_5022_50220101_118_dialog_content = "—Pffffft!",
  ui_story_5022_50220101_119_dialog_content = "Suspiro... Cada vez que ustedes dos se encuentran...",
  ui_story_5022_50220101_120_dialog_content = "Muy bien, ¿quién más necesita la ayuda de mamá hoy? ¿Mmm? ¿Es esa una cara nueva que veo?",
  ui_story_5022_50220101_121_dialog_content = "¡Sí! Permíteme presentarte a un joven amigo con poderes místicos—PlayerName, el último de los Caelestites!",
  ui_story_5022_50220101_122_dialog_content = "Ya veo... Encantado de conocerte. nombre Roy. Solo un tipo normal que gestiona la logística y las reparaciones de la llave inglesa Rediesel.",
  ui_story_5022_50220101_123_dialog_content = "Sinsa rara vez trae amigos... El último de los Caelestites, ¿eh?",
  ui_story_5022_50220101_124_dialog_content = "Bueno, cualquier amigo del líder es amigo nuestro, además de un estimado invitado de la Llave Rediesel. Bienvenido, PlayerName.",
  ui_story_5022_50220101_125_dialog_content = "Si estás aquí en esta época del año, solo puede ser para el Blazing Rally, ¿verdad? Ahora que lo pienso, es hora de decidirse por un lugar.",
  ui_story_5022_50220101_126_dialog_content = "¿Quieres decir que aún no has decidido dónde celebrar la carrera?",
  ui_story_5022_50220101_127_dialog_content = "Sí, hay muchas pistas pero solo elegimos en cuál realizar la carrera con un día de antelación.",
  ui_story_5022_50220101_128_dialog_content = "Aun así, las fuerzas de Lumopolis tienen esta tendencia a aparecer en busca de criminales buscados y vehículos perdidos.",
  ui_story_5022_50220101_129_dialog_content = "Por supuesto, también es divertido estar rodeado.",
  ui_story_5022_50220101_130_dialog_content = "E-Eso suena emocionante…",
  ui_story_5022_50220101_131_dialog_content = "(... Estoy demasiado familiarizado con todos, así que a veces olvido que son un grupo de bandidos errantes...)",
  ui_story_5022_50220101_132_dialog_content = "¡Ajaja! Pero no debería seguir hablando de eso. Tenemos invitados. Deberíamos comportarnos. ¿Tiene alguna idea, líder?",
  ui_story_5022_50220101_133_dialog_content = "Bueno, si queremos que nuestro amigo Caelestite amplíe sus horizontes, siempre está la <color=#FFB400>Diente llameante</color>.",
  ui_story_5022_50220101_134_dialog_content = "Apuesto a que esos nobles blandos, soldados envejecidos y mercenarios no tienen las agallas para seguirnos hasta el desierto.",
  ui_story_5022_50220101_135_dialog_content = "¡No! Ese lugar está cerca de mi área de patrulla. Nadie puede ganarme allí, ¡será aburrido!",
  ui_story_5022_50220101_136_dialog_content = "Hace buen tiempo, así que, ¿por qué no vamos al Nightmare Ouroboro junto al Gold River?",
  ui_story_5022_50220101_137_dialog_content = "¡O podemos ir al Infierno Verde junto al Corredor de los Susurros y sacar de quicio a algunos imbéciles de Umbratón!",
  ui_story_5022_50220101_138_dialog_content = "(¡Así que este niño puede hablar normalmente después de todo!)",
  ui_story_5022_50220101_139_dialog_content = "Hm… The Blazing Tooth es una ruta clásica.",
  ui_story_5022_50220101_140_dialog_content = "Pero la pista es muy difícil y el equipo de logística a menudo se queja de las consecuencias. Además, siguen apareciendo eclipses, incluso con barridos regulares.",
  ui_story_5022_50220101_141_dialog_content = "Según el informe de Zeta, los eclipses han estado inusualmente activos recientemente, lo que requerirá un poco de investigación.",
  ui_story_5022_50220101_142_dialog_content = "Tengo la sensación de que podría haber uno grande en el área, pero podría estar pensando demasiado...",
  ui_story_5022_50220101_143_dialog_content = "¡...!",
  ui_story_5022_50220101_144_dialog_content = "¿Uno grande? ¿Podría ser el legendario <color=#FFB400>Dragón Malvado Hakudoma</color>?",
  ui_story_5022_50220101_145_dialog_content = "Um, ¿así se llamaba?",
  ui_story_5022_50220101_146_dialog_content = "¡Lo inventé! Es genial, ¿verdad? ¿Derecha?",
  ui_story_5022_50220101_147_dialog_content = "Pensé que encajaba bien después de escuchar la historia que me contaste al respecto.",
  ui_story_5022_50220101_148_dialog_content = "Una historia, eh... Qué despreocupación...",
  ui_story_5022_50220101_149_dialog_content = "Ey, Roy, Revisaré el área por mi cuenta mañana.",
  ui_story_5022_50220101_150_dialog_content = "Solo relájate y juega juegos de carreras con los niños.",
  ui_story_5022_50220101_151_dialog_content = "Tú… ¿Estás diciendo que soy un niño?",
  ui_story_5022_50220101_152_dialog_content = "¡¿Y que Blazing Rally es un juego?!",
  ui_story_5022_50220101_153_dialog_content = "No solo eso, ¿quieres divertirte desafiando al malvado dragón por tu cuenta?",
  ui_story_5022_50220101_154_dialog_content = "Esto no se mantendrá. ¡Te reto a un duelo de carreras!",
  ui_story_5022_50220101_155_dialog_content = "Tsk, mocoso problemático...",
  ui_story_5022_50220101_156_dialog_content = "¡Te venceré en el rally!",
  ui_story_5022_50220101_157_dialog_content = "Y si aparece el dragón, cargaré delante de ti y lo destruiré, ¡como los héroes de las historias!",
  ui_story_5022_50220101_158_dialog_content = "...Probablemente.",
  ui_story_5022_50220101_159_dialog_content = "No tengo tiempo para tus pequeños juegos.",
  ui_story_5022_50220101_160_dialog_content = "¡N-No te vayas! No finjas que no me escuchaste. ¡Te arrastraré a la cabina de registro si es necesario!",
  ui_story_5022_50220101_161_dialog_content = "¡Oye! ¡No creas que puedes irte solo porque tienes las piernas largas! ¡Espérame!",
  ui_story_5022_50220101_162_dialog_content = "Oh. Ahora, esto es interesante.",
  ui_story_5022_50220101_163_dialog_content = "¿Un duelo?",
  ui_story_5022_50220101_164_dialog_content = "En la Llave Rediesel los duelos son cosa seria. La persona desafiada debe aceptar el desafío.",
  ui_story_5022_50220101_165_dialog_content = "¿Para proteger su honor? De hecho, no tenía idea de que la llave inglesa Rediesel pudiera ser tan...",
  ui_story_5022_50220101_166_dialog_content = "No. Es para que todos los demás puedan reunirse y ver la diversión.",
  ui_story_5022_50220101_167_dialog_content = "Supongo que debería haberlo visto venir...",
  ui_story_5022_50220101_168_dialog_content = "Oye, oye, es importante tener un programa para ver.",
  ui_story_5022_50220101_169_dialog_content = "Las reglas del duelo son súper laxas, todo vale. Brock Una vez me retó a una competencia de comer lagartos asados y gané.",
  ui_story_5022_50220101_170_dialog_content = "Aunque ambos fuimos regañados por Roy después...",
  ui_story_5022_50220101_171_dialog_content = "¿Cuántas veces les he dicho que no coman bocadillos antes de acostarse? Después de ese pequeño truco, nuestras reservas de alimentos—",
  ui_story_5022_50220101_172_dialog_content = "¡Ejem! Entonces, parece que la pista está decidida y es Blazing Tooth. ¿Sin objeciones? Bien. Roy, ¡Todavía tengo que mostrarle el lugar a nuestro invitado!",
  ui_story_5022_50220101_173_dialog_content = "Bueno, si el líder lo dice...",
  ui_story_5022_50220101_174_dialog_content = "Debería ir a prepararme para la carrera también.",
  ui_story_5022_50220101_175_dialog_content = "PlayerName, ¡deberías esperarlo!",
  ui_story_5022_50220201_1_dialog_content = "(¿Cómo terminé aquí… Y esto es solo el comienzo…)",
  ui_story_5022_50220201_2_dialog_content = "<size=45>-¡Toma esto! Disparo relámpago!</size>",
  ui_story_5022_50220201_3_dialog_content = "¡No es un Blazing Rally adecuado sin él! ¡Oigan, perdedores al frente! ¿Ya estás ardiendo?",
  ui_story_5022_50220201_4_dialog_content = "¡Idiota! ¡Te mostraré cómo es un arma de rally clásica! ¡Come abrojos, parásito!",
  ui_story_5022_50220201_5_dialog_content = "¡Uaaargh! ¡Vamos a atropellarlos!",
  ui_story_5022_50220201_6_dialog_content = "Linda. ¡Sus trucos son tan viejos que me estoy poniendo nostálgico aquí!",
  ui_story_5022_50220201_7_dialog_content = "(De alguna manera salimos ilesos...)",
  ui_story_5022_50220201_8_dialog_content = "Ah, eso es mejor. Más tranquilo.",
  ui_story_5022_50220201_9_dialog_content = "Así que, hora de las explicaciones.",
  ui_story_5022_50220201_S9_dialog_content = "¿Por qué estás en mi asiento de pasajero, Caelestite?",
  ui_story_5022_50220201_10_dialog_content = "C-¿No puedes acercarte tanto? Azure! ¡Ojos en el camino! ¡El camino!",
  ui_story_5022_50220201_11_dialog_content = "Sinsa Me dijo que me sentara aquí y lo esperara, pero luego sonó el pistoletazo de salida y él todavía no había aparecido.",
  ui_story_5022_50220201_12_dialog_content = "En cambio, lo que apareció fue...",
  ui_story_5022_50220201_13_dialog_content = "Olvídalo. No me importa pasar un tiempo a solas con un niño tan lindo, siempre y cuando no me des problemas.",
  ui_story_5022_50220201_14_dialog_content = "T-Para ser honesto, no esperaba que hubiera una cadena de choques desde el principio... todos los competidores son tan brutales...",
  ui_story_5022_50220201_15_dialog_content = "¡¿Qué clase de rally es este?!",
  ui_story_5022_50220201_16_dialog_content = "Tienes agallas para subirte a mi auto sin ni siquiera saber nada sobre este evento.",
  ui_story_5022_50220201_17_dialog_content = "Sinsa estaba demasiado ocupado arrastrándome a comer pastel de escorpión para explicar algo...",
  ui_story_5022_50220201_18_dialog_content = "Tu conducción es bastante impresionante para sacarnos de ese caos.",
  ui_story_5022_50220201_19_dialog_content = "Hm, eres un poco tonto, pero bastante adulador, ¿no?",
  ui_story_5022_50220201_20_dialog_content = "De todos modos, no es nada. Esto es solo un juego, y tomarlo en serio es lo que debería estar haciendo.",
  ui_story_5022_50220201_21_dialog_content = "¿Qué pasa con el duelo?",
  ui_story_5022_50220201_22_dialog_content = "Qué pregunta tonta. Sí, acepté el desafío, pero ¿y qué si ese muñeco gana?",
  ui_story_5022_50220201_23_dialog_content = "Lo que es más importante es rastrear los movimientos de los eclipses.",
  ui_story_5022_50220201_24_dialog_content = "Para que podamos evitar que se repitan esos eventos...",
  ui_story_5022_50220201_25_dialog_content = "Hablando de eso, el legendario dragón malvado—",
  ui_story_5022_50220201_26_dialog_content = "¡Guau!",
  ui_story_5022_50220201_27_dialog_content = "¿Qué fue eso de ahora?",
  ui_story_5022_50220201_28_dialog_content = "¿Siempre haces tantas preguntas? Estoy empezando a arrepentirme de dejarte quedarte en el auto.",
  ui_story_5022_50220201_29_dialog_content = "Acabo de pasar por encima de un Eclipsite, eso es todo. No fue fatal por lo que se siente, y probablemente lo alcance más tarde.",
  ui_story_5022_50220201_30_dialog_content = "... ¿Ponerse al día?",
  ui_story_5022_50220201_31_dialog_content = "Uh-huh, también debería haber más Eclipsites más adelante.",
  ui_story_5022_50220201_32_dialog_content = "Más...?",
  ui_story_5022_50220201_33_dialog_content = "Quién sabe, tal vez incluso encuentre ese Eclipsite que he estado buscando.",
  ui_story_5022_50220201_34_dialog_content = "No es demasiado tarde para que corras por tu vida si tienes miedo.",
  ui_story_5022_50220201_35_dialog_content = "Incluso alguien como tú debería poder correr a través de este pedazo de desierto y volver al punto de partida.",
  ui_story_5022_50220201_36_dialog_content = "Erm.",
  ui_story_5022_50220201_37_dialog_content = "Je... ¡Es broma! Tu expresión nerviosa es más divertida de lo que pensaba.",
  ui_story_5022_50220201_38_dialog_content = "Qué pena, parece que nuestro dulce tiempo a solas está a punto de ser interrumpido.",
  ui_story_5022_50220201_39_dialog_content = "Q-que...?",
  ui_story_5022_50220201_40_dialog_content = "—¡Yoohoo! PlayerName!",
  ui_story_5022_50220201_41_dialog_content = "Yaawn... Parece que nos quedamos dormidos y nos perdimos el comienzo de la competencia.",
  ui_story_5022_50220201_42_dialog_content = "¡Ese eras tú! ¡No me perdí nada!",
  ui_story_5022_50220201_43_dialog_content = "Aterrizando en un neumático, pasando entre grietas más allá de los tipos que bloquean el camino, esa es la forma en que la señorita Azure ¡lo hace!",
  ui_story_5022_50220201_44_dialog_content = "Espera, el coche se ha estado moviendo todo este tiempo. ¿Cómo llegaron aquí?",
  ui_story_5022_50220201_45_dialog_content = "¡Desde el techo!",
  ui_story_5022_50220201_46_dialog_content = "Lindo. Y aquí pensé que ustedes dos se habrían sacudido por el impacto antes y estarían boca abajo en la arena.",
  ui_story_5022_50220201_47_dialog_content = "Estabas durmiendo tan profundamente en mi coche sin permiso, que sentí que te merecías un tipo especial de llamada de atención.",
  ui_story_5022_50220201_48_dialog_content = "¡No seas tan frío! Tuve que conseguir asientos de primera fila para el regreso del ex campeón de rally.",
  ui_story_5022_50220201_49_dialog_content = "PlayerName, Te conseguí un buen asiento, ¿no? Me lo puedes agradecer después.",
  ui_story_5022_50220201_50_dialog_content = "Azure es mayor que yo, se unió a Rediesel Wrench antes que yo.",
  ui_story_5022_50220201_51_dialog_content = "Más importante aún, ¡es una corredora legendaria!",
  ui_story_5022_50220201_52_dialog_content = "Legendario, ¿eh? Eso es en el pasado.",
  ui_story_5022_50220201_53_dialog_content = "La única razón que se me ocurre para tu presencia es... Hmph. Entrometidos.",
  ui_story_5022_50220201_54_dialog_content = "Joven Sinsa aquí no es un junior adorable en absoluto, pero sigue siendo el líder.",
  ui_story_5022_50220201_55_dialog_content = "Ha dicho la palabra, así que dejaré que os quedéis.",
  ui_story_5022_50220201_56_dialog_content = "Pero déjenme aclarar esto: viajaré al área de Blazing Tooth para investigar los Eclipsites. Da la casualidad de que mi ruta se superpone con la pista de carreras.",
  ui_story_5022_50220201_57_dialog_content = "Parece que tenemos más autostopistas detrás de nosotros...",
  ui_story_5022_50220201_58_dialog_content = "¿Cómo se debe castigar a los niños traviesos?",
  ui_story_5022_50220202_1_dialog_content = "¿El coche de carreras de Azure acaba de disparar un cañón a los Eclipsites que nos perseguían...?",
  ui_story_5022_50220202_2_dialog_content = "Sabes qué, en este punto, ya nada me desconcierta.",
  ui_story_5022_50220202_3_dialog_content = "<size=45>Hola a todos-!</size>Este es tu anfitrión, Jomu! ¿Extráñame?",
  ui_story_5022_50220202_4_dialog_content = "¡Guau! ¿Que es eso?",
  ui_story_5022_50220202_5_dialog_content = "El Blazing Rally hace honor a su nombre al comenzar con una explosión...",
  ui_story_5022_50220202_6_dialog_content = "Así es, ¡la mitad de nuestros concursantes ya han sido eliminados en sus puntos de partida!",
  ui_story_5022_50220202_7_dialog_content = "Desafortunadamente, algunos de ellos fueron daños colaterales en los choques de otros. ¡Pero la suerte también es parte del juego aquí!",
  ui_story_5022_50220202_8_dialog_content = "¡Tengan la seguridad de todos los derrotados que yacen entre los escombros!",
  ui_story_5022_50220202_9_dialog_content = "Rabbie y Chainsaw Rick ¡El Equipo de Logística 6 estará allí para sacarlos a todos de sus vehículos a su debido tiempo!",
  ui_story_5022_50220202_10_dialog_content = "Los que todavía están en carrera están disparando hacia la primera etapa, la <color=#FFB400>Desierto de aire caliente</color>, ¡a toda velocidad!",
  ui_story_5022_50220202_11_dialog_content = "¡Sentémonos y veamos qué emocionantes espectáculos nos esperan!",
  ui_story_5022_50220202_12_dialog_content = "¿Es esto... una transmisión en vivo?",
  ui_story_5022_50220202_13_dialog_content = "Como siempre, el Blazing Rally está patrocinado exclusivamente por Rediesel Wrench.",
  ui_story_5022_50220202_14_dialog_content = "Rediesel Wrench, tu mejor amigo en el desierto.",
  ui_story_5022_50220202_15_dialog_content = "¡Ofrecemos seguridad del pueblo, reparación de máquinas, reciclaje, lucha y otros servicios para su conveniencia!",
  ui_story_5022_50220202_16_dialog_content = "Las tarifas... bueno, son más baratas que las de Illumina de todos modos, ¡y garantizamos transparencia!",
  ui_story_5022_50220202_17_dialog_content = "¡Haga un pedido ahora y obtenga una mini figura hecha a mano del famoso Lepidoz de Rediesel Wrench!",
  ui_story_5022_50220202_X17_dialog_content = "El stock es limitado, ¡así que es por orden de llegada! ¡No te lo pierdas!",
  ui_story_5022_50220202_18_dialog_content = "A continuación, anunciemos los resultados de la encuesta de audiencia de la última carrera...",
  ui_story_5022_50220202_19_dialog_content = "El feedback con más votos: ¿Podemos deshacernos del locutor ruidoso?",
  ui_story_5022_50220202_20_dialog_content = "¡Gracias! ¡Su satisfacción es nuestra motivación para mejorar!",
  ui_story_5022_50220202_21_dialog_content = "Desafortunadamente, todos los demás son demasiado tímidos o encuentran esta tarea demasiado problemática, ¡así que sigo siendo el anfitrión de la carrera de este año!",
  ui_story_5022_50220202_22_dialog_content = "Sin embargo, como compensación, ¡he invitado a comentaristas invitados para usted!",
  ui_story_5022_50220202_23_dialog_content = "¡Estaremos transmitiendo desde la estación de radio oficial en Lepidoz, compartiendo noticias sobre la carrera y muchos otros mensajes!",
  ui_story_5022_50220202_24_dialog_content = "... ¿Qué? ¿Quieres que me siente aquí? Tengo otras cosas importantes que⁠—",
  ui_story_5022_50220202_25_dialog_content = "¿De verdad quieres que un viejo como yo haga esto? No se me ocurre nada divertido que decir...",
  ui_story_5022_50220202_26_dialog_content = "(¡Claramente, lo obligaron al azar a hacer esto!)",
  ui_story_5022_50220202_27_dialog_content = "Y ahora, tengamos...",
  ui_story_5022_50220202_28_dialog_content = "Oh, quiero decir, tengamos a nuestro comentarista invitado Roy ¡presenta las reglas de la competencia a nuestros amigos que son nuevos en esto!",
  ui_story_5022_50220202_29_dialog_content = "Eh... ¿Reglas? No hacemos nada de esas cosas aburridas.",
  ui_story_5022_50220202_30_dialog_content = "Cualquiera que se inscriba puede usar cualquier vehículo para completar el curso designado. Todo lo que tienes que hacer es permanecer en el vehículo el mayor tiempo posible y completar el recorrido lo más rápido que puedas.",
  ui_story_5022_50220202_31_dialog_content = "¡Precisamente! ¡Conquista la naturaleza con bravuconería, empújate más allá de las limitaciones!",
  ui_story_5022_50220202_32_dialog_content = "¡Deja que el fuego de tus motores y tu corazón te impulsen en la batalla!",
  ui_story_5022_50220202_33_dialog_content = "¿Hay algo más que nuestro comentarista invitado quisiera agregar?",
  ui_story_5022_50220202_34_dialog_content = "¿Hay algo más que agregar? Supongo... Diviértete y trata de volver con vida.",
  ui_story_5022_50220202_35_dialog_content = "Siéntase libre de volverse loco. Mientras le quede vida, no hay nada que el equipo de logística no pueda hacer.",
  ui_story_5022_50220202_36_dialog_content = "¡Excelente! Como se esperaba de Roy, desatando una declaración tan extrema tan casualmente!",
  ui_story_5022_50220202_37_dialog_content = "Y esta no es la única sorpresa que preparamos este año.",
  ui_story_5022_50220202_38_dialog_content = "¡El legendario piloto invicto, conocido como el Sexy Wildcat de Rediesel Race, vuelve a las pistas por primera vez en una década!",
  ui_story_5022_50220202_39_dialog_content = "Jomu...!",
  ui_story_5022_50220202_40_dialog_content = "(Hay un aura intensamente peligrosa que emana de Azure...)",
  ui_story_5022_50220202_41_dialog_content = "Nunca he oído ese apodo en mi vida... Pronto estarás en su línea de visión, no es demasiado tarde para el control de daños.",
  ui_story_5022_50220202_42_dialog_content = "Es un pequeño sacrificio que hacer por el bien del espectáculo.",
  ui_story_5022_50220202_43_dialog_content = "Y hablando de!",
  ui_story_5022_50220202_44_dialog_content = "Se dice que el poderoso Eclipsite que apareció en Blazing Tooth hace más de diez años—",
  ui_story_5022_50220202_45_dialog_content = "—¡El Dragón Malvado Hakudoma, podría aparecer de nuevo!",
  ui_story_5022_50220202_46_dialog_content = "¿Cuándo se hizo oficial ese nombre? Bueno, a Zeta le va a encantar.",
  ui_story_5022_50220202_47_dialog_content = "De todos modos, vine porque quería discutir los premios contigo.",
  ui_story_5022_50220202_48_dialog_content = "¡Casi olvido! ¡Los premios de este año son los más lujosos hasta ahora!",
  ui_story_5022_50220202_49_dialog_content = "Como siempre, es por orden de llegada, e incluyen un boleto interactivo de un día de Lepidoz, Barbara y la de Regina...",
  ui_story_5022_50220202_50_dialog_content = "Los premios se han ido.",
  ui_story_5022_50220202_51_dialog_content = "¿Ah? ¿A qué te refieres con eso?",
  ui_story_5022_50220202_52_dialog_content = "Lepidoz se comió el ticket interactivo de un día.",
  ui_story_5022_50220202_53_dialog_content = "Barbara y Regina no querían juntar sus respectivos álbumes, y los explosivos aficionados tenían una selección anual de seis miembros en uno...",
  ui_story_5022_50220202_54_dialog_content = "Joanie Boom ganó, pero no pudo resistir la tentación y detonó su bomba antes de que comenzara la carrera.",
  ui_story_5022_50220202_55_dialog_content = "Ella dijo algo acerca de no haberlo probado después de hacerlo, luego envió una explosión de arenisca afilada al cielo.",
  ui_story_5022_50220202_56_dialog_content = "Pensé que era bastante decente, pero ella siguió insistiendo en que el color de la llama podría mejorar más estéticamente.",
  ui_story_5022_50220202_57_dialog_content = "Está bien, déjame corregirme—",
  ui_story_5022_50220202_58_dialog_content = "Parece que los premios para la carrera de este año serán los mismos que en años anteriores: mi propia mezcla ultrasecreta de proteína en polvo...",
  ui_story_5022_50220202_59_dialog_content = "¡Y un animalito hecho a mano por un donante anónimo!",
  ui_story_5022_50220202_60_dialog_content = "¡Además, cada corredor recibe un premio de participación!",
  ui_story_5022_50220202_61_dialog_content = "Cuál podría ser-",
  ui_story_5022_50220202_62_dialog_content = "¡La experiencia de estar vivo, de la pasión ardiente que corre por tus venas y la alegría de reír con todos entre el viento, bajo el sol tórrido!",
  ui_story_5022_50220202_63_dialog_content = "(¿Se puede apagar esta estación de radio...?)",
  ui_story_5022_50220202_64_dialog_content = "¡Esperar! Para aquellos de ustedes que están a punto de apagar la radio, ¡tenemos un premio misterioso más que se revelará más adelante!",
  ui_story_5022_50220202_65_dialog_content = "Lo emocionante comienza aquí. Pero primero, un mensaje importante—",
  ui_story_5022_50220202_66_dialog_content = "Octobro Shaved Ice, el puesto de helados raspados frente al Tir' Hotel, ¡ha lanzado recientemente un nuevo producto!",
  ui_story_5022_50220202_67_dialog_content = "Se llama Las mentiras saben a miel dulce. Sólo despierta el interés de uno, ¿no es así? Todos los que participaron en la prueba de sabor, ya sea Aurorian o Wolf, dijeron...",
  ui_story_5022_50220202_68_dialog_content = "Uf, eso finalmente ha terminado. ¿A la gente le gustan premios como ese...?",
  ui_story_5022_50220202_69_dialog_content = "Ja, nunca se sabe.",
  ui_story_5022_50220202_70_dialog_content = "Los miembros de Rediesel Wrench siempre han sido los encargados de recoger los premios. Hemos tenido incluso peor en años anteriores.",
  ui_story_5022_50220202_71_dialog_content = "La cosa es que, incluso si no hubiera premios involucrados, la gente vendría solo para divertirse.",
  ui_story_5022_50220202_72_dialog_content = "(¿Es la señorita Azure... sonriendo?)",
  ui_story_5022_50220202_73_dialog_content = "...Azure, ¿podría ser que realmente te gusta el Blazing Rally...?",
  ui_story_5022_50220202_74_dialog_content = "Nos acabamos de conocer y ya estás tratando de entrar en mi cabeza. No es una forma inteligente de coquetear con alguien, Caelestite.",
  ui_story_5022_50220202_75_dialog_content = "C-Cómo debería decirlo... Este evento es una locura. ¿Es así como hace las cosas la llave Rediesel...?",
  ui_story_5022_50220202_76_dialog_content = "¿De qué estás murmurando?",
  ui_story_5022_50220202_77_dialog_content = "Zeta?",
  ui_story_5022_50220202_78_dialog_content = "¿Vaya? No puedo creer que hayas reconocido mi voz tan rápido.",
  ui_story_5022_50220202_79_dialog_content = "Realmente no eres un proveedor casual... Maestro del Coloso, guía de la luz, último de los Caelestitas.",
  ui_story_5022_50220202_80_option_content = "Solo llamame PlayerName.",
  ui_story_5022_50220202_81_dialog_content = "¡Tonto! ¡Es un gran título! ¡Es un desperdicio no usarlo más!",
  ui_story_5022_50220202_82_dialog_content = "Veamos... Correcto, entonces, ¿por qué estamos siendo honrados con la presencia de Miss Sweet Devil en el canal de comunicación?",
  ui_story_5022_50220202_83_dialog_content = "Tú... ¡¿Me estás tomando por tonto, verdad?!",
  ui_story_5022_50220202_84_dialog_content = "¿No es ese el nombre del equipo que se te ocurrió? Miss-Sweet-Diablo.",
  ui_story_5022_50220202_85_dialog_content = "¡No te rías cuando lo digas!",
  ui_story_5022_50220202_86_option_content = "Jejeje, me halagas.",
  ui_story_5022_50220202_87_dialog_content = "¿Vaya? No esperaba que te gustara tanto el juego de roles. Que lindo.",
  ui_story_5022_50220202_88_dialog_content = "Pues bien... Señorita Dulce Diablo, ¿qué es lo que quiere de mi Caelestite?",
  ui_story_5022_50220202_89_dialog_content = "\"Mi\"...?",
  ui_story_5022_50220202_90_dialog_content = "No... ¡No te rías cada vez que mencionas el nombre que puse tanto esfuerzo en crear!",
  ui_story_5022_50220202_91_dialog_content = "¡Solo estoy aquí para ver por qué ustedes, carne de cañón, son tan lentos!",
  ui_story_5022_50220202_92_dialog_content = "¿El nombre de tu equipo no es Sweet Devil? Evoca una imagen confusa...",
  ui_story_5022_50220202_93_dialog_content = "El año pasado fue Child of the Wilderness o algo así...",
  ui_story_5022_50220202_94_dialog_content = "frenético Sinsa! ¿Por qué estás en el auto de esa mujer...? ¿Has traicionado tu misión?",
  ui_story_5022_50220202_95_dialog_content = "Eh, eso es... es...",
  ui_story_5022_50220202_96_dialog_content = "Jejeje. Lo sé, solo estás fingiendo que ella te engaña, pero en realidad estás esperando una oportunidad para ayudarme a detener su progreso...",
  ui_story_5022_50220202_97_dialog_content = "¡Aprecio tus esfuerzos, pero tengo la intención de luchar contra ella de manera justa y honesta!",
  ui_story_5022_50220202_98_dialog_content = "Parece que el caos de la línea de salida no fue suficiente para acabar contigo.",
  ui_story_5022_50220202_99_dialog_content = "Aunque es sorprendente que solo unas pequeñas bombas causaran tal alboroto...",
  ui_story_5022_50220202_100_dialog_content = "¡No, el seguimiento ocurrió principalmente porque cierto calvo sacó un lanzamisiles!",
  ui_story_5022_50220202_101_dialog_content = "¡Ay, ay! ¡Tiembla, Caelestita!",
  ui_story_5022_50220202_102_dialog_content = "Ella no está escuchando en absoluto.",
  ui_story_5022_50220202_103_dialog_content = "Alojo el poder de un dios demonio dentro de mí... ¡Soy el diablo! ¡Yo soy la amenaza! Incomprendido por todos en el mundo...",
  ui_story_5022_50220202_104_dialog_content = "... ¡Sin embargo, hay el espíritu de un guerrero bondadoso dentro de mí!",
  ui_story_5022_50220202_105_dialog_content = "Está actuando como si no estuviera escuchando, pero claramente acaba de arreglar el agujero en la trama de su historia...",
  ui_story_5022_50220202_106_dialog_content = "Así... te haré ver la derrota, Azure.",
  ui_story_5022_50220202_107_dialog_content = "También conocido como Absolute Zero Witch, ¡lacayo de uno de los cuatro Reyes Celestiales, el Rey Demonio!",
  ui_story_5022_50220202_108_dialog_content = "Quiénes en el mundo son el Rey Demonio y los otros tres... Sabes qué, no quiero saberlo.",
  ui_story_5022_50220202_109_dialog_content = "Debo admitir que prefiero Absolute Zero Witch a Sexy Wildcat.",
  ui_story_5022_50220202_110_dialog_content = "Desde el primer año que gané el Blazing Rally...",
  ui_story_5022_50220202_111_dialog_content = "Los tontos han estado comparando mi récord con el tuyo, diciendo que si no hubieras dejado las huellas, tal vez nunca tendría una oportunidad de ganar.",
  ui_story_5022_50220202_112_dialog_content = "Y siempre te embarcas en misiones peligrosas diciendo que quieres entrenar tu fuerza, haciendo Roy ¡preocupado por ti!",
  ui_story_5022_50220202_113_dialog_content = "No es necesario pronunciar más palabras. Nuestras vidas ya han sido entretejidas por la Mano del Destino.",
  ui_story_5022_50220202_114_dialog_content = "Corredor de las leyendas, será mejor que no me decepciones.",
  ui_story_5022_50220202_115_dialog_content = "Incluso agregó un poco de floritura extra al final...",
  ui_story_5022_50220202_116_dialog_content = "Es divertido ver a alguien esforzarse tanto, ¿no? A pesar de eso, ella no tiene lo que se necesita para ser traviesa.",
  ui_story_5022_50220202_117_dialog_content = "Pero como corredora, es una oponente que no debe subestimarse.",
  ui_story_5022_50220202_118_dialog_content = "¿Escuchaste el viento en el fondo de su transmisión? Hubo interferencias, pero estoy seguro.",
  ui_story_5022_50220202_119_dialog_content = "Zeta se adelantó a todos los demás y ya está en el desierto de aire caliente.",
  ui_story_5022_50220202_120_dialog_content = "Como el antagonista designado de su protagonista, voy a tener que mejorar mi juego.",
  ui_story_5022_50220301_1_dialog_content = "*Bostezo* ¿Dónde estamos?",
  ui_story_5022_50220301_2_dialog_content = "¡Oh! ¿No estamos ya en el desierto de aire caliente?",
  ui_story_5022_50220301_3_dialog_content = "Tengo algunos gusanos de arena secos aquí. ¿Quieres un poco? Me los comeré si no los quieres.",
  ui_story_5022_50220301_4_dialog_content = "Saben que esto no es un picnic, ¿verdad?",
  ui_story_5022_50220301_5_dialog_content = "¡Jejeje, tenía tantas ganas de que llegara el día de hoy que no dormí nada anoche!",
  ui_story_5022_50220301_6_dialog_content = "Entre la conducción rápida y constante de Azure y el zumbido de Jomu, me dio tanto sueño...",
  ui_story_5022_50220301_7_dialog_content = "Hablando de eso, se supone que Jomu es el locutor, ¡pero es solo un anuncio tras otro y nada sobre la carrera real!",
  ui_story_5022_50220301_8_dialog_content = "Los puntos de partida son diferentes, pero todos los concursantes pasan por el punto de control en Hot Air Desert en su camino a la estación de servicio en Dragon Breath Volcano.",
  ui_story_5022_50220301_9_dialog_content = "Luego pasan por Blazing Tooth Canyon, para finalmente llegar al borde más lejano de Eternal Night.",
  ui_story_5022_50220301_10_dialog_content = "Como su nombre lo indica, es una pista hacia el fin del mundo.",
  ui_story_5022_50220301_11_dialog_content = "El fin del mundo...",
  ui_story_5022_50220301_12_dialog_content = "El clima parece agradable hoy, por lo que no deberíamos encontrarnos con tormentas de arena. La última vez que corrimos, la arena nos golpeaba en la cara...",
  ui_story_5022_50220301_13_dialog_content = "¿Hay tormentas de arena? Eso suena muy arriesgado...",
  ui_story_5022_50220301_14_dialog_content = "No te preocupes, incluso si eres arrastrado hacia el cielo, ¡siempre hay una salida!",
  ui_story_5022_50220301_15_dialog_content = "Mmm. Deberíamos encontrarnos con otros competidores pronto.",
  ui_story_5022_50220301_16_dialog_content = "¡Oh! Mirar, PlayerName, ¡Mira!",
  ui_story_5022_50220301_17_dialog_content = "Eso es...",
  ui_story_5022_50220301_18_dialog_content = "¡Cuidado!",
  ui_story_5022_50220301_19_dialog_content = "Tsk, tsk. que bueno jejeje Sinsa fue rápido y te hizo retroceder.",
  ui_story_5022_50220301_20_dialog_content = "Sabes que esto no es un picnic, ¿verdad? PlayerName?",
  ui_story_5022_50220301_21_dialog_content = "¿Fue el molino de viento de la sombra de Clover el que casi me corta un trozo de cabello?",
  ui_story_5022_50220301_22_dialog_content = "¡Oye, eso es peligroso! ¡Tienes que pagar si me haces perder alguna de mis plumas!",
  ui_story_5022_50220301_23_dialog_content = "U-Um, g-chicos... No peleen... Moverse es peligroso...",
  ui_story_5022_50220301_24_dialog_content = "¡Waaaah! Soy mucho mejor con una moto en comparación con esto...",
  ui_story_5022_50220301_25_dialog_content = "Ese oso lo empezó.",
  ui_story_5022_50220301_26_dialog_content = "¡No me uses como chivo expiatorio!",
  ui_story_5022_50220301_27_dialog_content = "<size=45>¡Por supuesto que no recibí una comisión para venir a este lugar caliente como el infierno para participar en esta carrera y decirle a Kuma que te embosque para aumentar mis posibilidades de ganar!</size>",
  ui_story_5022_50220301_28_dialog_content = "Pengy, no acostumbrada, a mentir.",
  ui_story_5022_50220301_29_dialog_content = "¡Trabaja conmigo, socio! ¿Sabes por lo que tengo que pasar solo para ganarnos la vida?",
  ui_story_5022_50220301_30_dialog_content = "Parece que el Sr. Pengy tiene mucho trabajo por delante...",
  ui_story_5022_50220301_31_dialog_content = "Maggie, ojos en el camino. Tenga cuidado con las pendientes de arena.",
  ui_story_5022_50220301_32_dialog_content = "¡Ajá! ¡Una abertura!",
  ui_story_5022_50220301_33_dialog_content = "... Quiero gritar hasta quedar ronco, pero esta chica inquietantemente tranquila...",
  ui_story_5022_50220301_34_dialog_content = "¡¡¡Cállate!!! ¡Deja de perturbar mi sueño! ¿Quieres comer balas?",
  ui_story_5022_50220301_35_dialog_content = "¡¿Una emboscada?! ¡Prueba el poder de estas conchas! Ártico-",
  ui_story_5022_50220301_36_dialog_content = "Desviando la atención, proyectiles falsos y todo volado. Tan rápido.",
  ui_story_5022_50220301_37_dialog_content = "B-Antes de que pudiera usar Luminatics, tú...",
  ui_story_5022_50220301_38_dialog_content = "¿Eh? ¿No es esta señorita? Kafka?!",
  ui_story_5022_50220301_39_dialog_content = "Qué, son ustedes dos... ¿Así que finalmente decidieron unirse a Rediesel Wrench?",
  ui_story_5022_50220301_40_dialog_content = "¿Guau?",
  ui_story_5022_50220301_41_dialog_content = "No pienses tan poco de nosotros. A diferencia de este cocodrilo de aquí, no nos uniríamos a ustedes solo por una piscina asquerosa y tres comidas al día.",
  ui_story_5022_50220301_42_dialog_content = "Oye, no creas que no puedo echarte del auto solo porque estoy conduciendo. ¿O quieres convertirte en una almohada suave?",
  ui_story_5022_50220301_43_dialog_content = "¡Sí! A ustedes les gusta mucho esa piscina, ¿verdad?",
  ui_story_5022_50220301_44_dialog_content = "De hecho, pasamos mucho tiempo refrescándonos en la piscina del Oasis, poniéndonos al día con los chismes y las noticias a través de Rediesel Wrench.",
  ui_story_5022_50220301_45_dialog_content = "Extrañar Kafka también nos da bocadillos de vez en cuando, pero...",
  ui_story_5022_50220301_46_dialog_content = "¡Mis alas de libertad nunca serán compradas por estas pequeñas sutilezas!",
  ui_story_5022_50220301_47_dialog_content = "Todavía tengo dolor de cabeza por quedarme despierto hasta tarde en el trabajo. No tengo tiempo para tus tonterías. Mira aquí.",
  ui_story_5022_50220301_48_dialog_content = "Tus proyectiles eran solo una táctica de distracción. Estas latas de arenque, sin embargo, son auténticas.",
  ui_story_5022_50220301_49_dialog_content = "!",
  ui_story_5022_50220301_50_dialog_content = "Los voy a tirar.",
  ui_story_5022_50220301_51_dialog_content = "T-Tenemos esto—",
  ui_story_5022_50220301_X51_dialog_content = "Yo también—",
  ui_story_5022_50220301_X52_dialog_content = "Aaaahhh!!",
  ui_story_5022_50220301_X53_dialog_content = "Pengy! ¡Cuélgate de mí!",
  ui_story_5022_50220301_52_dialog_content = "Ese estúpido pingüino no tuvo que saltar de un coche a toda velocidad sólo por unas cuantas latas...",
  ui_story_5022_50220301_53_dialog_content = "Kuma estaba tratando de salvarlo y también cayó... Rodaron tan lejos que ya no puedo verlos.",
  ui_story_5022_50220301_54_dialog_content = "Deben ser las alas de la libertad de las que estaban hablando... De verdad, nadie les gana en payasadas.",
  ui_story_5022_50220301_55_dialog_content = "Muy bien, tus dos compañeros de equipo están dando tumbos en la arena, Sork. Prácticamente se han dado por vencidos.",
  ui_story_5022_50220301_56_dialog_content = "Esas latas de pescado no se desperdiciaron. Sé que apuntamos a lo mismo.",
  ui_story_5022_50220301_57_dialog_content = "La confrontación es inevitable.",
  ui_story_5022_50220301_58_dialog_content = "¡Awooooo!",
  ui_story_5022_50220301_59_dialog_content = "No entiendo... Realmente no entiendo.",
  ui_story_5022_50220301_60_dialog_content = "Por qué... ¿Por qué son los peluches que Roy hace sólo por diversión tan popular?",
  ui_story_5022_50220301_61_dialog_content = "Algunos coleccionistas incluso contratan a Bounty Hunters a precios ridículos solo para tener uno en sus manos.",
  ui_story_5022_50220301_62_dialog_content = "Porque podría haber un conejo esta vez. No te puedes perder los conejos.",
  ui_story_5022_50220301_63_dialog_content = "Bunnybear Plushes no es rival para su textura esponjosa. Tienes garantizada una buena noche de sueño abrazando a uno.",
  ui_story_5022_50220301_64_dialog_content = "¡Guau guau!",
  ui_story_5022_50220301_65_dialog_content = "No importa cómo se vean... o de qué materiales estén hechos... Siempre se siente como una suave caricia...",
  ui_story_5022_50220301_66_dialog_content = "Materiales sencillos pero elaborados con delicadeza y exquisitez. Lo convierte en un sillón perfecto en el nido.",
  ui_story_5022_50220301_67_dialog_content = "Bekk... ¿¡Incluso tú eres fanático!?",
  ui_story_5022_50220301_68_dialog_content = "¡Kafka tiene razón, chirrido! Esta batalla es inevitable.",
  ui_story_5022_50220301_69_dialog_content = "Es una rara oportunidad. Mientras estamos en eso, ¿por qué no averiguar quién es mejor francotirador que Rediesel Wrench?",
  ui_story_5022_50220301_70_dialog_content = "¡No hay dónde esconderse! ¡Franz, vete!",
  ui_story_5022_50220301_71_dialog_content = "¡Chirrido! ¡Bekk furioso!",
  ui_story_5022_50220301_72_dialog_content = "¡Mi turno! ¡M23 alto explosivo!",
  ui_story_5022_50220301_73_dialog_content = "Parece bastante animado por allí... ¿No deberíamos hacer algo al respecto?",
  ui_story_5022_50220301_74_dialog_content = "Está bien. Golpearse unos a otros también es parte de la carrera.",
  ui_story_5022_50220301_75_dialog_content = "Familiarizarse con las habilidades de los demás les permitirá trabajar mejor juntos en la batalla.",
  ui_story_5022_50220301_76_dialog_content = "no sabia que era tan profundo...",
  ui_story_5022_50220301_77_dialog_content = "Oh, se me ocurrió esa explicación al azar. ¡Me impresiono incluso a mí mismo!",
  ui_story_5022_50220301_78_dialog_content = "¿No podemos distanciarnos de ellos y dar vueltas alrededor?",
  ui_story_5022_50220301_79_dialog_content = "No es que no podamos, pero esta zona está repleta de gusanos de arena gigantes.",
  ui_story_5022_50220301_80_dialog_content = "Si nos desviamos del camino, probablemente terminemos como bocadillos de gusanos de arena, con auto y todo. O peor aún, las arenas movedizas nos tragarían.",
  ui_story_5022_50220301_81_dialog_content = "Pero incluso la ruta designada nos lleva a través de sus cotos de caza...",
  ui_story_5022_50220301_82_dialog_content = "Por cierto, escuché que hubo concursantes que trajeron sus propios gusanos de arena gigantes domesticados en años anteriores.",
  ui_story_5022_50220301_83_dialog_content = "Así es. Lo hicieron bien, para mi sorpresa, pero aun así gané al final.",
  ui_story_5022_50220301_84_dialog_content = "¡Guau! ¡Hay una ojiva gigante viniendo hacia aquí! Me pregunto de qué color será su explosión...",
  ui_story_5022_50220301_85_dialog_content = "Tsk... Qué montón de niños, esparciendo sus juguetes por todos lados así.",
  ui_story_5022_50220301_86_dialog_content = "¡¿En serio estás llamando a los explosivos \"juguetes\"?!",
  ui_story_5022_50220301_87_dialog_content = "Juguetes que duelen al pisarlos. Los dos francotiradores se ven más profesionales, pero la forma en que sostienen sus armas podría ser más...",
  ui_story_5022_50220301_88_dialog_content = "Azure! ¡Doblar! ¡Voltea ahora!",
  ui_story_5022_50220301_89_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5022_50220301_90_dialog_content = "Oh, solo un amarillo regular. Aburrido.",
  ui_story_5022_50220301_91_dialog_content = "Vaya, eso estuvo cerca... Qué onda de choque...",
  ui_story_5022_50220301_92_dialog_content = "¿Te divertiste lo suficiente? Si vamos a movernos, he encontrado una buena ruta.",
  ui_story_5022_50220301_93_dialog_content = "tener señorita Azure aquí me hace sentir seguro. Y ese hermoso giro de ahora, ni siquiera necesité advertirle...",
  ui_story_5022_50220301_94_dialog_content = "¡No no no no! Lo que ella llama una buena ruta—",
  ui_story_5022_50220301_95_dialog_content = "Caelestite, ¿te gusta rudo?",
  ui_story_5022_50220301_96_dialog_content = "¿Qué?",
  ui_story_5022_50220301_97_dialog_content = "PlayerName, ¡apurarse! ¡Agárrate a algo!",
  ui_story_5022_50220501_1_dialog_content = "(¿Estaba soñando?)",
  ui_story_5022_50220501_2_dialog_content = "(Soñé que nos acercábamos a una gran pendiente de arena. El auto voló por los aires y el tiempo pareció detenerse).",
  ui_story_5022_50220501_3_dialog_content = "(A nuestro alrededor había eclipses acechando en las sombras de las rocas. Todos miraron hacia arriba y me encontré con la mirada de cientos de pares de ojos).",
  ui_story_5022_50220501_4_dialog_content = "(Los eclipses fueron derrotados rápidamente, pero luego las dunas de arena comenzaron a separarse...)",
  ui_story_5022_50220501_5_dialog_content = "(Y algo apareció del suelo... ¿una boca llena de dientes?)",
  ui_story_5022_50220501_6_dialog_content = "¿Fue eso... un sueño?",
  ui_story_5022_50220501_7_dialog_content = "Era real.",
  ui_story_5022_50220501_8_dialog_content = "Vamos bastante rápido, así que ese gusano de arena hambriento es el problema del equipo de Kafka.",
  ui_story_5022_50220501_9_dialog_content = "¿Estarán bien?",
  ui_story_5022_50220501_10_dialog_content = "Por cierto, ¿es esto lo que llamas \"gustar más rudo\"?",
  ui_story_5022_50220501_11_dialog_content = "¡Hola! ¿Siguen vivos, mis oyentes y concursantes?",
  ui_story_5022_50220501_12_dialog_content = "Soy Jomu, tu anfitrión. ¡El Blazing Rally realmente se está calentando ahora! ¡Matar o ser asesinados, gente!",
  ui_story_5022_50220501_13_dialog_content = "Los gusanos de arena gigantes son invitados ocasionales a los que les gusta aparecer abruptamente, ¡y también se encontrarán en el Desierto de Aire Caliente!",
  ui_story_5022_50220501_14_dialog_content = "¿Quién sabe si tendremos más visitantes sorpresa más adelante en la carrera?",
  ui_story_5022_50220501_15_dialog_content = "Por ejemplo, ¡el legendario dragón malvado de nueve cabezas, seis garras y tres alas!",
  ui_story_5022_50220501_16_dialog_content = "Realmente dirás cualquier cosa para irritar a la multitud. ¿Ya has anunciado algo importante?",
  ui_story_5022_50220501_17_dialog_content = "Odi de la división de comunicación está recogiendo las señales de los concursantes que se dan por vencidos debido a los ataques de los gusanos de arena. Pero antes de eso...",
  ui_story_5022_50220501_18_dialog_content = "¡Todo el mundo! ¡El Eclipsite conocido como el Dragón Malvado es el mismo que fue ahuyentado por nuestro comentarista invitado hace años!",
  ui_story_5022_50220501_19_dialog_content = "Que hace Roy que decir sobre este viejo amigo?",
  ui_story_5022_50220501_20_dialog_content = "Por qué de repente... Bueno, sí. Fue una pena que no pudiéramos matar al Eclipsite en ese entonces.",
  ui_story_5022_50220501_21_dialog_content = "La fortaleza había sufrido una emboscada de los Eclipsites. Nos quedamos sin munición, y sus garras me habían atravesado...",
  ui_story_5022_50220501_22_dialog_content = "Pero aún desearía haberme esforzado más en ese entonces.",
  ui_story_5022_50220501_23_dialog_content = "¿Atravesado a través de ti?",
  ui_story_5022_50220501_24_dialog_content = "Ah, no fue nada. De todos modos, dejo la lucha a los jóvenes en estos días.",
  ui_story_5022_50220501_25_dialog_content = "Dicho esto, ciertas personas deberían tomárselo con un poco más de calma. Incluso si tienen lo que se necesita, no siempre deben tratar de hacer las cosas por su cuenta...",
  ui_story_5022_50220501_26_dialog_content = "Ya que estamos aquí, ¿por qué no relajarse un poco y disfrutar de la carrera?",
  ui_story_5022_50220501_27_dialog_content = "... ¿Entonces esa criatura realmente existe? Pensé que era solo algo de las historias de Zeta, como el dios malvado...",
  ui_story_5022_50220501_28_dialog_content = "¿Estas asustado? ¿Quiero un abrazo?",
  ui_story_5022_50220501_29_option_content = "¡No estoy!",
  ui_story_5022_50220501_30_dialog_content = "¿Es eso así? Tu falsa valentía también es linda.",
  ui_story_5022_50220501_31_option_content = "¡Sí, por favor!",
  ui_story_5022_50220501_32_dialog_content = "¿Vaya? Me encanta un chico honesto. Lamentablemente, estoy ocupado en este momento.",
  ui_story_5022_50220501_33_dialog_content = "Hace cuantos años que no esta? No es de extrañar que la historia se haya vuelto tan descabellada.",
  ui_story_5022_50220501_34_dialog_content = "Y ahora aparece el mismo año que regreso... Es demasiada coincidencia, ¿no?",
  ui_story_5022_50220501_35_dialog_content = "Pero existió y aún existe...",
  ui_story_5022_50220501_36_dialog_content = "...Voy a rectificar esto.",
  ui_story_5022_50220501_37_dialog_content = "(Su mirada es más aterradora que la de un dragón de nueve cabezas...)",
  ui_story_5022_50220501_38_dialog_content = "(¿Pasó algo en ese entonces...?)",
  ui_story_5022_50220501_39_dialog_content = "A continuación, ¡tengo un anuncio importante! ¡De verdad esta vez!",
  ui_story_5022_50220501_40_dialog_content = "Primero, hemos confirmado las bengalas de señales de los concursantes que se han dado por vencidos.",
  ui_story_5022_50220501_41_dialog_content = "El Lepidoz pronto llegará a la ubicación de destino para recoger a todos ustedes, gatos miedosos, ¡así que siéntense tranquilos!",
  ui_story_5022_50220501_42_dialog_content = "Lo que es más sorprendente es que esta es la primera vez que hemos tenido tan pocas lesiones en esta carrera.",
  ui_story_5022_50220501_43_dialog_content = "Por lo tanto, vamos a animar las cosas revelando el misterioso premio de este año...",
  ui_story_5022_50220501_44_dialog_content = "<size=45>\"Pide un deseo de Eve\"!</size>",
  ui_story_5022_50220501_45_dialog_content = "¿Qué?",
  ui_story_5022_50220501_46_dialog_content = "¡Así es! llave inglesa redisel Eve hará realidad cualquier deseo tuyo!",
  ui_story_5022_50220501_47_dialog_content = "¿Deseará el ganador ver la sonrisa de la dama o pedir prestado el poder de la Estrella Oscura Necroide?",
  ui_story_5022_50220501_48_dialog_content = "¡Estoy deseando averiguarlo!",
  ui_story_5022_50220501_49_dialog_content = "Eve ni me avisaste...",
  ui_story_5022_50220501_50_dialog_content = "Te habrías opuesto, ¿no?",
  ui_story_5022_50220501_51_dialog_content = "¿Por qué lo haría?",
  ui_story_5022_50220501_52_dialog_content = "Verla completamente recuperada y dispuesta a ponerse al día con todas las cosas que se perdió...",
  ui_story_5022_50220501_53_dialog_content = "Y usando su poder para ayudar a todos... No podría estar más feliz.",
  ui_story_5022_50220501_54_dialog_content = "¿Ah, de verdad? Sabes que es \"cualquier deseo\", ¿verdad?",
  ui_story_5022_50220501_55_dialog_content = "Por ejemplo, ¿qué pasa si alguien desea casarse con ella?",
  ui_story_5022_50220501_56_dialog_content = "... ¿Eh?",
  ui_story_5022_50220501_57_option_content = "Esa es una posibilidad",
  ui_story_5022_50220501_58_dialog_content = "Eve es encantador y amable. Cualquiera querría protegerla.",
  ui_story_5022_50220501_59_dialog_content = "Cualquiera sería afortunado de acompañarla por el resto de sus vidas...",
  ui_story_5022_50220501_60_dialog_content = "¿¡Qué diablos estás pensando!?",
  ui_story_5022_50220501_61_dialog_content = "¡N-Nada!",
  ui_story_5022_50220501_62_option_content = "Lo dudo",
  ui_story_5022_50220501_63_dialog_content = "¿Qué? No crees que nuestro Eve es lo suficientemente bueno, ¿es eso?",
  ui_story_5022_50220501_64_dialog_content = "¡Por supuesto que ella es!",
  ui_story_5022_50220501_65_dialog_content = "Si realmente apareciera alguien que realmente la amaría, la atesoraría y la protegería con su vida...",
  ui_story_5022_50220501_66_dialog_content = "¿Qué hacer? Esa pequeña broma tiene Sinsa todos acurrucados en la consternación!",
  ui_story_5022_50220501_67_dialog_content = "Todo es tu culpa, PlayerName. ¡Di algo!",
  ui_story_5022_50220501_68_dialog_content = "¿¡Mi culpa!?",
  ui_story_5022_50220501_69_dialog_content = "¡Eh, tú! ¡Fuera del camino! Voy a toda velocidad aquí!",
  ui_story_5022_50220501_70_dialog_content = "¡De lo contrario, te enviaré volando!",
  ui_story_5022_50220501_71_dialog_content = "Técnicamente hablando, es \"Brock está sentado en el coche que Fleur está conduciendo a toda velocidad\".",
  ui_story_5022_50220501_72_dialog_content = "¡Oye, realmente te vas a caer por la borda si sigues inclinando tu cuerpo por la ventana de esa manera!",
  ui_story_5022_50220501_73_dialog_content = "Oh chico, aquí viene el problema...",
  ui_story_5022_50220501_74_dialog_content = "¡Oooooohh! no es eso PlayerName!?",
  ui_story_5022_50220501_75_dialog_content = "¡Estás un paso más cerca de convertirte en un individuo joven viril y apasionado al unirte al Blazing Rally! Pero, por supuesto, ¡todavía no eres rival para mí!",
  ui_story_5022_50220501_76_dialog_content = "Déjame ver... Tus compañeros de equipo son Joanie Boom y.... señorita Azure!?",
  ui_story_5022_50220501_77_dialog_content = "Mucho tiempo sin verlo, Brock. Parece que te has puesto algo de carne desde la última vez que nos vimos.",
  ui_story_5022_50220501_78_dialog_content = "Dios, sigues tan hermosa como siempre...",
  ui_story_5022_50220501_79_dialog_content = "Ah, quiero decir, ¡por supuesto! ¡Ya soy el segundo al mando de Rediesel Wrench!",
  ui_story_5022_50220501_80_dialog_content = "Soy el hombre más popular en Rediesel Wrench, ¡pero sigo entrenando todos los días! ¡Yo nunca me aflojo!",
  ui_story_5022_50220501_81_dialog_content = "Del mismo modo, incluso si voy a enfrentarte a ti en este rally, ¡aún triunfaré y obtendré el primer lugar!",
  ui_story_5022_50220501_82_dialog_content = "Después de todo, el gran premio estaba destinado a mí.",
  ui_story_5022_50220501_83_dialog_content = "¿El gran premio...?",
  ui_story_5022_50220501_84_dialog_content = "Sinsa?! ¿Qué estás haciendo aquí?",
  ui_story_5022_50220501_85_dialog_content = "¿Alguien más débil que yo es capaz de proteger a mi hermana? Prueba... Correcto. Debo ponerte a prueba.",
  ui_story_5022_50220501_86_dialog_content = "¿Por qué estás murmurando para ti mismo? Hmph, ¿es porque dije que soy el segundo al mando...?",
  ui_story_5022_50220501_87_dialog_content = "¿Por qué estás abriendo la puerta? ¡Oh, vamos! No debería haberme jactado, ¡pero no tienes que estar tan molesto!",
  ui_story_5022_50220501_88_dialog_content = "Extrañar Azure, que es eso detras Brock y el coche de Fleur?",
  ui_story_5022_50220501_89_dialog_content = "¡Lo que! ¡Si quieres una pelea, te daré una pelea!",
  ui_story_5022_50220501_90_dialog_content = "¡Te venceré en nuestro duelo 873 y eliminaré a tu equipo en el proceso!",
  ui_story_5022_50220501_91_dialog_content = "Espera, no es el momento de pelear... ¡Se acercan eclipses!",
  ui_story_5022_50220502_1_dialog_content = "¿No acabamos de derrotar a una ola de ellos? ¡Hay demasiados de ellos!",
  ui_story_5022_50220502_2_dialog_content = "¡Guau! ¡Mira el polvo que levantaron! ¡Es como una tormenta de arena!",
  ui_story_5022_50220502_3_dialog_content = "A pesar de que la arena está obstruyendo parcialmente mi vista, todavía puedo sentir Eclipses reuniéndose tanto delante como detrás de nosotros.",
  ui_story_5022_50220502_4_dialog_content = "¿Es esa la habilidad especial de tu especie? Muy bueno, Caelestite.",
  ui_story_5022_50220502_5_dialog_content = "no parece Sinsa y Brock van a parar...",
  ui_story_5022_50220502_6_dialog_content = "¿Eh? ¿Cuándo se subieron al auto?",
  ui_story_5022_50220502_7_dialog_content = "Bueno obviamente. ¡Ningún momento es malo para una pelea entre Rediesel Wrench!",
  ui_story_5022_50220502_8_dialog_content = "Ja, jóvenes de sangre caliente... Nunca son capaces de sostener sus caballos.",
  ui_story_5022_50220502_9_dialog_content = "Tal vez debería relajarme y divertirme...",
  ui_story_5022_50220502_10_dialog_content = "Me ocuparé de los Eclipsites en la parte de atrás. Caelestite, toma el volante.",
  ui_story_5022_50220502_11_dialog_content = "¡Cuenta conmigo! ¡Vamos, vamos a hacerlos volar por los aires!",
  ui_story_5022_50220502_12_dialog_content = "¿Me? Pero no sé manejar...",
  ui_story_5022_50220502_13_dialog_content = "¡Oye, no sueltes el volante así!",
  ui_story_5022_50220502_14_dialog_content = "Je, apenas puedo esperar. Entonces, ¿por dónde empezar?",
  ui_story_5022_50220502_15_dialog_content = "¡Déjame destrozarte a todos!",
  ui_story_5022_50220502_16_dialog_content = "Extrañar Azure, que debería...",
  ui_story_5022_50220502_17_dialog_content = "¿Mmm? No digas que has terminado. Recién estamos comenzando.",
  ui_story_5022_50220502_18_dialog_content = "(Cálmate... ¡Cálmate! Hay armas y explosiones, ¡pero cálmate!)",
  ui_story_5022_50220502_19_dialog_content = "(¡Usa tu instinto, gira la rueda y encuentra una manera de atravesarlos...!)",
  ui_story_5022_50220502_20_dialog_content = "Que estas esperando, PlayerName! ¡Golpea el acelerador, vamos!",
  ui_story_5022_50220502_21_dialog_content = "¡No olvides que soy un novato! ¡¿Cuál es el acelerador... esto?!",
  ui_story_5022_50220502_22_dialog_content = "Fleur¡Aceleremos también!",
  ui_story_5022_50220502_23_dialog_content = "Vaya. Subí al techo solo para lucir genial, pero esto realmente es alto...",
  ui_story_5022_50220502_24_dialog_content = "¡El tiempo es ahora!",
  ui_story_5022_50220502_25_dialog_content = "Brock, más te vale-",
  ui_story_5022_50220502_26_dialog_content = "-¡Comportarse!",
  ui_story_5022_50220502_27_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50220502_28_dialog_content = "Uf...",
  ui_story_5022_50220502_29_dialog_content = "Ey, Brock, si esquivas, el capó de Powerball quedará abollado.",
  ui_story_5022_50220502_30_dialog_content = "Pobre cosita. Dolía, ¿no? Me pregunto si tengo suficientes piezas para repararte.",
  ui_story_5022_50220502_31_dialog_content = "¿Hola? ¡Todavía estoy aquí, loco mecánico!",
  ui_story_5022_50220502_32_dialog_content = "¡Y no lo esquivé! ¡Esto es parte de mi estrategia! ¡Ahora estoy dando todo lo que tengo!",
  ui_story_5022_50220502_33_dialog_content = "Debes estar bien si todavía eres capaz de gritar así.",
  ui_story_5022_50220502_34_dialog_content = "Hemos perdido el control del coche, nos dirigimos directamente hacia esa roca.",
  ui_story_5022_50220502_35_dialog_content = "¿Ah?",
  ui_story_5022_50220502_36_dialog_content = "Sinsa, ¿te importa echar una mano ya que has decidido hacer autostop con nosotros?",
  ui_story_5022_50220502_37_dialog_content = "¡Lo hicimos!",
  ui_story_5022_50220502_38_dialog_content = "No hay más eclipses después de nosotros... Azure cuidar de todos esos Eclipsites?!",
  ui_story_5022_50220502_39_dialog_content = "¡Oye, ayudé! ¡Yo también quiero elogios!",
  ui_story_5022_50220502_40_dialog_content = "Simplemente esto ni siquiera es algo de lo que valga la pena regodearse. Los débiles no duran en el desierto.",
  ui_story_5022_50220502_41_dialog_content = "Sin embargo, eres más confiable de lo que esperaba, Caelestite. Eso estuvo bastante bien para ser la primera vez.",
  ui_story_5022_50220502_42_dialog_content = "¡Sí! ¿Quieres considerar registrarte como concursante formal la próxima vez...?",
  ui_story_5022_50220502_43_dialog_content = "Espera, si vas a competir de todos modos, ¿por qué no vas con todo y desafías el récord de Azure?",
  ui_story_5022_50220502_44_option_content = "ahora estoy interesado",
  ui_story_5022_50220502_45_dialog_content = "Oh, qué emocionante. Pero necesitarás más entrenamiento para ser un oponente satisfactorio para mí.",
  ui_story_5022_50220502_46_dialog_content = "(Ella luce feliz...)",
  ui_story_5022_50220502_47_option_content = "no soy tan bueno",
  ui_story_5022_50220502_48_dialog_content = "¿Tímidos, somos? Mientras estés dispuesto, estoy dispuesto a enseñarte cualquier cosa.",
  ui_story_5022_50220502_49_dialog_content = "(¡Tan cerca!)",
  ui_story_5022_50220502_50_dialog_content = "B-Por cierto, ¿no nos estamos olvidando de algo?",
  ui_story_5022_50220502_51_dialog_content = "*Tos, tos*",
  ui_story_5022_50220502_52_dialog_content = "A pesar de Sinsa logramos detener el auto, nos va a costar mucho tiempo reparar todo este daño.",
  ui_story_5022_50220502_53_dialog_content = "Espera, ¿todavía no vas a perder? Tu auto está literalmente echando humo.",
  ui_story_5022_50220502_54_dialog_content = "Nunca subestimes a un técnico. Mi objetivo es hacer mechs gigantes en el futuro. Arreglar un coche no es nada.",
  ui_story_5022_50220502_55_dialog_content = "Además, la forma en que saltaste desde la parte superior de ese auto me dio una nueva inspiración.",
  ui_story_5022_50220502_56_dialog_content = "Poner un sistema de propulsión vertical en el mecanismo podría ser una buena idea...",
  ui_story_5022_50220502_57_dialog_content = "Realmente te gustan los robots... Sin embargo, para ser honesto, eso suena bastante increíble.",
  ui_story_5022_50220502_58_dialog_content = "Una cosa más...",
  ui_story_5022_50220502_59_dialog_content = "¿Qué?",
  ui_story_5022_50220502_60_dialog_content = "Mira allá.",
  ui_story_5022_50220502_61_dialog_content = "<size=45>Sinsa! ¡Te dejaremos atrás si no te mueves!</size>",
  ui_story_5022_50220502_62_dialog_content = "¡Oye! ¡Espera!",
  ui_story_5022_50220502_63_dialog_content = "Guau, está corriendo a pie y alcanzando a un auto en marcha. Eso es Sinsa ¡para ti!",
  ui_story_5022_50220502_64_dialog_content = "¡Soy el hombre más rápido en Rediesel Wrench!",
  ui_story_5022_50220502_65_dialog_content = "¡Y ganaré el duelo 874 para tomar el puesto de primero al mando!",
  ui_story_5022_50220502_66_dialog_content = "La próxima vez definitivamente podré presumir frente a la señorita Azure!",
  ui_story_5022_50220502_67_dialog_content = "¡Jajaja! ¡Ese es el espíritu!",
  ui_story_5022_50220502_68_dialog_content = "Sin embargo, actualmente estamos varados en medio del desierto, así que...",
  ui_story_5022_50220502_69_dialog_content = "Pásame ese destornillador verde, ¿quieres? Piensa en ello como si estuvieras dando el primer paso en tu próximo duelo.",
  ui_story_5022_50220601_1_dialog_content = "Volar el vehículo de un oponente... ¿Así se supone que debe ser el Blazing Rally? Me pregunto cómo estarán los tres...",
  ui_story_5022_50220601_2_dialog_content = "¿Estás sintiendo un poco el atractivo de los autos de carreras ahora?",
  ui_story_5022_50220601_3_dialog_content = "Pensé que todo esto era solo un juego tonto para ti y no te lo estabas tomando tan en serio...",
  ui_story_5022_50220601_4_dialog_content = "¡Pero claramente te estás divirtiendo!",
  ui_story_5022_50220601_5_dialog_content = "Como dama, considero de etiqueta adaptarme al ardor de mis pretendientes.",
  ui_story_5022_50220601_6_dialog_content = "Tienes razón. Esto es un juego, pero no está destinado a ser jugado.",
  ui_story_5022_50220601_7_dialog_content = "Parecías realmente interesado mientras conducías. ¿Seguro que no quieres seguir?",
  ui_story_5022_50220601_8_dialog_content = "Eh, bueno.",
  ui_story_5022_50220601_9_dialog_content = "Oh, vamos, ¿ya retrocediendo? ¡No sabes cómo divertirte en absoluto!",
  ui_story_5022_50220601_10_dialog_content = "Sin embargo, aun así, definitivamente te entusiasmarás pronto. Jejeje!",
  ui_story_5022_50220601_11_dialog_content = "...¿Qué quieres decir?",
  ui_story_5022_50220601_12_dialog_content = "Porque... uf, eso estuvo cerca. Vamos a llegar a la etapa del volcán a continuación.",
  ui_story_5022_50220601_13_dialog_content = "¡Whoa!",
  ui_story_5022_50220601_14_dialog_content = "Oh, eres tú, Sinsa. Pensé que una roca que caía había aterrizado en el auto. ¿La gente normal entra a los autos saltando por las ventanas?",
  ui_story_5022_50220601_15_dialog_content = "Pfft, supongo que te pusiste al día.",
  ui_story_5022_50220601_16_dialog_content = "¿Acabas de burlarte de mí?",
  ui_story_5022_50220601_17_dialog_content = "no creo señorita Azure destinado a irse Sinsa detrás...",
  ui_story_5022_50220601_18_dialog_content = "Eres demasiado ingenuo, ¡ella definitivamente hablaba medio en serio al respecto! ¡Menos mal que soy un corredor rápido!",
  ui_story_5022_50220601_19_dialog_content = "Espera, ¿por qué siento que la atmósfera se calienta?",
  ui_story_5022_50220601_20_dialog_content = "Entramos en la segunda parte del rally, la <color=#FFB400>Volcán Aliento de Dragón</color>. Tenemos que pasar por este volcán.",
  ui_story_5022_50220601_21_dialog_content = "¿Me estás tomando el pelo? ¿¡Qué tipo de pista es esta!?",
  ui_story_5022_50220601_22_dialog_content = "No pasar por el volcán es la ruta más corta al Blazing Tooth, pero...",
  ui_story_5022_50220601_23_dialog_content = "No soñaría con no dejarte divertirte cuando acabas de aprender la belleza de las carreras.",
  ui_story_5022_50220601_24_dialog_content = "Somos prácticamente camaradas ahora, así que puedes tener la rueda cuando quieras intentarlo.",
  ui_story_5022_50220601_25_dialog_content = "¡N-No, gracias! ¡Todavía tengo caminos por recorrer!",
  ui_story_5022_50220601_26_dialog_content = "No seas tan humilde, PlayerName.",
  ui_story_5022_50220601_27_dialog_content = "Eres bueno en los juegos y un natural en la conducción. Imagina eso.",
  ui_story_5022_50220601_28_dialog_content = "(Oh, hablando de juegos...)",
  ui_story_5022_50220601_29_dialog_content = "(Me pregunto cómo Vice está haciendo.)",
  ui_story_5022_50220601_30_dialog_content = "(Siempre estuvimos juntos, experimentando todas esas aventuras maravillosas y peligrosas juntos).",
  ui_story_5022_50220601_31_dialog_content = "(... Si tan solo ella estuviera aquí.)",
  ui_story_5022_50220601_32_dialog_content = "¡Ackkk! ¡Pará pará pará! Lo lamento, Roy!",
  ui_story_5022_50220601_33_dialog_content = "Te dejo durante cinco segundos y decides empezar a correr la boca. ¿Olvidaste las cláusulas adicionales que mencioné tantas veces?",
  ui_story_5022_50220601_34_dialog_content = "Roy, ¡vamos! Solo oculté parte de la verdad para motivarlos mejor... ¡Ay! ¡Mi oído!",
  ui_story_5022_50220601_35_dialog_content = "Lo siento chicos. Permítanme aclarar algo: El anfitrión se reserva el derecho de determinar los parámetros del gran premio.",
  ui_story_5022_50220601_36_dialog_content = "Solo se puede conceder un deseo. Si hay desacuerdos entre el equipo, resuélvanlo entre ustedes sin recurrir a la violencia.",
  ui_story_5022_50220601_37_dialog_content = "Espero que todos ustedes hagan su mejor esfuerzo. May gana el mejor concursante, y sea quien sea, recomiendo reflexionar bien sobre lo que se quiere desear.",
  ui_story_5022_50220601_38_dialog_content = "Y no tire nada, porque yo mismo le romperé las piernas a cualquier tramposo. ¿Todos escucharon eso?",
  ui_story_5022_50220601_39_dialog_content = "N-Ahora, pongamos a todos al tanto de cómo va la carrera.",
  ui_story_5022_50220601_40_dialog_content = "Primero tenemos a Zeta, nuestro Dulce Diablo, el primero en llegar a la estación de servicio al pie del volcán.",
  ui_story_5022_50220601_41_dialog_content = "El estado del resto de los equipos seguirá pronto después de este breve comercial—",
  ui_story_5022_50220601_42_dialog_content = "Quieres saborear algo gourmet bajo los cerezos en flor...",
  ui_story_5022_50220601_43_dialog_content = "Dulce diesel! Barbara! ¡Guau!",
  ui_story_5022_50220601_44_dialog_content = "Huh, estoy escuchando algo de ruido de fondo...",
  ui_story_5022_50220601_45_dialog_content = "♪ Bendiciones de mi viaje en vientos fortuitos para ti ♪",
  ui_story_5022_50220601_46_dialog_content = "¿Quieres experimentar... el más supremo de los sabores?",
  ui_story_5022_50220601_47_dialog_content = "♪ Me saludas con la mano... Siempre estoy aquí esperando... ♪",
  ui_story_5022_50220601_48_dialog_content = "Entonces ven y prueba... ¡Delicioso! Kaniya Ramen!",
  ui_story_5022_50220601_49_dialog_content = "*Tose* Maldita sea...",
  ui_story_5022_50220601_50_dialog_content = "♪ La la la! ¡La la la! ¡Cántalo conmigo! ♪",
  ui_story_5022_50220601_51_dialog_content = "¡La la la! ¡La la la!",
  ui_story_5022_50220601_52_dialog_content = "La música está dominando el comercial real...",
  ui_story_5022_50220601_53_dialog_content = "Uf, bien. cariño diesel Barbara acoge un concierto de 300 canciones en el convoy junto al Lepidoz...",
  ui_story_5022_50220601_54_dialog_content = "Como parte del personal de entretenimiento del equipo de logística, ella...",
  ui_story_5022_50220601_55_dialog_content = "¡A ella no le importa en absoluto cómo casi me arrancan las orejas en el estudio hace un momento y ella acaba de comenzar su trabajo a la hora programada sin preocuparse en el mundo!",
  ui_story_5022_50220601_56_dialog_content = "De todos modos, dirijamos nuestra atención a este gran...",
  ui_story_5022_50220601_57_dialog_content = "¡Todo termina ahora!",
  ui_story_5022_50220601_58_dialog_content = "Puaj... Regina? ¡No sabía que iba a estar aquí!",
  ui_story_5022_50220601_59_dialog_content = "Jomu, realmente apestas a todo el mundo.",
  ui_story_5022_50220601_60_dialog_content = "La neutralidad es buena para los negocios. ¿Te importaría guardar esa sierra?",
  ui_story_5022_50220601_61_dialog_content = "No dejaré que tus horribles gritos arruinen los oídos de todos, Barbara!",
  ui_story_5022_50220601_62_dialog_content = "¡Te aplastaré con mi música abrasadora!",
  ui_story_5022_50220601_63_dialog_content = "Regina, crees que te tengo miedo?",
  ui_story_5022_50220601_64_dialog_content = "Barbara! Barbara!",
  ui_story_5022_50220601_65_dialog_content = "¡Tormenta solar! ¡Tormenta solar!",
  ui_story_5022_50220601_66_dialog_content = "♪ La la la! ¡Tu suerte, mi suerte! ¡Tomémonos de la mano! ♪",
  ui_story_5022_50220601_67_dialog_content = "¡Maldita sea, ella se me adelantó! ¡Gente, vamos a rockear!",
  ui_story_5022_50220601_68_dialog_content = "♪ ¡Rugido! ¡Rugido! ¿¡Quién puede salvarnos de este callejón sin salida!? ♪",
  ui_story_5022_50220601_69_dialog_content = "¡Santo cielo! ¡Apaga la estación! ¡Mi cerebro está a punto de explotar!",
  ui_story_5022_50220601_70_dialog_content = "Oh, ¿eso es todo lo que puedes tomar, Caelestite?",
  ui_story_5022_50220601_71_dialog_content = "Según las costumbres del Blazing Rally, lo bueno está por llegar.",
  ui_story_5022_50220601_72_dialog_content = "Mientras los pilotos corren para superarse, ¡el duelo de Diesel Sweety y Solar Storm llega a su clímax!",
  ui_story_5022_50220601_73_dialog_content = "Como puede escuchar, Diesel Sweety ha optado por ir con una melodía alegre. ¡Sus dulces notas altas pueden romper copas de vino!",
  ui_story_5022_50220601_74_dialog_content = "En cuanto a Solar Storm, ¡su canción está llegando a su coro publicitado!",
  ui_story_5022_50220601_75_dialog_content = "¿Cómo elegirá entregar esas notas estimulantes? Vamos a averiguar...",
  ui_story_5022_50220601_76_dialog_content = "¡Así es como! Ella va a... va a...",
  ui_story_5022_50220601_77_dialog_content = "Solar Storm no rompió la guitarra por su estilo dramático. ¡En cambio, ella lo arrojó!",
  ui_story_5022_50220601_78_dialog_content = "¡Solar Storm ha dejado el escenario!",
  ui_story_5022_50220601_79_dialog_content = "Tormenta solar... ¡Ha saltado al trofeo que obtuvo de la búsqueda de Lumopolis! ¡Un dirigible!",
  ui_story_5022_50220601_80_dialog_content = "¡Solar Storm tomó la aeronave... y va por la pared de roca!",
  ui_story_5022_50220601_81_dialog_content = "¡Hmph! Hojaldre frito! <size=45>¡Prueba la música real!</size>",
  ui_story_5022_50220601_82_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50220601_83_dialog_content = "¡¿Una explosión?!",
  ui_story_5022_50220601_84_dialog_content = "¿Dónde está el Lepidoz? No debería afectarnos...",
  ui_story_5022_50220601_85_dialog_content = "<color=#e8d9bb>Uf... ¡Ah!</color>",
  ui_story_5022_50220601_86_dialog_content = "Bueno, eso no es algo seguro de decir.",
  ui_story_5022_50220601_87_dialog_content = "¿Qué es ese sonido?",
  ui_story_5022_50220601_88_dialog_content = "¡La... la pared del acantilado de la izquierda se está derrumbando!",
  ui_story_5022_50220601_89_dialog_content = "Mantén la calma. Manténgase a la vanguardia del colapso y estaremos bien.",
  ui_story_5022_50220601_90_dialog_content = "¿Porque estas asustado? Sigue siendo seguro a la derecha, ¿no?",
  ui_story_5022_50220601_91_dialog_content = "Pero ya vamos a toda velocidad, y puedo sentir...",
  ui_story_5022_50220601_92_dialog_content = "¡Allí está lleno de eclipses!",
  ui_story_5022_50220602_1_dialog_content = "Oye. Ya puedes abrir los ojos. PlayerName?",
  ui_story_5022_50220602_2_dialog_content = "¿Qué debemos hacer? Parece que estás un poco conmocionado.",
  ui_story_5022_50220602_3_dialog_content = "Todavía estás demasiado verde. Te acostumbrarás cuando lo experimentes más.",
  ui_story_5022_50220602_4_dialog_content = "...¡En serio!",
  ui_story_5022_50220602_5_dialog_content = "¡Aquí vamos! Pero no hicimos nada. ¡Qué milagro médico!",
  ui_story_5022_50220602_6_dialog_content = "¿Más de esto? ¡Es un milagro que no estoy muerto!",
  ui_story_5022_50220602_7_dialog_content = "Algo tan pequeño no es un milagro.",
  ui_story_5022_50220602_8_dialog_content = "Me explicaré, ya que reservo un poco de paciencia para las linduras.",
  ui_story_5022_50220602_9_dialog_content = "Abre los ojos y mira la carretera con atención. Este lado es el acantilado, y ese lado es la pared de roca.",
  ui_story_5022_50220602_10_dialog_content = "Derecha. Ya veo.",
  ui_story_5022_50220602_11_dialog_content = "Este lugar está cerca del borde de la Noche Eterna. Los eclipses suelen esconderse a la sombra de la pared de roca para minimizar los costos de energía.",
  ui_story_5022_50220602_12_dialog_content = "Eso tiene sentido.",
  ui_story_5022_50220602_13_dialog_content = "Es decir, siempre que encontremos el ángulo correcto, podemos usar Eclipsites como amortiguadores de impacto.",
  ui_story_5022_50220602_14_dialog_content = "Ahora entiendo...",
  ui_story_5022_50220602_15_dialog_content = "¡NO!",
  ui_story_5022_50220602_16_dialog_content = "¡Usar Eclipsites como cojines está más allá del sentido común!",
  ui_story_5022_50220602_17_dialog_content = "PlayerName, no pienses. Siente, siéntelo con el corazón.",
  ui_story_5022_50220602_18_dialog_content = "¡Así es! Y confía señorita Azure, ella tiene esto!",
  ui_story_5022_50220602_19_dialog_content = "Ugh... Soy el único que cuestiona las cosas... Esto se siente tan mal...",
  ui_story_5022_50220602_20_dialog_content = "Vice...",
  ui_story_5022_50220602_21_dialog_content = "Vice... Te necesito aquí...",
  ui_story_5022_50220602_22_dialog_content = "(Si tan solo me hubiera disculpado con ella en ese entonces...)",
  ui_story_5022_50220602_23_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5022_50220602_24_dialog_content = "Caelestita? Caelestita? ¿Está ahí?",
  ui_story_5022_50220602_25_dialog_content = "¡¿De nuevo?!",
  ui_story_5022_50220602_26_dialog_content = "¿Q-Qué te pasó? ¿Comiste algo sucio del suelo? ¿O el calor te frió el cerebro?",
  ui_story_5022_50220602_27_dialog_content = "Um, quiero decir... ¿qué pasa, Zeta?",
  ui_story_5022_50220602_28_dialog_content = "¿Que pasa? Eres lento. ¡Demasiado lento! ¿Ya están cerca del volcán?",
  ui_story_5022_50220602_29_dialog_content = "¡Esta no es una pelea digna! ¡Es un lado borrando al otro!",
  ui_story_5022_50220602_30_dialog_content = "Entonces, ¿supongo que Miss Sweet Devil ya llegó a la meta?",
  ui_story_5022_50220602_31_dialog_content = "Jejeje, ya he salido del Lago de Magma. No esperabas eso, ¿¡verdad!?",
  ui_story_5022_50220602_32_dialog_content = "También obtuve el Amuleto de Frost para resistir el calor de Tiny One, el maestro de armas de los guerreros, en la estación de servicio!",
  ui_story_5022_50220602_33_dialog_content = "*sorbe*",
  ui_story_5022_50220602_34_dialog_content = "Qué es ese sonido...?",
  ui_story_5022_50220602_35_dialog_content = "¡Miss Sweet Devil es tan impresionante que me tiene temblando!",
  ui_story_5022_50220602_36_dialog_content = "Fingir que no te importa no funcionará. Yo también soy corredor, no me puedes engañar. Debes estar ansioso por alcanzarme.",
  ui_story_5022_50220602_37_dialog_content = "¡Lamentablemente, has estado fuera del juego durante demasiado tiempo y has perdido tu ventaja!",
  ui_story_5022_50220602_38_dialog_content = "¡Más importante aún, el miedo a la muerte y la derrota te ha devorado desde adentro hacia afuera!",
  ui_story_5022_50220602_39_dialog_content = "¡El corredor en ti se ha quemado, no quedan ni cenizas!",
  ui_story_5022_50220602_40_dialog_content = "Seré yo quien derrote al malvado dragón. ¡Yo también seré el campeón de la carrera!",
  ui_story_5022_50220602_41_dialog_content = "¡Sé testigo de mi victoria!",
  ui_story_5022_50220602_42_dialog_content = "Impresionante, no tartamudeé ni una sola vez y no me salté ninguna línea...!",
  ui_story_5022_50220602_43_dialog_content = "...Deberías verificar que tus comunicaciones estén apagadas antes de romper el carácter...",
  ui_story_5022_50220602_44_dialog_content = "Huh, ella debe haber practicado decir eso frente a un espejo. La entrega fue mucho más suave que su burla la última vez.",
  ui_story_5022_50220602_45_dialog_content = "Sinsa también compitió contra Zeta antes?",
  ui_story_5022_50220602_46_dialog_content = "Obtuvo el segundo lugar la última vez y me desafió directamente en el escenario.",
  ui_story_5022_50220602_47_dialog_content = "Realmente no entendí lo que estaba diciendo porque estaba teniendo un colapso.",
  ui_story_5022_50220602_48_dialog_content = "Afortunadamente para mí, Roy la apartó de mí...",
  ui_story_5022_50220602_49_dialog_content = "Aún así, eso fue una burla bastante brutal... Incluso Azure no tuvo regreso.",
  ui_story_5022_50220602_50_dialog_content = "Extrañar Azure...?",
  ui_story_5022_50220602_51_dialog_content = "La batalla de canciones de Solar Storm y Diesel Sweety se ha puesto en pausa momentáneamente.",
  ui_story_5022_50220602_52_dialog_content = "Ahora, volvamos nuestra atención a la carrera.",
  ui_story_5022_50220602_53_dialog_content = "Me emociona anunciar que los concursantes que llegaron al Volcán Aliento de Dragón, la segunda etapa de la carrera...",
  ui_story_5022_50220602_54_dialog_content = "<size=45>¡Son pocos en número!</size>",
  ui_story_5022_50220602_55_dialog_content = "Bien vale. Eso no es algo por lo que valga la pena chillar. Lo que realmente vale la pena mencionar es que...",
  ui_story_5022_50220602_56_dialog_content = "¡Algunos concursantes se sintieron tan atraídos por los comerciales de Kaniya Ramen y Octobro Shaved Ice que abandonaron el juego para satisfacer sus estómagos!",
  ui_story_5022_50220602_57_dialog_content = "¡Oh, no hay necesidad de estar decepcionado sin embargo!",
  ui_story_5022_50220602_58_dialog_content = "Los registros anteriores indican que solo los mejores logran atravesar el desierto de aire caliente.",
  ui_story_5022_50220602_59_dialog_content = "Los concursantes tienen que navegar tanto por el duro entorno como por la cooperación en equipo, que son desafíos increíbles por sí solos.",
  ui_story_5022_50220602_60_dialog_content = "¿Todavía recuerdas cómo descubrimos esta increíble ruta por pura casualidad porque nos perdimos?",
  ui_story_5022_50220602_61_dialog_content = "¡Realmente pensé que iba a morir durante la operación de búsqueda y rescate! ¡Jajaja!",
  ui_story_5022_50220602_62_dialog_content = "Recuerdo que alguien sugirió usar algunas tablas de desecho sacadas de los autos para deslizarse por la caída de magma...",
  ui_story_5022_50220602_63_dialog_content = "¿¡Caída de magma!?",
  ui_story_5022_50220602_64_dialog_content = "Mmm... No. No puedo recordar Pero también hubo un concursante que intentó congelar todo el Lago Magma...",
  ui_story_5022_50220602_65_dialog_content = "Y un concursante que cortó el auto de un oponente en seis pedazos con un cuchillo, pero de alguna manera el conductor salió solo con el ego herido...",
  ui_story_5022_50220602_66_dialog_content = "Lamentablemente, esos dos concursantes usaron nombres falsos y rara vez participan.",
  ui_story_5022_50220602_67_dialog_content = "Oh, cómo nos encantaría volver a verlos, pero estoy divagando.",
  ui_story_5022_50220602_68_dialog_content = "También hemos notado un aumento inusual en la actividad de Eclipsites esta vez.",
  ui_story_5022_50220602_69_dialog_content = "Los Eclipsites regulares no representan una amenaza para nuestros corredores experimentados...",
  ui_story_5022_50220602_70_dialog_content = "¡Pero! ¡El Dragón Malvado Hakudoma es una historia diferente!",
  ui_story_5022_50220602_71_dialog_content = "Si realmente apareciera, ¡deberíamos lanzar algunos recuerdos de Wicked Dragon de edición limitada para obtener ganancias!",
  ui_story_5022_50220602_72_dialog_content = "Por qué alguien querría eso...?",
  ui_story_5022_50220602_73_dialog_content = "Odi del Equipo de Logística 3 está monitoreando la región actual a través de la red de comunicaciones preinstalada en el Lepidoz.",
  ui_story_5022_50220602_74_dialog_content = "Hasta el momento, no hay signos de grandes eclipses.",
  ui_story_5022_50220602_75_dialog_content = "¡Qué reconfortante, pero decepcionante! ¡Ahora, una breve pausa comercial! Crunchy Munchy Crunch, un paquete sirve para tres comidas...",
  ui_story_5022_50220602_76_dialog_content = "...No?",
  ui_story_5022_50220602_77_dialog_content = "(Por que Azure parece un poco... ¿decepcionado?)",
  ui_story_5022_50220602_78_dialog_content = "Extrañar Azure, ¿esperas que aparezca Wicked Dragon Hakudoma?",
  ui_story_5022_50220602_79_dialog_content = "¿Es tan obvio?",
  ui_story_5022_50220602_80_dialog_content = "Caelestite, harías bien en no hurgar en mi cerebro.",
  ui_story_5022_50220602_81_dialog_content = "Sin embargo, ya que lo hiciste bastante bien cuando peleábamos contra los otros concursantes... te seguiré la corriente solo por esta vez.",
  ui_story_5022_50220602_82_dialog_content = "Esta pista en particular significa algo especial para mí.",
  ui_story_5022_50220602_83_dialog_content = "Fue aquí donde aprendí a conducir y participé en mi primer Blazing Rally, donde establecí nuevos récords una y otra vez.",
  ui_story_5022_50220602_84_dialog_content = "Mis mejores y peores recuerdos viven dentro de este lugar.",
  ui_story_5022_50220602_85_dialog_content = "Experimenté mi peor fracaso aquí, y me hice un enemigo que juré matar.",
  ui_story_5022_50220602_86_dialog_content = "Un día, romperé su cráneo, aplastaré su espina dorsal y lo convertiré en cenizas bajo mis pies.",
  ui_story_5022_50220602_87_dialog_content = "Esperaba que hoy fuera el día.",
  ui_story_5022_50220602_88_dialog_content = "No puede simplemente morir y desaparecer antes de que tenga la oportunidad de arrancarle las tripas.",
  ui_story_5022_50220602_89_dialog_content = "¿Qué? ¿Te asuste?",
  ui_story_5022_50220602_90_dialog_content = "Bastante...",
  ui_story_5022_50220602_91_dialog_content = "Es más que finalmente veo un atisbo de tu verdadero carácter.",
  ui_story_5022_50220602_92_dialog_content = "Puede que seas tonto y cobarde, pero seguro que sabes cómo complacer.",
  ui_story_5022_50220602_93_dialog_content = "¿Cuántos corazones has derretido con esas floridas palabras?",
  ui_story_5022_50220602_94_dialog_content = "Solo estaba diciendo la verdad...",
  ui_story_5022_50220602_95_dialog_content = "Pero, ¿por qué insistes tanto en luchar contra este Eclipsite en particular?",
  ui_story_5022_50220602_96_dialog_content = "Realmente disfrutas de una historia, ¿no es así, Caelestite?",
  ui_story_5022_50220602_97_dialog_content = "Quiero decir, se ha ido por más de una década.",
  ui_story_5022_50220602_98_dialog_content = "Tal vez debería preocuparme más por las locas demandas que hará Zeta si gana.",
  ui_story_5022_50220602_99_dialog_content = "¿Ella puede hacer eso? ¿Es eso parte del duelo?",
  ui_story_5022_50220602_100_dialog_content = "Es Zeta con quien estamos tratando aquí. Ella no te lo va a poner fácil.",
  ui_story_5022_50220602_101_dialog_content = "Oye, Caelestite, no lo digas como si no tuviera nada que ver contigo.",
  ui_story_5022_50220602_102_dialog_content = "Somos compañeros de equipo. Pase lo que pase, lo enfrentaremos todos juntos, ¿no?",
  ui_story_5022_50220602_103_dialog_content = "¿Ah?",
  ui_story_5022_50220602_104_dialog_content = "Creo que esta es mi parada aquí...",
  ui_story_5022_50220602_105_dialog_content = "Decir ah. No empieces a entrar en pánico todavía.|\nEl juego acaba de comenzar.",
  ui_story_5022_50220802_1_dialog_content = "¡Finalmente, la estación de mantenimiento! Estoy exhausto, todos esos Eclipsites fueron un verdadero dolor...",
  ui_story_5022_50220802_2_dialog_content = "Extrañar Azure¡Por fin estás aquí! Aparca tu coche aquí, por favor...",
  ui_story_5022_50220802_3_dialog_content = "¡Usted, compruebe si hay piezas que necesitan ser reemplazadas!",
  ui_story_5022_50220802_4_dialog_content = "En cuanto a los neumáticos... ¡Tú! ¡Así es, tú! ¡Saca los neumáticos!",
  ui_story_5022_50220802_5_dialog_content = "¡Y tú, levántate y muévete!",
  ui_story_5022_50220802_6_dialog_content = "¡Sí señor!",
  ui_story_5022_50220802_7_dialog_content = "Bien hecho, Tiny One. Sabes cómo hacer las cosas.",
  ui_story_5022_50220802_8_dialog_content = "Jeje.",
  ui_story_5022_50220802_9_dialog_content = "Es una pena que tu altura no coincida con tu autoridad...",
  ui_story_5022_50220802_9X1_dialog_content = "<size=45>¡Oye, oye! ¡Para!</size>",
  ui_story_5022_50220802_10_dialog_content = "¿Por qué no dejas de comentar sobre mi altura y...?",
  ui_story_5022_50220802_11_dialog_content = "¿Eh? PlayerName? Nunca pensé que te vería todo el camino hasta aquí.",
  ui_story_5022_50220802_12_dialog_content = "Alguien tan débil como tú logrando llegar tan lejos... Estoy impresionado.",
  ui_story_5022_50220802_13_dialog_content = "Eso no suena como un cumplido...",
  ui_story_5022_50220802_14_dialog_content = "No, espera. Lo que quise decir es que eres demasiado bajito para andar llamando débiles a las personas.",
  ui_story_5022_50220802_14X1_dialog_content = "<size=45>¡Oye! ¡Cortalo!</size>",
  ui_story_5022_50220802_15_dialog_content = "Bueno, eso es suficiente de esto. Se acercan los Magma Lake Life Enders. Esas curvas son la parte más difícil de la pista. ¿Estas listo para ellos?",
  ui_story_5022_50220802_16_dialog_content = "¡Ay! Espera... ¿Por qué se llama Magma Lake?",
  ui_story_5022_50220802_17_dialog_content = "Es justo lo que parece. Un lago de magma fundido.",
  ui_story_5022_50220802_18_dialog_content = "Quiero decir, esa parte era algo obvia...",
  ui_story_5022_50220802_S18_dialog_content = "Vale, vale, ¡estoy escuchando! ¡No me golpees!",
  ui_story_5022_50220802_19_dialog_content = "La temperatura del magma es lo suficientemente alta como para vaporizarte por completo si caes en él.",
  ui_story_5022_50220802_20_dialog_content = "El anfitrión proporcionó a los concursantes equipo para combatir el calor y los gases tóxicos, pero aún sentirás que estás respirando fuego.",
  ui_story_5022_50220802_21_dialog_content = "Entonces... ¿cómo lo superamos?",
  ui_story_5022_50220802_22_dialog_content = "¿Ya tienes miedo? Realmente no tienes remedio... Toma, toma esta bolsa de gelatina de cactus.",
  ui_story_5022_50220802_23_dialog_content = "Entonces esto me puede ayudar a combatir el calor? Las plantas del desierto son increíbles...",
  ui_story_5022_50220802_24_dialog_content = "Nada de ese tipo.",
  ui_story_5022_50220802_25_dialog_content = "¿Ah?",
  ui_story_5022_50220802_26_dialog_content = "Simplemente sabe bien. Eso es todo.",
  ui_story_5022_50220802_27_dialog_content = "¡Ahora, escuchemos los informes de los equipos!",
  ui_story_5022_50220802_28_dialog_content = "Ojalá pudiera hacer una pausa comercial, pero no tenemos tantos patrocinadores... Incluso he comercializado mis propios productos...",
  ui_story_5022_50220802_29_dialog_content = "*sorbe*",
  ui_story_5022_50220802_30_dialog_content = "Sweet Devil todavía tiene la delantera. Azure, el subcampeón, ¡todavía está a cierta distancia!",
  ui_story_5022_50220802_31_dialog_content = "Fuego Polar, Equipo Kafka, y otros concursantes eliminados han sido recogidos por Lepidoz y están siendo reparados.",
  ui_story_5022_50220802_32_dialog_content = "Si me perdí a alguien, es tu culpa por ser tan difícil de encontrar. ¡Esforzarse más!",
  ui_story_5022_50220802_33_dialog_content = "¡Escupe la sangre y sigue adelante! ¡Sé que puedes hacerlo! ¡No te detengas!",
  ui_story_5022_50220802_34_dialog_content = "Dando un excelente ejemplo para el resto de ustedes, My Super Dream Team ha sido reparado por Fleur y está de vuelta en el juego!",
  ui_story_5022_50220802_35_dialog_content = "Si no puede reparar sus juegos, espere a que lo rescaten. Chainsaw Rick y Rabbie!",
  ui_story_5022_50220802_36_dialog_content = "Si nada más, al menos podemos ayudarlo a desenterrar los restos de la arena, ¡para que no tenga nada de qué preocuparse!",
  ui_story_5022_50220802_37_dialog_content = "(Bien... Sabe bien. Pero no combatirá el calor y no es un amuleto de escarcha...)",
  ui_story_5022_50220802_38_dialog_content = "Zeta es imparable en esta carrera. Ha demostrado lo excelente conductora que es.",
  ui_story_5022_50220802_39_dialog_content = "¡Ella ha estudiado Blazing Tooth cuidadosamente con anticipación, lo que también la ha ayudado enormemente!",
  ui_story_5022_50220802_40_dialog_content = "(Llevaré algunos como recuerdo para todos en el Coloso).",
  ui_story_5022_50220802_41_dialog_content = "El resultado de esta carrera parece grabado en piedra... ¿Eh? Extrañar Odi? ¿Qué ocurre?",
  ui_story_5022_50220802_42_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5022_50220802_43_dialog_content = "Esto es Odi, supervisor de comunicaciones en el Equipo de Logística 3.",
  ui_story_5022_50220802_44_dialog_content = "Todos, escuchen.",
  ui_story_5022_50220802_45_dialog_content = "Tenemos problemas.",
  ui_story_5022_50220901_1_dialog_content = "Hemos detectado una gran cantidad de eclipses entre el volcán Dragon Breath y Blazing Tooth.",
  ui_story_5022_50220901_2_dialog_content = "Están levantando mucha arena y polvo, lo que los hace difíciles de rastrear...",
  ui_story_5022_50220901_3_dialog_content = "Pero después de comparar la velocidad y el tamaño de uno de ellos con los registros históricos, creemos que estamos ante un Eclipsita de tipo Dragón.",
  ui_story_5022_50220901_4_dialog_content = "Se mueve a lo largo de la vía, pero tenemos dificultades para contactar a Zeta debido a la arena y el polvo...",
  ui_story_5022_50220901_5_dialog_content = "Intentaré restablecer las comunicaciones con el personal de la zona. Los mantendré informados sobre cualquier novedad.",
  ui_story_5022_50220901_6_dialog_content = "¡Tened cuidado ahí fuera, patanes!",
  ui_story_5022_50220901_7_dialog_content = "Es... ¡Parece que un invitado sorpresa ha llegado durante las etapas finales del rally!",
  ui_story_5022_50220901_8_dialog_content = "Es el legendario Eclipsite, el Malvado...",
  ui_story_5022_50220901_9_dialog_content = "¡Ésto es una emergencia! ¡Estoy tomando el mando!",
  ui_story_5022_50220901_10_dialog_content = "Actualmente, Zeta solo tiene un camino a través del cañón frente a ella. Es probable que los Eclipsites la alcancen.",
  ui_story_5022_50220901_11_dialog_content = "¡...!",
  ui_story_5022_50220901_12_dialog_content = "Ella no será capaz de manejarlos por sí misma. Sin embargo, ese chico es uno de nuestros mejores...",
  ui_story_5022_50220901_13_dialog_content = "Entonces, aunque estará aterrorizada, debería poder resistir un poco.",
  ui_story_5022_50220901_14_dialog_content = "Los miembros del equipo de logística en el área de Blazing Tooth serán enviados para brindar apoyo inmediato.",
  ui_story_5022_50220901_15_dialog_content = "Necesitaremos tiempo para llegar allí en vehículos regulares. Azure, eres el concursante más cercano. Contamos contigo.",
  ui_story_5022_50220901_16_dialog_content = "Una vez que el Lepidoz llegue al área de comunicación, asignaré equipos para enfrentarse a los Eclipsites. Estén atentos para más pedidos.",
  ui_story_5022_50220901_17_dialog_content = "Roy suena tan tranquilo... Pero la situación es mala, ¿no?",
  ui_story_5022_50220901_18_dialog_content = "Tiny One, ¿puedes calcular la posición de Zeta a partir de cuándo salió de la estación de servicio?",
  ui_story_5022_50220901_19_dialog_content = "A juzgar por la velocidad a la que iba, debería estar muy cerca de la entrada del cañón.",
  ui_story_5022_50220901_20_dialog_content = "Tardará un poco en llegar. Incluso tendrás que reducir la velocidad al pasar por Magma Lake Life Enders...",
  ui_story_5022_50220901_21_dialog_content = "Por supuesto que no llegaremos a tiempo por la ruta normal.",
  ui_story_5022_50220901_22_dialog_content = "Maldita sea, si tan solo hubiera seguido mi ruta de patrulla a lo largo del pie del volcán en lugar de la pista...",
  ui_story_5022_50220901_23_dialog_content = "Bueno, ahora no hay tiempo para remordimientos...",
  ui_story_5022_50220901_24_dialog_content = "Caelestite, ya que puedes ver el flujo de luz, probablemente puedas crear una red sensorial con múltiples aurorianos, ¿verdad? ¿Como hiciste durante la batalla anterior?",
  ui_story_5022_50220901_25_dialog_content = "Claro... pero no veo cómo eso nos ayudará a sortear Magma Lake...",
  ui_story_5022_50220901_26_dialog_content = "Oh, creo que lo hará.",
  ui_story_5022_50220901_27_dialog_content = "Encontré una ruta que te dejará boquiabierto.",
  ui_story_5022_50220901_28_dialog_content = "¿Estás lista, Caelestite?",
  ui_story_5022_50220901_S28_dialog_content = "Supongo, pero...",
  ui_story_5022_50220901_29_dialog_content = "¿Cuántas veces he visto mi vida pasar ante mis ojos ahora...?",
  ui_story_5022_50220901_30_dialog_content = "Iré a toda velocidad hasta la cima.",
  ui_story_5022_50220901_31_dialog_content = "¿Realmente no hay otra manera? ¡Ahhhhhhhhh!",
  ui_story_5022_50220901_32_dialog_content = "<anim type=Shake><size=45>¡Vamos a volar!</size></anim>",
  ui_story_5022_50220901_32X1_dialog_content = "(Jo-Jo-Jo-Joanie—)",
  ui_story_5022_50220901_33_dialog_content = "Sinsa, ¿crees que ella pensó en esto? ¿Funcionará?",
  ui_story_5022_50220901_34_dialog_content = "En teoría, sí. Las matemáticas son buenas, pero...",
  ui_story_5022_50220901_35_dialog_content = "¿Lanzar bombas al aire, dispararlas y usar las explosiones para impulsar el automóvil a través del lago Magma?",
  ui_story_5022_50220901_36_dialog_content = "¡Es ridículo desde cualquier punto de vista!",
  ui_story_5022_50220901_37_dialog_content = "Oye es Azure y PlayerName estamos hablando aquí. ¡Funcionará!",
  ui_story_5022_50220901_38_dialog_content = "¡Allí están! ¡Mira hacia allá, sobre el lago Magma! Sheesh, están muy arriba, ¿no es así?",
  ui_story_5022_50220901_39_dialog_content = "¡Jejeje, este plan es tan divertido que no puede fallar!",
  ui_story_5022_50220901_40_dialog_content = "¡Solo porque te estás divirtiendo no tienes que anunciarlo a todos!",
  ui_story_5022_50220901_41_dialog_content = "¡Deja de mirarme! ¡Si les pasara algo, seré el primero en ir a rescatarlos!",
  ui_story_5022_50220901_42_dialog_content = "¡Esperar! PlayerName ¡Me está hablando telepáticamente!",
  ui_story_5022_50220901_43_dialog_content = "Bateador, ¿la pelota de béisbol...? No, ¿la llave inglesa está lista? ¡Voy a tirar las bombas!",
  ui_story_5022_50220901_44_dialog_content = "¡Tengo esto!",
  ui_story_5022_50220901_45_dialog_content = "(Ahora Sinsa! Muévelo a la ubicación que he marcado—)",
  ui_story_5022_50220901_46_dialog_content = "¡Muy bien, bombas fuera!",
  ui_story_5022_50220901_47_dialog_content = "bomba entrante, Azure! Listo-",
  ui_story_5022_50220901_47X1_dialog_content = "<size=45>¡¡Fuego!!</size>",
  ui_story_5022_50220901_47X2_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50220901_48_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5022_50220901_49_dialog_content = "¡Funcionó! Sólo unas pocas veces más...",
  ui_story_5022_50220901_50_dialog_content = "(Tengo que mantener el auto balanceado. Si me muevo un poco a la derecha... ¡Bien!)",
  ui_story_5022_50220901_51_dialog_content = "(Está bien. Incluso si sucediera lo peor...)",
  ui_story_5022_50220901_52_dialog_content = "¡Aaaah!",
  ui_story_5022_50220901_53_dialog_content = "¡PlayerName!",
  ui_story_5022_50220901_54_dialog_content = "(No mires hacia abajo... ¡No mires, no mires, no mires hacia abajo!)",
  ui_story_5022_50220901_55_dialog_content = "Oye, si de verdad quieres alejarte de mí, lo entiendo, pero este no es el mejor momento.",
  ui_story_5022_50220901_56_dialog_content = "¿O quieres que te deje ir?",
  ui_story_5022_50220901_57_dialog_content = "Deja de burlarte de mi, Azure... Eran...",
  ui_story_5022_50220901_58_dialog_content = "¿Hm...? En realidad no estamos cayendo tan rápido...",
  ui_story_5022_50220901_59_dialog_content = "¿Ves esas rocas de magma flotantes?",
  ui_story_5022_50220901_60_dialog_content = "El Volcán Aliento de Dragón es único porque los objetos que se acerquen a él flotarán a una corta distancia sobre el suelo.",
  ui_story_5022_50220901_61_dialog_content = "¡Whoa!",
  ui_story_5022_50220901_62_dialog_content = "Hermoso, ¿no es así? Sin embargo, a pesar de que hemos dejado atrás a nuestros dos pasajeros, todavía somos mucho más pesados que esas rocas.",
  ui_story_5022_50220901_63_dialog_content = "Así que, si no vuelves aquí y sigues adelante...",
  ui_story_5022_50220901_64_dialog_content = "¡Deberías haber dicho eso antes!",
  ui_story_5022_50220901_65_dialog_content = "¡Último golpe!",
  ui_story_5022_50220901_66_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50220901_67_dialog_content = "¡Vaya! ¡Viste eso! ¡Han llegado al otro lado del Lago Magma!",
  ui_story_5022_50220901_68_dialog_content = "Realmente lo hicieron. Ahora, esa es una ruta que pasa por Magma Lake que no se ha intentado antes...",
  ui_story_5022_50220901_69_dialog_content = "¡No tenemos tiempo para pensar en eso ahora! Ese eclipse de alto nivel...",
  ui_story_5022_50220901_70_dialog_content = "¿De qué estás hablando? ¡La carrera aún no ha terminado!",
  ui_story_5022_50220901_71_dialog_content = "Así es. ¡Acabamos de agregar una misión de búsqueda y rescate envuelta en un desafío de jefe con un lado de la caza de Eclipsite!",
  ui_story_5022_50220901_72_dialog_content = "Me pregunto cómo será luchar contra ese dragón... ¡Me emociono solo de pensarlo!",
  ui_story_5022_50220901_73_dialog_content = "Tiny One! ¡Tienes que salir de ese taller de vez en cuando, o tu cerebro se oxidará!",
  ui_story_5022_50220901_74_dialog_content = "¡Una fiesta sin invitados sorpresa no es una fiesta!",
  ui_story_5022_50220901_75_dialog_content = "¡Date prisa, o todo lo que obtendrás serán sobras!",
  ui_story_5022_50220901_76_dialog_content = "Bueno... Tenemos vehículos de reserva en la estación de mantenimiento...",
  ui_story_5022_50220901_77_dialog_content = "Cuenta conmigo. Alguien tiene que evitar que hagas algo estúpido.",
  ui_story_5022_50220901_78_dialog_content = "Entonces, ¿¡qué estamos esperando!? ¡Tiempo de fiesta!",
  ui_story_5022_50220901_79_dialog_content = "Destino: <color=#FFB400>Diente llameante</color>!",
  ui_story_5022_50221001_1_dialog_content = "Humph... No lo creo... ¡En realidad lo hicimos!",
  ui_story_5022_50221001_2_dialog_content = "No hay nada que me sorprenda -",
  ui_story_5022_50221001_3_dialog_content = "No, mejor no gafe... Sigo aquí con la llave inglesa Rediesel.",
  ui_story_5022_50221001_4_dialog_content = "¿Ver? Estás aprendiendo, PlayerName.",
  ui_story_5022_50221001_5_dialog_content = "(¿Se perdió Azure solo... ¿usar mi nombre?)",
  ui_story_5022_50221001_6_dialog_content = "(Dicho esto, cuando ella me agarró sobre Magma Lake, ella también...)",
  ui_story_5022_50221001_7_dialog_content = "¿Por qué sonríes?",
  ui_story_5022_50221001_8_dialog_content = "¡N-Nada! Estaba pensando que no hay manera Sinsa puede competir contigo cuando vas con todo!",
  ui_story_5022_50221001_9_dialog_content = "Bueno, te equivocas. Sinsa Detuve mi Colossus una vez usando solo una mano. Eso fue algo.",
  ui_story_5022_50221001_10_dialog_content = "No sé cómo decirlo, pero... Diría que eres un verdadero veterano de Rediesel Wrench.",
  ui_story_5022_50221001_11_dialog_content = "Lo tomaré como un cumplido. Esta carrera puede volverse un poco loca a veces, pero seguro que es adictiva, ¿no?",
  ui_story_5022_50221001_12_dialog_content = "Hablando de eso, tú mismo eres un poco loco.",
  ui_story_5022_50221001_13_dialog_content = "Allá atrás, contabas conmigo para sujetarte mientras intentabas equilibrar el auto, ¿verdad?",
  ui_story_5022_50221001_14_dialog_content = "Bueno, esa no era la apuesta más segura. No soy un jugador de equipo. ¿Y si no te hubiera alcanzado?",
  ui_story_5022_50221001_15_dialog_content = "Lo harías.",
  ui_story_5022_50221001_16_dialog_content = "Estoy acostumbrado a dar órdenes en una batalla, así que sé estas cosas.",
  ui_story_5022_50221001_17_dialog_content = "Aunque te quejes de que la gente se interponga en tu camino, siempre prestas atención a tus compañeros de equipo y sabes exactamente lo que están haciendo.",
  ui_story_5022_50221001_18_dialog_content = "No te pierdes nada.",
  ui_story_5022_50221001_19_dialog_content = "me halagas, PlayerName. Me gusta.",
  ui_story_5022_50221001_20_dialog_content = "¿Qué tal eso? Supongo que me gustas un poco.",
  ui_story_5022_50221001_21_dialog_content = "Oh, err...",
  ui_story_5022_50221001_22_dialog_content = "...",
  ui_story_5022_50221001_23_dialog_content = "Aún queda camino por recorrer antes de llegar a la entrada del cañón. Tiempo para una historia.",
  ui_story_5022_50221001_24_dialog_content = "Te preguntas qué pasó entre ese Eclipsite y yo, ¿verdad? Está escrito por toda la cara.",
  ui_story_5022_50221001_25_dialog_content = "...",
  ui_story_5022_50221001_26_dialog_content = "Me derrotó. No tuve oportunidad contra eso...",
  ui_story_5022_50221001_27_dialog_content = "Si Roy Si no hubiera llegado allí cuando lo hizo, no estaría aquí ahora.",
  ui_story_5022_50221001_28_dialog_content = "¡...!",
  ui_story_5022_50221001_29_dialog_content = "A pesar de que bromea al respecto todo el tiempo y les cuenta la historia a los niños como si fuera un cuento de hadas...",
  ui_story_5022_50221001_30_dialog_content = "Ambos sabemos que lo que pasó ese día nos marcó para siempre.",
  ui_story_5022_50221001_31_dialog_content = "Es difícil de imaginar, ¿verdad? El Rediesel Wrench apenas escapó de una emboscada de Eclipsite hace poco más de una década.",
  ui_story_5022_50221001_32_dialog_content = "Multitudes de monstruos intentaron rodear las líneas de defensa de Illumina a través del desierto... Ese Eclipsite fue uno de ellos.",
  ui_story_5022_50221001_33_dialog_content = "Perdí mi casa y muchos de mis amigos en esas batallas.",
  ui_story_5022_50221001_34_dialog_content = "Y me di por vencido en el rally.",
  ui_story_5022_50221001_35_dialog_content = "El entrenamiento para la batalla y la supervivencia parecía más importante que los juegos.",
  ui_story_5022_50221001_36_dialog_content = "Siempre he sido un lobo solitario porque no confío en mi capacidad para cuidar de mis camaradas.",
  ui_story_5022_50221001_37_dialog_content = "Patético, ¿no? Pero no quiero sentir esa... impotencia nunca más.",
  ui_story_5022_50221001_38_dialog_content = "Azur…",
  ui_story_5022_50221001_39_dialog_content = "Aunque he realizado una exploración peligrosa tras otra, todavía me preocupa no ser lo suficientemente bueno.",
  ui_story_5022_50221001_40_dialog_content = "¿Soy lo suficientemente bueno para luchar contra nuestros enemigos y proteger a las personas que más me importan?",
  ui_story_5022_50221001_41_dialog_content = "Si vuelvo a encontrarme con mi antiguo némesis, ¿será realmente diferente?",
  ui_story_5022_50221001_42_dialog_content = "Al igual que el rally, aunque he dicho que me he rendido...",
  ui_story_5022_50221001_43_dialog_content = "Todavía termino mis misiones temprano solo para escabullirme y verlo todo el tiempo...",
  ui_story_5022_50221001_44_dialog_content = "No soy tan confiable y capaz como crees que soy. solo soy un...",
  ui_story_5022_50221001_45_dialog_content = "Solo un aficionado.",
  ui_story_5022_50221001_46_dialog_content = "No eres nada por el estilo.",
  ui_story_5022_50221001_47_dialog_content = "No hay nada de malo en disfrutar de lo que amas.",
  ui_story_5022_50221001_48_dialog_content = "Esto puede sonar extraño viniendo de un extraño, pero...",
  ui_story_5022_50221001_49_dialog_content = "¿No es el principio de Rediesel Wrench vivir la vida al máximo?",
  ui_story_5022_50221001_50_dialog_content = "Los que conozco tratarían cualquier peligro como una oportunidad para divertirse.",
  ui_story_5022_50221001_51_dialog_content = "Ahora que lo dices... Casi puedo ver el rostro de Joanie radiante de emoción.",
  ui_story_5022_50221001_52_dialog_content = "Y al igual que mis amigos y yo confiamos el uno en el otro, la llave inglesa Rediesel nunca te dejaría enfrentarte a tu némesis solo.",
  ui_story_5022_50221001_53_dialog_content = "Quiero decir... Obviamente ahora mismo soy solo yo, pero...",
  ui_story_5022_50221001_54_dialog_content = "Te ayudaré en todo lo que pueda, aunque no sé cómo usar Luminatics.",
  ui_story_5022_50221001_55_dialog_content = "Entonces, en las próximas batallas, ¡puedes confiar en mí!",
  ui_story_5022_50221001_56_dialog_content = "PlayerName...",
  ui_story_5022_50221001_57_dialog_content = "Ahora me siento avergonzado de haber parloteado sobre mi pasado...",
  ui_story_5022_50221001_58_dialog_content = "Pero... sabía que te tenía echado el ojo por una razón. Tu eres una buena persona.",
  ui_story_5022_50221001_59_dialog_content = "Estamos casi en la entrada del cañón. Zeta probablemente esté llorando como un bebé en este momento.",
  ui_story_5022_50221001_60_dialog_content = "Por cierto... Roy incluso fingió ser una princesa para las historias de Zeta...",
  ui_story_5022_50221001_61_dialog_content = "Pero cuando ella está en peligro de muerte, ¿él cree que puede defenderse hasta que lleguemos allí?",
  ui_story_5022_50221001_62_dialog_content = "Rediesel Wrench seguro que ofrece un tipo salvaje de educación...",
  ui_story_5022_50221001_63_dialog_content = "Es como él dijo, Zeta es uno de los mejores.",
  ui_story_5022_50221001_64_dialog_content = "Pero aun así no deberíamos hacerla esperar demasiado. Será mejor que acabemos con estos eclipses y nos pongamos en marcha.",
  ui_story_5022_50221001_65_dialog_content = "Mostrémosles lo que tenemos, PlayerName!",
  ui_story_5022_50221101_1_dialog_content = "¿Ves esa masa negra de Eclipses?",
  ui_story_5022_50221101_2_dialog_content = "Eww... Se mueven como gusanos cuando se juntan así. Repugnante...",
  ui_story_5022_50221101_3_dialog_content = "¡Vamos a hacerlos volar por los aires! Estaba buscando una oportunidad para calibrar mis nuevas bombas. ¡Pero el malvado dragón es mío!",
  ui_story_5022_50221101_4_dialog_content = "No hay problema. Ese eclipse de alto nivel no está entre ellos.",
  ui_story_5022_50221101_5_dialog_content = "Debe haber seguido a Zeta al interior del cañón. Es sorprendentemente rápido...",
  ui_story_5022_50221101_6_dialog_content = "El resto de los Eclipsites parecen estar moviéndose hacia el centro.",
  ui_story_5022_50221101_7_dialog_content = "¿Están tratando de frenar a la señorita? Azure? Está muy lejos para decir...",
  ui_story_5022_50221101_8_dialog_content = "<color=#e8d9bb>Crujido... Crujido...</color>",
  ui_story_5022_50221101_9_dialog_content = "Tiny One, ¿Puedes oírme?",
  ui_story_5022_50221101_10_dialog_content = "Roy! ¡Te escucho! mandamás Sinsa y Joanie Boom también están aquí conmigo. ¿Qué necesitas?",
  ui_story_5022_50221101_11_dialog_content = "Sinsa? ¿No debería estar con Azure...?",
  ui_story_5022_50221101_12_dialog_content = "No importa. Es mejor así... Puedes causar serios estragos de esta manera.",
  ui_story_5022_50221101_13_dialog_content = "Muévase detrás de ellos, luego capte su atención y destrúyalos. tenemos que dar Azure una oportunidad de abrirse paso.",
  ui_story_5022_50221101_14_dialog_content = "¿Cómo es eso de un plan, líder?",
  ui_story_5022_50221101_15_dialog_content = "vamos a dejar Azure Sé el héroe esta vez... Ella puede tener esta fiesta, ¡pero solo esta!",
  ui_story_5022_50221101_16_dialog_content = "Sé que ya has escuchado esto, y probablemente no haya nada de qué preocuparse si el líder está aquí... Pero me gustaría recordarte...",
  ui_story_5022_50221101_17_dialog_content = "Elimine esos gusanos de sandía primero para evitar picos. ¡Protege nuestro viaje!",
  ui_story_5022_50221101_18_dialog_content = "¡Y deshazte de esos molestos trapeadores peludos que también pueden curar a otros Eclipsites! ¡Termina con todos!",
  ui_story_5022_50221101_19_dialog_content = "Esos monstruos del globo ocular que parecen huevos mal cocidos pueden ser un verdadero dolor de cabeza, porque siguen convocando a sus súbditos. Destrúyelos tan pronto como puedas. ¿Entiendo?",
  ui_story_5022_50221101_20_dialog_content = "Err... ¿Qué más...",
  ui_story_5022_50221101_21_dialog_content = "Mantén tu distancia de Mega Fists. Y ten mucho cuidado con los pulpos voladores: intentarán desincronizarnos.",
  ui_story_5022_50221101_22_dialog_content = "... Roy, acabas de suspirar? Corrígeme si dije algo mal.",
  ui_story_5022_50221101_23_dialog_content = "No, no, estás haciendo un trabajo fabuloso. Es solo que... Es increíble lo rápido que crecen los niños...",
  ui_story_5022_50221101_24_dialog_content = "Kafka y Sork se unirá a usted en breve. Hágase cargo de la batalla, líder. |\nDivertirse.",
  ui_story_5022_50221101_25_dialog_content = "¡Aaaaaahhh! Púdrete, Barbara¡Arruinaste mi concierto en solitario otra vez!",
  ui_story_5022_50221101_26_dialog_content = "¡¡Graaaah!!",
  ui_story_5022_50221101_27_dialog_content = "¡Callarse la boca! ¡Caerse y quedarse abajo! Solo Requiem!",
  ui_story_5022_50221101_28_dialog_content = "¿Vaya? Tu concierto, ¿verdad? ¡Disculpe, pero creo que todos están aquí por mí!",
  ui_story_5022_50221101_29_dialog_content = "¿Listo? ¡Dulce beso!",
  ui_story_5022_50221101_30_dialog_content = "¿Ah, de verdad? ¿A quién demonios le gustan tus estúpidas canciones de amor?",
  ui_story_5022_50221101_31_dialog_content = "Diría que tus gritos implacables son un poco más duros para los oídos.",
  ui_story_5022_50221101_32_dialog_content = "¿Estás buscando pelea?",
  ui_story_5022_50221101_33_dialog_content = "¡Si eso es lo que quieres, no tendría el corazón para decir que no!",
  ui_story_5022_50221101_34_dialog_content = "*Tos* Siento interrumpir.",
  ui_story_5022_50221101_35_dialog_content = "Ustedes dos se separaron de Lepidoz y rodearon el volcán para atacar a través del desierto del norte. Debes estar subiendo a los Eclipsites, ¿verdad?",
  ui_story_5022_50221101_36_dialog_content = "Eres muy lento, Roy. Hemos estado en acción por un tiempo. Se supone que debemos quemarlos a todos, ¿verdad?",
  ui_story_5022_50221101_37_dialog_content = "Psh... Todos son pequeños, es aburrido.",
  ui_story_5022_50221101_38_dialog_content = "Una vez en una luna azul, estoy de acuerdo contigo.",
  ui_story_5022_50221101_39_dialog_content = "Pero cumpliré cualquier misión que me encomienden, por trivial que sea. ¡Los súper ídolos tienen una ética de trabajo superior!",
  ui_story_5022_50221101_40_dialog_content = "Bueno, lo siento, pero mantener al enemigo bajo control y evitar que más Eclipsites inunden el cañón es realmente una tarea importante.",
  ui_story_5022_50221101_41_dialog_content = "Oye, ¿cómo suena esto? Quien destruya más Eclipsites puede tener una actuación en solitario en el próximo concierto de Fiery Support.",
  ui_story_5022_50221101_42_dialog_content = "!",
  ui_story_5022_50221101_43_dialog_content = "Y el cantante puede elegir cualquier lugar, incluso Lepidoz o el Oasis.",
  ui_story_5022_50221101_44_dialog_content = "¡Guau! ¿Estas seguro acerca de esto?",
  ui_story_5022_50221101_45_dialog_content = "Si elijo el Oasis, ¡puedo usar efectos de luz fantásticos y de ensueño! Me emociono solo de pensarlo...",
  ui_story_5022_50221101_46_dialog_content = "Emm... Pero un concierto en un Lepidoz en movimiento también es una rara oportunidad...",
  ui_story_5022_50221101_47_dialog_content = "¡Ey! Regina! ¡No saltes el arma!",
  ui_story_5022_50221101_48_dialog_content = "Uf... Ahora, ¿qué sigue...",
  ui_story_5022_50221101_49_dialog_content = "Azure, los eclipses comienzan a dispersarse. ¡Podremos salir pronto!",
  ui_story_5022_50221101_50_dialog_content = "¿La ayuda provino de la llave Rediesel?",
  ui_story_5022_50221101_51_dialog_content = "Los eclipses no perderían interés en nosotros así como así. Para que el enemigo se disperse tan rápido... esto tiene que ser obra de Roy.",
  ui_story_5022_50221101_52_dialog_content = "Um, parece que tenemos un mensaje entrante.",
  ui_story_5022_50221101_53_dialog_content = "Hola...?",
  ui_story_5022_50221101_54_dialog_content = "Adiós.",
  ui_story_5022_50221101_55_dialog_content = "¿Qué...?",
  ui_story_5022_50221101_56_dialog_content = "¡Esperar! Ahora, eso es frío. ¡Y pensé que era como una madre para ti!",
  ui_story_5022_50221101_57_dialog_content = "Vamos, eres demasiado viejo para eso. Ten un poco de respeto por ti mismo.",
  ui_story_5022_50221101_58_dialog_content = "Tos... Cierto. Asi que...",
  ui_story_5022_50221101_59_dialog_content = "... Roy.",
  ui_story_5022_50221101_60_dialog_content = "Sé lo que vas a decir. No te preocupes, ya lo he visto yo mismo.",
  ui_story_5022_50221101_61_dialog_content = "La Llave Rediesel solía temer a los Eclipsites porque fue derrotada por ellos. Pero durante la última década, ha cambiado...",
  ui_story_5022_50221101_62_dialog_content = "Y yo también.",
  ui_story_5022_50221101_63_dialog_content = "¿Derecha?",
  ui_story_5022_50221101_64_dialog_content = "Azur…",
  ui_story_5022_50221101_65_dialog_content = "La única forma en que puedo salir de esa sombra inquietante del pasado es terminar esto yo mismo.",
  ui_story_5022_50221101_66_dialog_content = "Así que si tienes algo que decir, guárdalo para mi regreso triunfal.",
  ui_story_5022_50221101_67_dialog_content = "… Ya veo. Te hemos abierto un camino.",
  ui_story_5022_50221101_68_dialog_content = "Feliz cacería.",
  ui_story_5022_50221201_1_dialog_content = "<color=#e8d9bb>Hace más de diez años</color>",
  ui_story_5022_50221201_2_dialog_content = "gaar...",
  ui_story_5022_50221201_3_dialog_content = "Huff... Wheeze... Esto no tiene fin...",
  ui_story_5022_50221201_4_dialog_content = "Ghaaar...",
  ui_story_5022_50221201_5_dialog_content = "Parece que ese imbécil planea agotarme antes de hacer su movimiento...",
  ui_story_5022_50221201_6_dialog_content = "(Dibujarlo usando el auto claramente no va a funcionar... Pero si fallo, todos lo harán...)",
  ui_story_5022_50221201_7_dialog_content = "... ¿Qué? ¡Repitelo!",
  ui_story_5022_50221201_8_dialog_content = "Me escuchaste bien.",
  ui_story_5022_50221201_9_dialog_content = "¿Qué quieres decir con que el líder no viene, Roy? ¡Mírame!",
  ui_story_5022_50221201_10_dialog_content = "La crisis está lejos de terminar. Pueden ganarnos algo de tiempo con sus vidas, pero esos Eclipsites que destruyeron nuestra base pronto nos alcanzarán.",
  ui_story_5022_50221201_11_dialog_content = "Uno de los Eclipsites parece un dragón. Se mueve extremadamente rápido. Intentaré alejarlo. Sinsa, llevar...",
  ui_story_5022_50221201_12_dialog_content = "¿Por qué volviste solo? Por qué...",
  ui_story_5022_50221201_13_dialog_content = "Yo también quisiera ser yo el que muriera, Azure.",
  ui_story_5022_50221201_14_dialog_content = "Una vez que superemos esto, puedes golpearme tan fuerte como quieras. Pero ahora mismo... ¡Oye! ¿Adónde vas?",
  ui_story_5022_50221201_15_dialog_content = "(Le dije algunas cosas bastante malas allá atrás. Espero tener la oportunidad de disculparme...)",
  ui_story_5022_50221201_16_dialog_content = "(Debería poder golpear desde detrás de esta cubierta...)",
  ui_story_5022_50221201_17_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5022_50221201_18_dialog_content = "Ahh...!",
  ui_story_5022_50221201_19_dialog_content = "(Mierda... ¡Ni siquiera penetró la piel exterior!)",
  ui_story_5022_50221201_20_dialog_content = "(El arma... Necesito recuperar mi arma...)",
  ui_story_5022_50221201_21_dialog_content = "Jaja... Realmente duele...",
  ui_story_5022_50221201_22_dialog_content = "(No puedo... moverme...)",
  ui_story_5022_50221201_23_dialog_content = "(¿Me rompí un hueso cuando golpeé la roca antes? ¿O su rugido de alguna manera me adormeció los nervios?)",
  ui_story_5022_50221201_24_dialog_content = "(Concéntrate en el presente. No puedo rendirme todavía... No puedo...)",
  ui_story_5022_50221201_25_dialog_content = "<anim type=Shake><size=45>¡Rugido!</size></anim>",
  ui_story_5022_50221201_26_dialog_content = "(No... Mi conciencia... se está desvaneciendo...)",
  ui_story_5022_50221201_27_dialog_content = "(¿Los demás lograron escapar?)",
  ui_story_5022_50221201_28_dialog_content = "(¿Voy a morir aquí?)",
  ui_story_5022_50221201_29_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5022_50221201_30_dialog_content = "<size=45>¡Gaar, ahhhhhh!</size>",
  ui_story_5022_50221201_31_dialog_content = "(¿Fue eso... una explosión?)",
  ui_story_5022_50221201_32_dialog_content = "Tos... Ah-hahah... Parece que... Lo hice justo a tiempo.",
  ui_story_5022_50221201_33_dialog_content = "Roy! Tú...",
  ui_story_5022_50221201_34_dialog_content = "¿Qué pasa con esa cara? Pensé... Hngh... Pensé que estarías más feliz de verme.",
  ui_story_5022_50221201_35_dialog_content = "La situación está actualmente bajo control, pero nuestra potencia de fuego no puede mantener al enemigo a raya por mucho tiempo...",
  ui_story_5022_50221201_36_dialog_content = "Ah... Estás... *Tos* Preocupado por esto...",
  ui_story_5022_50221201_37_dialog_content = "Ouch... No pensé que tenía suficiente fuerza para atacarte...",
  ui_story_5022_50221201_38_dialog_content = "Sí, duele un poco... Pero no es nada que una buena noche de sueño no pueda solucionar...",
  ui_story_5022_50221201_39_dialog_content = "Después de todo, soy bastante sólido y robusto.",
  ui_story_5022_50221201_40_dialog_content = "Cállate. Si sigues hablando, tu herida...",
  ui_story_5022_50221201_41_dialog_content = "Los otros han... Alcanzado la seguridad. Había una especie de lagarto...",
  ui_story_5022_50221201_42_dialog_content = "pero envié Sinsa para comprobarlo... Así que no te preocupes...",
  ui_story_5022_50221201_43_dialog_content = "Dame unos segundos más... Déjame recuperar algo de fuerza...",
  ui_story_5022_50221201_44_dialog_content = "Puedo congelar la garra. ¡Se volverá quebradizo para que pueda romperlo!",
  ui_story_5022_50221201_45_dialog_content = "… Muy fiable.",
  ui_story_5022_50221201_46_dialog_content = "No como yo, sin cerebro... El líder me regañará duramente con seguridad...",
  ui_story_5022_50221201_47_dialog_content = "...",
  ui_story_5022_50221201_48_dialog_content = "Oh... No... No lo hará... Casi lo olvido... Ya se fue...",
  ui_story_5022_50221201_49_dialog_content = "Ya que ni el Eclipsite ni nosotros podíamos movernos en este momento, yo... Tos... Debo presentar una queja.",
  ui_story_5022_50221201_50_dialog_content = "¿De verdad crees que este es un buen momento para predicar?",
  ui_story_5022_50221201_51_dialog_content = "No habrá predicación. Pero, ¿cuántas veces te he dicho que no te vayas solo y trates de demostrar lo valiente que eres?",
  ui_story_5022_50221201_52_dialog_content = "Te he enseñado demasiado bien. No podría alcanzarte en un auto aunque lo intentara... Tendré que practicar más...",
  ui_story_5022_50221201_53_dialog_content = "El líder... me hizo prometer que os mantendría a salvo a ti y a la llave Rediesel. Seguro que a ese tipo le encantaba mandar a la gente...",
  ui_story_5022_50221201_54_dialog_content = "Me dijo... Je... Que tenía que cumplir mi promesa por cien años.",
  ui_story_5022_50221201_55_dialog_content = "Me duele la cabeza solo de pensar en convertir a este grupo de idiotas y bandidos errantes en amos del desierto.",
  ui_story_5022_50221201_56_dialog_content = "Claro, fueron sus últimas palabras, pero... está pidiendo mucho.",
  ui_story_5022_50221201_57_dialog_content = "Así que... voy a necesitar que te quedes.",
  ui_story_5022_50221201_58_dialog_content = "Tenemos demasiado en nuestro plato para morir aquí.",
  ui_story_5022_50221201_59_dialog_content = "¡No tienes que decirme eso! Ahora cállate, necesito concentrarme para controlar el rango de mi Luminatics.",
  ui_story_5022_50221201_60_dialog_content = "jajaja Tos... Parece que alguien ha descansado lo suficiente.",
  ui_story_5022_50221201_61_dialog_content = "Vamos a casa.",
  ui_story_5022_50221201_62_dialog_content = "Construiremos una nueva fortaleza... En algún lugar con agua y muchos árboles...",
  ui_story_5022_50221202_1_dialog_content = "Eh... señorita Azure?",
  ui_story_5022_50221202_2_dialog_content = "Nada que una buena noche de sueño no solucione... Ja, estuvo fuera durante más de una semana seguida...",
  ui_story_5022_50221202_3_dialog_content = "¿Quién exactamente estaba tratando de ser valiente?",
  ui_story_5022_50221202_4_dialog_content = "... Extrañar Azure? Extrañar Azure?",
  ui_story_5022_50221202_5_dialog_content = "¿Qué fue eso?",
  ui_story_5022_50221202_6_dialog_content = "Pareces distante. Y has estado murmurando para ti mismo mientras aceleras... ¿Estás bien?",
  ui_story_5022_50221202_7_dialog_content = "Yo sólo... Recordé algo del pasado.",
  ui_story_5022_50221202_8_dialog_content = "No te preocupes. Podría conducir esta pista con los ojos cerrados.",
  ui_story_5022_50221202_8X_dialog_content = "Preferiría que los mantuvieras abiertos...",
  ui_story_5022_50221202_9_dialog_content = "Puedo sentir ese eclipse de alto nivel. Está muy cerca de nosotros.",
  ui_story_5022_50221202_10_dialog_content = "Su Darkflow se siente familiar. De una manera muy inquietante...",
  ui_story_5022_50221202_11_dialog_content = "Hemos entrado en el cañón. La arena no afectará tanto a nuestro equipo de comunicaciones aquí... Podríamos llegar a Zeta...",
  ui_story_5022_50221202_12_dialog_content = "<color=#e8d9bb>Crujido... Crujido...</color>",
  ui_story_5022_50221202_13_dialog_content = "Boo-hoo... ¡Ahhhhhh!",
  ui_story_5022_50221202_14_dialog_content = "¿Hay alguien ahí? Necesito ayuda...",
  ui_story_5022_50221202_15_dialog_content = "Zeta! Gracias a dios. ¿Estás bien?",
  ui_story_5022_50221202_16_dialog_content = "¿Se ha restablecido la comunicación? Caelestita! ¿Eres tu?",
  ui_story_5022_50221202_17_dialog_content = "Yo, yo...",
  ui_story_5022_50221202_18_dialog_content = "¡Estoy solly! ¡Wahhh!",
  ui_story_5022_50221202_19_dialog_content = "Eso es... muy fuerte.",
  ui_story_5022_50221202_20_dialog_content = "¡Lo siento! Quería... *Sniff*... Quería hacerme amigo de todos.",
  ui_story_5022_50221202_21_dialog_content = "Quería jugar con los demás... *sollozo* Sólo hice problemas *olfatear* para que la gente me notara...",
  ui_story_5022_50221202_22_dialog_content = "¡Waaaah! Lo siento, Maggie... Estamos en el mismo equipo, pero te hice tantas bromas...",
  ui_story_5022_50221202_23_dialog_content = "Y y Tiny One, Kafka, Rabbie, Odi, Jomu, Clover, Chainsaw Rick, y Sork...",
  ui_story_5022_50221202_24_option_content = "Son muchas disculpas que hacer...",
  ui_story_5022_50221202_25_dialog_content = "¡No he terminado aún! Hay muchos más en la Llave Rediesel…",
  ui_story_5022_50221202_26_dialog_content = "Como Scorching Jinx, Tempest Emperor, Dusk Phoenix, Fallen Warwraith... Waaah...",
  ui_story_5022_50221202_27_dialog_content = "(Nunca he oído hablar de esas personas...)",
  ui_story_5022_50221202_28_option_content = "Zeta, cálmate un minuto...",
  ui_story_5022_50221202_29_dialog_content = "¡No!",
  ui_story_5022_50221202_30_dialog_content = "(Supongo que la dejaré terminar...)",
  ui_story_5022_50221202_31_dialog_content = "*Sollozo*... Azure...",
  ui_story_5022_50221202_32_dialog_content = "Avanzar. Estoy escuchando.",
  ui_story_5022_50221202_33_dialog_content = "La única razón por la que sigo causándote problemas es porque estoy celoso.",
  ui_story_5022_50221202_34_dialog_content = "Eres tan bueno en todo. Y Roy confía en ti más que nadie...",
  ui_story_5022_50221202_35_dialog_content = "Es por eso que siempre trato de encontrar fallas contigo...",
  ui_story_5022_50221202_36_dialog_content = "Debajo de mi cama hay una caja de hojalata. Contiene todos los dulces que he coleccionado a lo largo de los años.",
  ui_story_5022_50221202_37_dialog_content = "Azure... *Sniff*... Lo tomas y lo compartes con todos...",
  ui_story_5022_50221202_38_dialog_content = "Entiendo. ¿Algo más?",
  ui_story_5022_50221202_39_dialog_content = "*Sniff* Es una trampa explosiva, así que ten mucho cuidado cuando, cuando la quites...",
  ui_story_5022_50221202_40_dialog_content = "Dale algunos dulces extra a Maggie en Canarias. Y Roy porque siempre trabaja hasta tarde. Y...",
  ui_story_5022_50221202_41_dialog_content = "Por favor, diles a todos que los amo... Waaah...",
  ui_story_5022_50221202_42_dialog_content = "Han sido dieciséis hermosos años en la Llave Rediesel...",
  ui_story_5022_50221202_43_dialog_content = "Por favor, no me olvides... ¡Waaaahhh!",
  ui_story_5022_50221202_44_dialog_content = "¿Ya terminaste?",
  ui_story_5022_50221202_45_dialog_content = "Sí...",
  ui_story_5022_50221202_46_dialog_content = "no lo haré",
  ui_story_5022_50221202_47_dialog_content = "¿Ah?",
  ui_story_5022_50221202_48_dialog_content = "Todas esas solicitudes, son demasiados problemas. No tengo tiempo para esto. Mejor lo haces tú mismo.",
  ui_story_5022_50221202_49_dialog_content = "Pero...",
  ui_story_5022_50221202_50_dialog_content = "No te preocupes. seré el héroe...",
  ui_story_5022_50221202_51_dialog_content = "En realidad, seré el villano que, tocado por los nobles caminos del héroe, abandona sus malos caminos y vuelve al camino de la virtud...",
  ui_story_5022_50221202_52_dialog_content = "Luego, cuando el héroe se enfrenta a obstáculos insuperables, salta y derrota al dragón.",
  ui_story_5022_50221202_53_dialog_content = "… Te llevaré a casa, Zeta.",
  ui_story_5022_50221301_1_dialog_content = "Azure, ¡Yo lo veo! ¡Allí!",
  ui_story_5022_50221301_2_dialog_content = "(Ese eclipse de alto nivel parece una modificación Nozard...)",
  ui_story_5022_50221301_3_dialog_content = "PlayerName, estarse quieto. Estoy a punto de pisar el acelerador.",
  ui_story_5022_50221301_4_dialog_content = "<color=#e8d9bb>¡Blam! ¡Bang... bang!</color>",
  ui_story_5022_50221301_5_dialog_content = "(Acabamos de pasar por encima de un pequeño eclipse...)",
  ui_story_5022_50221301_6_dialog_content = "¿Esto no dañará su parachoques delantero y parabrisas?",
  ui_story_5022_50221301_7_dialog_content = "No subestimes a Bullock 8. No es como esos juguetes que ves en Illumina.",
  ui_story_5022_50221301_8_dialog_content = "Así que deja de preocuparte por mi coche. Toma esos binoculares y revisa a Zeta.",
  ui_story_5022_50221301_9_dialog_content = "Déjame ver...",
  ui_story_5022_50221301_10_dialog_content = "El... ¡El dragón recogió su coche, y Zeta todavía está dentro!",
  ui_story_5022_50221301_11_dialog_content = "Eso no suena bien. ¡Tenemos que darnos prisa!",
  ui_story_5022_50221301_12_dialog_content = "Vamos.",
  ui_story_5022_50221301_13_dialog_content = "¡Bueno! Esperar... Azure, ¿por qué vamos hacia atrás?",
  ui_story_5022_50221301_14_dialog_content = "PlayerName, por mucho que me encantaría enfrentarme a este Eclipsite de frente...",
  ui_story_5022_50221301_15_dialog_content = "Tengo un plan mejor.",
  ui_story_5022_50221301_16_dialog_content = "(Manténgase fuera de la vista y suba por pequeños senderos hasta un punto dominante en el bosque...)",
  ui_story_5022_50221301_17_dialog_content = "Ya veo. Así deben hacerlo los francotiradores. Realmente sabes lo que estás haciendo.",
  ui_story_5022_50221301_18_dialog_content = "No podría haberlo hecho por mi cuenta. Tomaría mucho más tiempo si no fuera por su capacidad para detectar eclipses más pequeños en el camino.",
  ui_story_5022_50221301_19_dialog_content = "… ¿Es así como se siente trabajar en equipo? No está nada mal.",
  ui_story_5022_50221301_20_dialog_content = "¿Eh? ¿Qué fue eso? ¡Déjame saber si puedo ser de ayuda!",
  ui_story_5022_50221301_21_dialog_content = "Estaba esperando a que dijeras eso. PlayerName, ven aquí y ponte de rodillas.",
  ui_story_5022_50221301_22_dialog_content = "Espera... ¿Eso es un arma? ¿Por qué lo pones en mi...",
  ui_story_5022_50221301_23_dialog_content = "¡Mantenerla baja!",
  ui_story_5022_50221301_24_dialog_content = "… Estupendo. La altura es simplemente perfecta.",
  ui_story_5022_50221301_25_dialog_content = "Quedarse quieto. No tiembles.",
  ui_story_5022_50221301_26_dialog_content = "Trataré dar lo mejor de mí...",
  ui_story_5022_50221301_27_dialog_content = "Je... Increíble.",
  ui_story_5022_50221301_28_dialog_content = "Soñé con este momento miles de veces, pero cuando lo imaginaba nunca sentí esto...",
  ui_story_5022_50221301_29_dialog_content = "Tranquilo.",
  ui_story_5022_50221301_30_dialog_content = "¿Puedes ver cómo le está yendo a Zeta a través de tu visor?",
  ui_story_5022_50221301_31_dialog_content = "Por supuesto. Ella está colgando de la puerta, tirando bombas...",
  ui_story_5022_50221301_32_dialog_content = "Mientras luchaba por volver al coche.",
  ui_story_5022_50221301_33_dialog_content = "¿Por qué tengo la sensación de que te lo estás pasando bien viendo esto...",
  ui_story_5022_50221301_34_dialog_content = "No seas estúpido. Los francotiradores comenzamos nuestra misión observando nuestro entorno y prediciendo el movimiento del objetivo.",
  ui_story_5022_50221301_35_dialog_content = "Pero estás en lo correcto. No me importa el espectáculo.",
  ui_story_5022_50221301_36_dialog_content = "Dirección del viento, comprobada. Velocidad del viento, comprobada.",
  ui_story_5022_50221301_37_dialog_content = "Ahora esperamos a que el Eclipsite dé la vuelta y me eche un vistazo...",
  ui_story_5022_50221301_38_dialog_content = "Extrañar Azure, He visto un eclipse de alto nivel similar antes...",
  ui_story_5022_50221301_39_dialog_content = "Tuvimos que volar toda una ciudad subterránea de Illumina para matarlo.",
  ui_story_5022_50221301_40_dialog_content = "¿No confías en mí?",
  ui_story_5022_50221301_41_dialog_content = "... Es cierto que fallé en matarlo antes.",
  ui_story_5022_50221301_42_dialog_content = "Sus garras son afiladas y su piel indestructible.",
  ui_story_5022_50221301_43_dialog_content = "Mis amigos y yo derramamos sangre y sufrimos por ello.",
  ui_story_5022_50221301_44_dialog_content = "Pero el pasado es el pasado... La llave inglesa Rediesel no teme a nada.",
  ui_story_5022_50221301_45_dialog_content = "Nunca rechazamos una pelea, y siempre luchamos para ganar.",
  ui_story_5022_50221301_46_dialog_content = "Si no podemos ganar, encontraremos una oportunidad para desquitarnos.",
  ui_story_5022_50221301_47_dialog_content = "... ¡Y esa oportunidad es ahora!",
  ui_story_5022_50221301_48_dialog_content = "¡¡Auge!!",
  ui_story_5022_50221301_49_dialog_content = "!",
  ui_story_5022_50221301_50_dialog_content = "¿Funcionó? Vi la bala penetrar su ojo...",
  ui_story_5022_50221301_51_dialog_content = "No te muevas.",
  ui_story_5022_50221301_52_dialog_content = "E-Está bien...",
  ui_story_5022_50221301_53_dialog_content = "... No funcionó.",
  ui_story_5022_50221301_54_dialog_content = "El comportamiento del objetivo ha cambiado, pero todavía se está moviendo.",
  ui_story_5022_50221301_55_dialog_content = "Sin embargo, aunque no sé tanto sobre eclipses como Roy...",
  ui_story_5022_50221301_56_dialog_content = "Creo que perder los ojos contaría como un mal día para cualquier ser vivo.",
  ui_story_5022_50221301_57_dialog_content = "je. Todavía se mueve a pesar de tener una bala en la cabeza... Pero eso lo hace más interesante.",
  ui_story_5022_50221301_58_dialog_content = "<color=#e8d9bb>¡Bam! ¡Bum, bum!</color>",
  ui_story_5022_50221301_59_dialog_content = "Woah, ese destello cegador... Y una serie de explosiones... ¿Era Zeta?",
  ui_story_5022_50221301_60_dialog_content = "Sí. Ella se escapó.",
  ui_story_5022_50221301_61_dialog_content = "¿Que hacemos ahora? ¿Recargar el arma?",
  ui_story_5022_50221301_62_dialog_content = "Puedo sentir otros eclipses. Son atraídos aquí por los disparos y las explosiones...",
  ui_story_5022_50221301_63_dialog_content = "Vamos, PlayerName.",
  ui_story_5022_50221301_64_dialog_content = "Saquemos esa cosita ruidosa de ahí primero.",
  ui_story_5022_50221402_1_dialog_content = "¡Guaaaahh!",
  ui_story_5022_50221402_2_dialog_content = "¿Cómo es que todavía hay tantos eclipses... Vienen del subsuelo?",
  ui_story_5022_50221402_3_dialog_content = "Podrían tener una guarida en algún lugar de este cañón.",
  ui_story_5022_50221402_4_dialog_content = "Esa es una pieza importante de inteligencia. Sin embargo, ahora mismo tenemos que centrarnos en el enemigo.",
  ui_story_5022_50221402_5_dialog_content = "Menos mal que está corriendo como un loco después de perder los ojos. De lo contrario, nunca podríamos unirnos a Zeta.",
  ui_story_5022_50221402_6_dialog_content = "*sollozos*... Azure...",
  ui_story_5022_50221402_7_dialog_content = "Zeta, está bien abrazar a la persona que te salvó la vida.",
  ui_story_5022_50221402_8_dialog_content = "Pero no es agradable dejar tus mocos encima de ella.",
  ui_story_5022_50221402_9_dialog_content = "El, el Caelestite entonces... Waaah...",
  ui_story_5022_50221402_10_option_content = "¡¿Está bien limpiarme los mocos?!",
  ui_story_5022_50221402_11_dialog_content = "¡Solo un poco más largo!",
  ui_story_5022_50221402_12_dialog_content = "Soy, soy la heroína que salvará a Astra. *Sniff* ¡No puedo rendirme todavía!",
  ui_story_5022_50221402_13_option_content = "No tengas miedo. Estamos aquí contigo.",
  ui_story_5022_50221402_14_dialog_content = "*Sollozo*",
  ui_story_5022_50221402_15_dialog_content = "Gracias Caelestita...",
  ui_story_5022_50221402_16_dialog_content = "Ahora estoy bien.",
  ui_story_5022_50221402_17_dialog_content = "El Dragón Malvado Hakudoma apareció en medio de mi enfrentamiento con Azure... Así pone a prueba el destino al elegido...",
  ui_story_5022_50221402_18_dialog_content = "(Ella todavía está sollozando, pero parece estar recuperándose bastante rápido...)",
  ui_story_5022_50221402_19_dialog_content = "Tenemos que desgastarlo. PlayerName, planificar una ruta.",
  ui_story_5022_50221402_20_dialog_content = "Bueno. Tengo esto.",
  ui_story_5022_50221402_21_dialog_content = "<color=#e8d9bb>Bang Bang Bang...</color>",
  ui_story_5022_50221402_22_dialog_content = "<color=#e8d9bb>Bum... Bum... Bum...</color>",
  ui_story_5022_50221402_23_dialog_content = "¡¡Auge!!",
  ui_story_5022_50221402_24_dialog_content = "(En las operaciones anteriores, ella siguió la ruta que le tracé, pero...)",
  ui_story_5022_50221402_25_dialog_content = "(Ahora, Zeta ha descubierto rápidamente el patrón y está lanzando bombas de caramelo en lugares difíciles de esquivar para el malvado dragón...)",
  ui_story_5022_50221402_26_dialog_content = "(Y señorita Azure está disparando todas y cada una de esas bombas... Su trabajo en equipo es simplemente perfecto.)",
  ui_story_5022_50221402_27_dialog_content = "(Este Eclipsite es diferente a cualquier otro que haya conocido).",
  ui_story_5022_50221402_28_dialog_content = "Hmm... Si es similar a Nozard, debería poder manipular otros Eclipsites para atacar.",
  ui_story_5022_50221402_29_dialog_content = "Pero por otro lado, se ve y se mueve como los Vice y traté en el Corredor de los Susurros.",
  ui_story_5022_50221402_30_dialog_content = "Excepto que es más duro y de piel más gruesa. Es... Es casi indestructible.",
  ui_story_5022_50221402_31_dialog_content = "Si no podemos prever cómo actuará y elegir sus objetivos, esto puede volverse muy peligroso...",
  ui_story_5022_50221402_32_dialog_content = "PlayerName, ¿Tiene un plan?",
  ui_story_5022_50221402_33_dialog_content = "… Parece que sigue un patrón cuando esquiva nuestros ataques… Como…",
  ui_story_5022_50221402_34_dialog_content = "<color=#e8d9bb>Boom...</color>",
  ui_story_5022_50221402_35_dialog_content = "¡Deja de distraerte, Caelestite! ¡Las garras del malvado dragón no son para decorar!",
  ui_story_5022_50221402_36_dialog_content = "¡Esta bien! Mantendré un ojo en el Caelestite.",
  ui_story_5022_50221402_37_dialog_content = "... Lo tengo!",
  ui_story_5022_50221402_38_dialog_content = "¡Me asustaste! ¿Que has descubierto?",
  ui_story_5022_50221402_39_dialog_content = "Ese núcleo rojo.",
  ui_story_5022_50221402_40_dialog_content = "Azure, ¿tú también lo notaste? ¡Sí, está protegiendo el núcleo en su pecho!",
  ui_story_5022_50221402_41_dialog_content = "Sí, lo acabo de confirmar con mi última toma.",
  ui_story_5022_50221402_42_dialog_content = "Desde que perdió los ojos, ha confiado en sus instintos y en la capacidad de sentir a Lumina para evitar nuestros golpes.",
  ui_story_5022_50221402_43_dialog_content = "Ahora que tenemos su punto débil... PlayerName! Zeta!",
  ui_story_5022_50221402_44_dialog_content = "¡Vamos a triturarlo hasta convertirlo en polvo!",
  ui_story_5022_50221501_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50221501_2_dialog_content = "¡Graaooooohhh!",
  ui_story_5022_50221501_3_dialog_content = "Aunque conocemos su punto débil, el núcleo parece estar muy bien protegido. Es casi imposible de romper.",
  ui_story_5022_50221501_4_dialog_content = "La bala de Miss Azure no atravesó... ¿Qué debemos hacer?",
  ui_story_5022_50221501_5_dialog_content = "Bueno... Si una bala no funciona, intentaremos con diez. Si eso sigue sin funcionar, despediremos a cien de ellos, todos en el mismo lugar.",
  ui_story_5022_50221501_6_dialog_content = "De todos modos, no sería muy satisfactorio si lo derrotamos de inmediato.",
  ui_story_5022_50221501_7_dialog_content = "Es... ¡Está tratando de escapar!",
  ui_story_5022_50221501_8_dialog_content = "¡Ni siquiera lo pienses!",
  ui_story_5022_50221501_9_dialog_content = "Nuestros ataques han herido las alas del malvado dragón. No podrá volar.",
  ui_story_5022_50221501_10_dialog_content = "Necesitaremos más potencia de fuego para limitar aún más su movimiento...",
  ui_story_5022_50221501_11_dialog_content = "¡Come plomo!",
  ui_story_5022_50221501_12_dialog_content = "Azure, ¡aqui! Crearé aberturas para ti.",
  ui_story_5022_50221501_13_dialog_content = "Es Jona ¡y los otros! ¿Cómo llegaron tan alto? ¡Vaya, qué entrada!",
  ui_story_5022_50221501_14_dialog_content = "PlayerName, sígueme. Encontrémonos con ellos.",
  ui_story_5022_50221501_15_dialog_content = "¡Ja, esta será mi mejor actuación hasta ahora!",
  ui_story_5022_50221501_16_dialog_content = "¡De ningún modo! La última canción es mía!",
  ui_story_5022_50221501_17_dialog_content = "¡Ja! ¡Mi música habrá convertido al enemigo en polvo antes de que puedas aclararte la garganta!",
  ui_story_5022_50221501_18_dialog_content = "Muy bien, ustedes dos, ¡el escenario es todo suyo!",
  ui_story_5022_50221501_19_dialog_content = "Pero tengo que decir que ustedes dos son muy rápidos. Lepidoz y otros ni siquiera están aquí todavía.",
  ui_story_5022_50221501_20_dialog_content = "Ya sabes lo perezoso que es nuestro lagarto. Y crece una actitud en los viajes de larga distancia.",
  ui_story_5022_50221501_21_dialog_content = "Roy sabe cómo engatusarlo. Deberían llegar aquí pronto.",
  ui_story_5022_50221501_22_dialog_content = "Bueno, entonces se perderán toda la diversión de matar dragones. ¡Ahora que estoy aquí, terminaremos en segundos!",
  ui_story_5022_50221501_23_dialog_content = "Hmph. ¡Si puedes seguirme el ritmo, eso es!",
  ui_story_5022_50221501_24_dialog_content = "¡Un guerrero no permitirá que el mal escape! ¡Ahora, cuenta tus pecados!",
  ui_story_5022_50221501_25_dialog_content = "Incluso si quisiera contar sus pecados, creo que solo escucharíamos \"gaah\" y \"garr\".",
  ui_story_5022_50221501_26_dialog_content = "¡Hace calor aquí! Si no le importa, le daré un golpe con mi arma.",
  ui_story_5022_50221501_27_dialog_content = "Suspiro...",
  ui_story_5022_50221501_28_dialog_content = "Ahora que todos están aquí, no puedo evitar sentir que fue un poco estúpido de mi parte tratar de enfrentarme al dragón solo.",
  ui_story_5022_50221501_29_dialog_content = "Gah...",
  ui_story_5022_50221501_30_dialog_content = "Esta vez, yo... quiero decir que nosotros...",
  ui_story_5022_50221501_31_dialog_content = "¡No te dejaré escapar con vida!",
  ui_story_5022_50221502_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5022_50221502_2_dialog_content = "<size=45>Graaaaahhhhhh!</size>",
  ui_story_5022_50221502_3_dialog_content = "Se acabó.",
  ui_story_5022_50221502_4_dialog_content = "¿Ganamos? He usado todas mis bombas de caramelo, pero no parecían hacer mucho...",
  ui_story_5022_50221502_5_dialog_content = "Uf... No está mal, Azure. Visita al Gusano de Arena Retorcido cuando encuentres tiempo. Invito yo.",
  ui_story_5022_50221502_6_dialog_content = "Parece que no habrá bis. El grande se convirtió en cenizas tan pronto como murió.",
  ui_story_5022_50221502_7_dialog_content = "Para un espectáculo espectacular como este, no me importa estar en la audiencia por una vez.",
  ui_story_5022_50221502_8_dialog_content = "Deberían amarrarte a ti y a tu voz chillona a los asientos para siempre.",
  ui_story_5022_50221502_9_dialog_content = "¿Qué fué lo que me dijiste? Hacía demasiado viento para oír.",
  ui_story_5022_50221502_10_dialog_content = "(Se pelean y discuten, pero en el fondo son muy cercanos).",
  ui_story_5022_50221502_11_dialog_content = "(Me pregunto que Vice es hasta ahora...)",
  ui_story_5022_50221502_12_dialog_content = "(Espera... Siento que nos estamos perdiendo algo realmente importante otra vez...)",
  ui_story_5022_50221502_13_dialog_content = "<color=#e8d9bb>Bang Bang Bang...</color>",
  ui_story_5022_50221502_14_dialog_content = "Algo se acerca... ¿Un coche?",
  ui_story_5022_50221502_15_dialog_content = "¡Oye! ¿Para qué están todos aquí?",
  ui_story_5022_50221502_16_dialog_content = "Ese auto está haciendo algunos ruidos preocupantes... pero al menos se está moviendo.",
  ui_story_5022_50221502_17_dialog_content = "¡Hola a todos!",
  ui_story_5022_50221502_18_dialog_content = "¿Eh? ¿Nos perdimos una fiesta o algo así?",
  ui_story_5022_50221502_19_dialog_content = "Suspiro... Brock Quería ayudarme a arreglar el auto, pero rompió el Comunicador. No hemos recibido nada desde...",
  ui_story_5022_50221502_20_dialog_content = "¡Te entregué exactamente los destornilladores que me pediste!",
  ui_story_5022_50221502_21_dialog_content = "Y puedo decir que estás muy orgulloso de ello...",
  ui_story_5022_50221502_22_dialog_content = "De todos modos... ¡Esta vez no me ganarás, Zeta!",
  ui_story_5022_50221502_23_dialog_content = "...",
  ui_story_5022_50221502_24_dialog_content = "¡Olvidé que la carrera sigue en marcha!",
  ui_story_5022_50221502_25_dialog_content = "Bruja Cero Absoluto Azure!",
  ui_story_5022_50221502_26_dialog_content = "No hay necesidad de gritar, guerrero.",
  ui_story_5022_50221502_27_dialog_content = "Derrotaste al dragón antes de que yo pudiera, ¡pero el rally aún no ha terminado!",
  ui_story_5022_50221502_28_dialog_content = "¡Yo... no esperaré a que te pongas al día!",
  ui_story_5022_50221502_29_dialog_content = "<color=#e8d9bb>¡Boom... Boom! Auge...</color>",
  ui_story_5022_50221502_30_dialog_content = "El auto de Zeta de alguna manera sobrevivió a las garras del malvado dragón...",
  ui_story_5022_50221502_31_dialog_content = "No tenemos tiempo para quedarnos boquiabiertos, PlayerName.",
  ui_story_5022_50221502_32_dialog_content = "Extrañar Azure?",
  ui_story_5022_50221502_33_dialog_content = "¿Te unirías a mí durante el resto de la carrera y conducirías conmigo hasta el fin del mundo?",
  ui_story_5022_50221502_34_dialog_content = "Por supuesto...",
  ui_story_5022_50221502_35_dialog_content = "¿Pero por qué lo haces sonar raro?",
  ui_story_5022_50221502_36_dialog_content = "Estimados oyentes, tal como les comenté anteriormente durante esta emocionante batalla...",
  ui_story_5022_50221502_37_dialog_content = "¡¡¡Gah!!!",
  ui_story_5022_50221502_38_dialog_content = "(Casi me olvido de este comentarista de radio súper ruidoso...)",
  ui_story_5022_50221502_39_dialog_content = "Equipo Azure y Team Zeta dejaron de lado viejos rencores y unieron fuerzas con nuestro personal de eventos.",
  ui_story_5022_50221502_40_dialog_content = "¡En una asombrosa demostración de habilidad, derrotaron al malvado dragón Hakudoma!",
  ui_story_5022_50221502_41_dialog_content = "Los miembros desarmados del Equipo de Logística 3 se escondieron en un rincón y transmitieron toda la batalla.",
  ui_story_5022_50221502_42_dialog_content = "No hubo más bajas que el dragón, que fue bombardeado hasta el olvido. ¡Felicitaciones a todos!",
  ui_story_5022_50221502_43_dialog_content = "¡Apuesto a que nuestros concursantes desearían haber escuchado mis apasionados comentarios durante la batalla!",
  ui_story_5022_50221502_44_dialog_content = "(Err... No realmente...)",
  ui_story_5022_50221502_45_dialog_content = "Pero no te preocupes. ¡Escucho tu llamada!",
  ui_story_5022_50221502_46_dialog_content = "¡Volveré a contar toda la historia especialmente para ti en la fiesta de celebración más tarde!",
  ui_story_5022_50221502_47_dialog_content = "Lo volveré a contar con tal realismo y detalle que será mejor que unirme a la batalla real. ¡Y solo por 1000 Nightium!",
  ui_story_5022_50221502_48_dialog_content = "¡Ahora, nuestros concursantes están de vuelta en la competencia, corriendo hacia la línea de meta en el límite de la Noche Eterna!",
  ui_story_5022_50221502_49_dialog_content = "¡Además, Lepidoz finalmente se ha liberado de la grieta y se dirige en la misma dirección!",
  ui_story_5022_50221502_49X_dialog_content = "Realmente necesita cuidar lo que come...",
  ui_story_5022_50221502_50_dialog_content = "La carrera está entrando en su etapa final. ¿Qué otras sorpresas nos tienen nuestros concursantes?",
  ui_story_5022_50221502_51_dialog_content = "Azure, ¡mirar! ¡Más adelante!",
  ui_story_5022_50221502_52_dialog_content = "… ¡Zeta! <size=45>¡No te escaparás esta vez! </size><size=40>... Tú... </size><size=35>... Ah... </size><size=30>... Ay... </size><size=25>... Ay... </size><size=20>...</size>",
  ui_story_5022_50221502_53_dialog_content = "Er... Parece que el coche de Brock está rodando cuesta abajo...",
  ui_story_5022_50221502_54_dialog_content = "¡En la zigzagueante sección cuesta abajo de Blazing Tooth, Sweet Devil y My Super Dream Team están teniendo una feroz batalla!",
  ui_story_5022_50221502_55_dialog_content = "¡Zeta pareció girar a la izquierda durante el giro a la derecha, pero en realidad se estaba posicionando para girar a la izquierda justo después!",
  ui_story_5022_50221502_56_dialog_content = "¡El resultado fue un derrape absolutamente perfecto!",
  ui_story_5022_50221502_57_dialog_content = "¡Engañado por sus excelentes técnicas, Powerball de My Super Dream Team se ha salido de la carretera! Parece que necesitará un trabajo de reparación serio.",
  ui_story_5022_50221502_58_dialog_content = "Mientras tanto, Azure se está poniendo al día rápidamente...",
  ui_story_5022_50221502_59_dialog_content = "El parabrisas de su coche está hecho añicos... ¿Es realmente seguro conducir así?",
  ui_story_5022_50221502_60_dialog_content = "¡Cuidado ahora! Este es el Dragón de Arena, el Rainbow ¡Cazador del que estás hablando!",
  ui_story_5022_50221502_61_dialog_content = "¡Que nombre!",
  ui_story_5022_50221502_62_dialog_content = "De hecho, te mantienes al día. La leyenda hace honor a su reputación...",
  ui_story_5022_50221502_63_dialog_content = "¡Veamos cómo manejas esto!",
  ui_story_5022_50221502_64_dialog_content = "¡Vaya, está acelerando!",
  ui_story_5022_50221502_65_dialog_content = "Te mueves demasiado cuando cambias de marcha.",
  ui_story_5022_50221502_66_dialog_content = "¿Qué... qué?",
  ui_story_5022_50221502_67_dialog_content = "Escucha. No se distraiga con los demás ni con las ventajas o desventajas que pueda tener. Concéntrate en ti mismo.",
  ui_story_5022_50221502_68_dialog_content = "(¡No puedo ver nada afuera, pero creo que están uno al lado del otro!)",
  ui_story_5022_50221502_69_dialog_content = "¿Que sabes? No es como si me hubieras vencido antes...",
  ui_story_5022_50221502_70_dialog_content = "Ja. Fui dos veces campeón del Circuito Blazing Tooth incluso antes de que nacieras.",
  ui_story_5022_50221502_71_dialog_content = "Puedo decir exactamente qué estúpidos trucos estás planeando hacer con solo escuchar los comentarios de la radio...",
  ui_story_5022_50221502_72_dialog_content = "... Y sé cómo planeas ganar la carrera.",
  ui_story_5022_50221502_73_dialog_content = "Tú... ¿Me has estado observando?",
  ui_story_5022_50221502_74_dialog_content = "¡Azur!",
  ui_story_5022_50221502_75_dialog_content = "¿Eh? ¿No te gustó lo que dije? Bueno, demuéstrame que estoy equivocado.",
  ui_story_5022_50221502_76_dialog_content = "Pensé que lo más importante en esta carrera era vencerte...",
  ui_story_5022_50221502_77_dialog_content = "Pero como es que ...",
  ui_story_5022_50221502_78_dialog_content = "Aunque todavía no te gané...",
  ui_story_5022_50221502_79_dialog_content = "¿Me siento feliz?",
  ui_story_5022_50221502_80_dialog_content = "¿Mmm?",
  ui_story_5022_50221502_81_dialog_content = "Este circuito... Este intento de récord... Este...",
  ui_story_5022_50221502_82_dialog_content = "Nunca he hecho esto bien antes.",
  ui_story_5022_50221502_83_dialog_content = "Boo-hoo... ¡Waaaah!",
  ui_story_5022_50221502_84_dialog_content = "¿Ella está llorando? Menos mal que no hay nada más que llanuras de arena por delante...",
  ui_story_5022_50221502_85_dialog_content = "jeje, eso me trae recuerdos. Yo mismo solía ser así.",
  ui_story_5022_50221502_86_dialog_content = "Entonces me di cuenta de que ganar era menos gratificante que trabajar con mis rivales para superar nuestros límites.",
  ui_story_5022_50221502_87_dialog_content = "Tengo que admitir que eres un conductor bastante decente.",
  ui_story_5022_50221502_88_dialog_content = "Azur…",
  ui_story_5022_50221502_89_dialog_content = "¡Sin embargo, eso no significa que voy a dejarte ganar!",
  ui_story_5022_50221502_90_dialog_content = "Voy a establecer un nuevo récord para Blazing Tooth.",
  ui_story_5022_50221502_91_dialog_content = "¡N-No estés tan seguro de eso!",
  ui_story_5022_50221502_92_dialog_content = "¡No olvides compartir los dulces que guardas debajo de tu cama y disculparte con todos cuando pierdas!",
  ui_story_5022_50221502_93_dialog_content = "¡Olvídate de haber oído hablar de eso! ¡Bruja!",
  ui_story_5022_50221502_94_dialog_content = "Aww, pero ¿cómo podría olvidar la última petición de un guerrero?",
  ui_story_5022_50221502_95_dialog_content = "¡Aaah! ¡No voy a perder este! ¡Si te gano, tendrás que llevarme en tus misiones a partir de ahora!",
  ui_story_5022_50221502_96_dialog_content = "(Hasta yo me estoy emocionando viendo este intercambio...)",
  ui_story_5022_50221502_97_dialog_content = "(¿Es esto lo que Sinsa llama la carrera real? Creo que estoy empezando a entender lo que quiso decir.)",
  ui_story_5022_50221502_98_dialog_content = "(Espera... ¿Pasó algo volando por encima de tu cabeza?)",
  ui_story_5022_50221502_99_dialog_content = "Eh...",
  ui_story_5022_50221502_100_dialog_content = "Eh?!?!",
  ui_story_5022_50221601_1_dialog_content = "ZzZzz... ¡Ay!",
  ui_story_5022_50221601_2_dialog_content = "Tengo que estar despierto para ver a los pilotos cruzar la línea de meta...",
  ui_story_5022_50221601_3_dialog_content = "Puedes apoyarte en mi hombro si quieres dormir. Y no te preocupes por la carrera.",
  ui_story_5022_50221601_4_dialog_content = "Puede que no pueda ver, pero sentiré el viento cuando los autos se acerquen.",
  ui_story_5022_50221601_5_dialog_content = "Dawn, ¿todavía no hay rastro de ellos? Hace mucho calor aquí, me está dando sueño...",
  ui_story_5022_50221601_6_dialog_content = "Puedo sentir una vibración en la distancia...",
  ui_story_5022_50221601_7_dialog_content = "No, espera... Algo masivo se acerca...",
  ui_story_5022_50221601_8_dialog_content = "Desde el cielo.",
  ui_story_5022_50221601_9_dialog_content = "¡Oh! ¡Está viniendo!",
  ui_story_5022_50221601_10_dialog_content = "Esto... ¿Podría ser...?",
  ui_story_5022_50221601_11_dialog_content = "Huh... Esta es la cinta del arcoíris en la línea de meta. ¿Por qué está aquí? ¿Alguien terminó la carrera?",
  ui_story_5022_50221601_12_dialog_content = "Ese vehículo es enorme…. No recuerdo haber visto algo así en la línea de salida.",
  ui_story_5022_50221601_13_dialog_content = "Ah... es PlayerName¡Es Soroz!",
  ui_story_5022_50221601_14_dialog_content = "Ahora que lo mencionas... Odi envió un mensaje diciendo que un Coloso entregó un formulario de entrada en el puesto de control en el Desierto de Aire Caliente...",
  ui_story_5022_50221601_15_dialog_content = "Pensé que estaba bromeando.",
  ui_story_5022_50221601_16_dialog_content = "Por la presente anuncio que el ganador del Blazing Rally es...",
  ui_story_5022_50221601_17_dialog_content = "<size=45>Soroz y su piloto!</size>",
  ui_story_5022_50221601_18_dialog_content = "¡Ahora, finalmente, procederemos a la muy esperada ceremonia de entrega de premios!",
  ui_story_5022_50221601_19_dialog_content = "El campeón de rally puede pedir el deseo de Eve!",
  ui_story_5022_50221601_20_dialog_content = "El campeón, señorita Vice, deseos para... un pack regalo de formas de enseñar Sinsa ¡una lección!",
  ui_story_5022_50221601_21_dialog_content = "¿Ahora que?",
  ui_story_5022_50221601_22_dialog_content = "¡Escuchemos el discurso de aceptación de Miss Vice!",
  ui_story_5022_50221601_23_dialog_content = "No deje una nota que diga: \"Tengo PlayerName. Ven al Desierto de Aire Caliente si quieres volver a verlo...\"",
  ui_story_5022_50221601_24_dialog_content = "¡Y luego llévatelo!",
  ui_story_5022_50221601_25_dialog_content = "¡Eso se llama secuestro!",
  ui_story_5022_50221601_26_dialog_content = "Después del discurso de aceptación, es hora de que nuestra campeona Miss Vice para recibir su recompensa!",
  ui_story_5022_50221601_27_dialog_content = "Entonces, ¿supongo que eso significa que tendré que darle una lección a mi hermano?",
  ui_story_5022_50221601_28_dialog_content = "No, Eve, por favor...",
  ui_story_5022_50221601_29_dialog_content = "Aaaaaaaargh!!",
  ui_story_5022_50221601_30_dialog_content = "Vaya, no lo vi venir.",
  ui_story_5022_50221601_31_dialog_content = "*Sollozando* Puedo aceptar que corrimos a un empate, pero... ¿De dónde salió eso? Vice señora viene?",
  ui_story_5022_50221601_32_dialog_content = "Tiene suerte de ser amiga de Caelestite y de que su cola es tan genial...",
  ui_story_5022_50221601_33_dialog_content = "De lo contrario, ¡ya la habría desafiado a un duelo!",
  ui_story_5022_50221601_34_dialog_content = "Azure, ¿cómo es que estás tan tranquilo? ¿No estás decepcionado?",
  ui_story_5022_50221601_35_dialog_content = "Bueno, ella no hizo trampa, ¿verdad? Muy pocas personas son capaces de volar un Colossus. Diría que ganó justamente.",
  ui_story_5022_50221601_36_dialog_content = "Además, es un placer verte saltar arriba y abajo como un pequeño jerbo enojado.",
  ui_story_5022_50221601_37_dialog_content = "¿Qué fué lo que me dijiste?",
  ui_story_5022_50221601_38_dialog_content = "(nunca habia pensado eso Vice volaría Soroz aquí...)",
  ui_story_5022_50221601_39_dialog_content = "¡PlayerName!",
  ui_story_5022_50221601_40_dialog_content = "¿Cómo pudiste irte con Sinsa sin decirme?",
  ui_story_5022_50221601_41_dialog_content = "¡Escuché todo en la radio! Conducir un coche de carreras a través de un volcán... Luchar contra un Eclipsite de nueve cabezas que parecía un dragón...",
  ui_story_5022_50221601_42_dialog_content = "La batalla terminó cuando Soroz y yo llegamos al cañón. ¿Tienes idea de lo preocupados que estábamos?",
  ui_story_5022_50221601_43_option_content = "Lo siento. ¡Realmente soy!",
  ui_story_5022_50221601_44_dialog_content = "(Ella no parece recordar nuestra discusión...)",
  ui_story_5022_50221601_45_option_content = "Por favor, perdóname, Vice.",
  ui_story_5022_50221601_46_dialog_content = "Pensé que estabas enojado conmigo...",
  ui_story_5022_50221601_47_dialog_content = "Te prometo que siempre te diré a dónde voy de ahora en adelante.",
  ui_story_5022_50221601_48_dialog_content = "Mmmm... Bien. ¡Te perdonaré esta vez, pero solo porque pareces realmente arrepentirte!",
  ui_story_5022_50221601_49_dialog_content = "Y para ser justos, el rally fue divertido y ese volcán fue bastante espectacular.",
  ui_story_5022_50221601_50_dialog_content = "Flying Soroz puede haber estado doblando un poco las reglas, pero la única regla en el rally es que no hay reglas. ¿Derecha?",
  ui_story_5022_50221601_51_dialog_content = "Deberías invitarme el año que viene, ¡soy un buen conductor de aerodeslizadores!",
  ui_story_5022_50221601_52_dialog_content = "Vice...",
  ui_story_5022_50221601_53_dialog_content = "Tal vez deberíamos jugar juntos, podría ayudarnos a tener un mejor desempeño en la carrera.",
  ui_story_5022_50221601_54_dialog_content = "¡Vice!",
  ui_story_5022_50221601_55_dialog_content = "Oh y PlayerName, no olvides tu programa de entrenamiento. Te lo recordaré todos los días como siempre!",
  ui_story_5022_50221601_56_dialog_content = "Err… no creo que eso sea…",
  ui_story_5022_50221601_57_dialog_content = "<color=#e8d9bb>Crepitar...</color>",
  ui_story_5022_50221601_58_dialog_content = "¡Hola a todos! ¡¿Me extrañaste?!",
  ui_story_5022_50221601_59_dialog_content = "¿Qué fue eso?",
  ui_story_5022_50221601_60_dialog_content = "Está bien. Es solo la radio. A mí también me sobresaltó cuando lo escuché por primera vez.",
  ui_story_5022_50221601_61_dialog_content = "Jomu ha estado transmitiendo comerciales todo este tiempo. Ni siquiera mencionó que Soroz se sumó a la carrera...",
  ui_story_5022_50221601_62_dialog_content = "Apuesto a que algunos de nuestros oyentes deben estar quejándose de que no he mencionado la aparición de Vice ¡en la carrera!",
  ui_story_5022_50221601_63_dialog_content = "De hecho, ¡esta es la primera vez que un Coloso se une al Blazing Rally!",
  ui_story_5022_50221601_64_dialog_content = "Tos… Y para mantener la carrera interesante, también puede ser la última vez.",
  ui_story_5022_50221601_65_dialog_content = "¡Solo dejé de mencionarlo para crear un poco de suspenso para nuestros oyentes!",
  ui_story_5022_50221601_66_dialog_content = "Gracias por acudir a nuestro programa para el Blazing Rally de este año. ¡Hasta la próxima, y no olvides completar la encuesta!",
  ui_story_5022_50221601_67_dialog_content = "Además, por favor pase por mi tienda. Tenemos…",
  ui_story_5022_50221601_68_dialog_content = "Ey, Jomu! Ven aquí. Tengo toda una palangana de dátiles para que los peles.",
  ui_story_5022_50221601_69_dialog_content = "Roy, estoy transmitiendo!",
  ui_story_5022_50221601_70_dialog_content = "Estupendo. Luego dígales a todos que dejen de jugar y vengan, la comida está lista.",
  ui_story_5022_50221601_71_dialog_content = "Brock, no abras esas latas de proteína en polvo. No te dije... Oye, no, ¡no te lo eches en la boca! Fleur, detenerlo!",
  ui_story_5022_50221601_72_dialog_content = "Tos... Entonces, supongo que todos escucharon...",
  ui_story_5022_50221601_73_dialog_content = "¡Es hora de la fiesta de celebración!",
  ui_story_5022_50221601_74_dialog_content = "Muy bien, terminaré de ocuparme de mi hermano después de la comida.",
  ui_story_5022_50221601_75_dialog_content = "¡¿Hay más?!",
  ui_story_5022_50221601_76_dialog_content = "¿Cómo es? Mucho mejor que antes, ¿verdad?",
  ui_story_5022_50221601_77_dialog_content = "es comestible Por lo general, lo único que realmente vale la pena esperar es el postre. ¿Qué estamos recibiendo hoy?",
  ui_story_5022_50221601_78_dialog_content = "Budín de espino cerval de mar, ¡tu favorito!",
  ui_story_5022_50221601_79_dialog_content = "¿Con puré de dátiles? Me gusta espeso y rico!",
  ui_story_5022_50221601_80_dialog_content = "Bueno, eso depende de si Jomu se ha terminado de pelarlos todavía.",
  ui_story_5022_50221601_81_dialog_content = "Qué piensas, PlayerName? Fue un viaje bastante bueno, ¿no?",
  ui_story_5022_50221601_82_dialog_content = "Definitivamente superó mis expectativas. Espera, qué... ¡¿Qué me acabas de dar de comer?!",
  ui_story_5022_50221601_83_dialog_content = "Intentalo. Brocheta de lagarto!",
  ui_story_5022_50221601_84_dialog_content = "¿Estás seguro de que esto es comestible?",
  ui_story_5022_50221601_85_dialog_content = "¡Por supuesto! Mira a Azure!",
  ui_story_5022_50221601_86_dialog_content = "no puedo creer señorita Azure está comiendo esto... y de una manera tan elegante...",
  ui_story_5022_50221601_87_dialog_content = "Esto también, PlayerName. ¿Quieres tener un gusto?",
  ui_story_5022_50221601_88_dialog_content = "¡Esta es mi serpiente de cascabel al horno con queso favorita!",
  ui_story_5022_50221601_89_dialog_content = "Err... Gracias pero...",
  ui_story_5022_50221601_90_dialog_content = "¡Comer hasta! No seas tímido.",
  ui_story_5022_50221601_91_dialog_content = "Realmente no soy... Yo... Oh...",
  ui_story_5022_50221601_92_dialog_content = "Estos son solo los aperitivos. Todavía no hemos llegado a los platos principales.",
  ui_story_5022_50221601_93_dialog_content = "¿Te han conmovido hasta las lágrimas todos estos alimentos que nunca antes habías tenido la fortuna de probar? Pobre cosa…",
  ui_story_5022_50221601_94_dialog_content = "Aqui. ¡Tengo estofado de huevo de lagarto con escarabajos!",
  ui_story_5022_50221601_95_dialog_content = "¡Mmm! ¡El malvavisco asado es tan sabroso! ¡Debemos hacer esto de regreso a casa también!",
  ui_story_5022_50221601_96_dialog_content = "Vice, Ya has tenido suficiente. Ven y ayudame...",
  ui_story_5022_50221601_97_dialog_content = "Azure?",
  ui_story_5022_50221601_98_dialog_content = "¿Qué haces sentado aquí solo? El postre no esperará a nadie.",
  ui_story_5022_50221601_99_dialog_content = "¿Conseguiste agarrar algunos?",
  ui_story_5022_50221601_100_dialog_content = "Por supuesto. También le robé la porción a Zeta porque está demasiado ocupada mostrando su muñeca premiada.",
  ui_story_5022_50221601_101_dialog_content = "Solías irte justo después del mitin y nunca asististe a una fiesta de celebración. ¡Ahora sabes lo que te has perdido todos estos años!",
  ui_story_5022_50221601_102_dialog_content = "Eh. No lo presiones.",
  ui_story_5022_50221601_103_dialog_content = "Jajaja, nunca solíamos poder disfrutar de comidas y postres lujosos como este. ¡No más depender de lagartijas asadas para llenar nuestros estómagos!",
  ui_story_5022_50221601_104_dialog_content = "Creo que merezco presionarlo un poco.",
  ui_story_5022_50221601_105_dialog_content = "Todavía tienes la costumbre de recordar el pasado como un viejo geezer. No vengas corriendo hacia mí cuando los jóvenes empiecen a enfadarse contigo.",
  ui_story_5022_50221601_106_dialog_content = "¡Vaya que frío! Por favor, todavía estoy en la flor de mi vida.",
  ui_story_5022_50221601_107_dialog_content = "...",
  ui_story_5022_50221601_108_dialog_content = "... Azure.",
  ui_story_5022_50221601_109_dialog_content = "¿Crees que su deseo se ha cumplido?",
  ui_story_5022_50221601_110_dialog_content = "¿Por qué de repente preguntas? Además, nadie conocía mejor al exlíder que tú.",
  ui_story_5022_50221601_111_dialog_content = "Solo respóndeme, por favor.",
  ui_story_5022_50221601_112_dialog_content = "...",
  ui_story_5022_50221601_113_dialog_content = "Está bien, déjame pensar.",
  ui_story_5022_50221601_114_dialog_content = "Nuestra operación de recolección y recuperación de tarifas de protección está funcionando sin problemas. Lo estamos haciendo bastante bien en lo que respecta a los golpes con nuestros enemigos y dentro de nuestra banda...",
  ui_story_5022_50221601_115_dialog_content = "Todos disfrutan de los placeres de la vida y, sorprendentemente, todos estamos bien alimentados y abrigados.",
  ui_story_5022_50221601_116_dialog_content = "Para un grupo heterogéneo de personas que se quedaron atrás o fueron abandonadas y que decidieron unirse, diré que hemos hecho un trabajo bastante bueno.",
  ui_story_5022_50221601_117_dialog_content = "Para muchos de nosotros -entre los que me incluyo- esto ya es lo más parecido a casa después de todo lo que hemos perdido.",
  ui_story_5022_50221601_118_dialog_content = "Como mala hierba, una vez fuimos arrancados de raíz, pero en una tierra estéril echamos raíces y crecimos sin control.",
  ui_story_5022_50221601_119_dialog_content = "Desde nuestro lugar en el desierto, apagamos los fuegos que los altos y poderosos señores nobles no pueden apagar y resolvemos los asuntos que están fuera de su alcance.",
  ui_story_5022_50221601_120_dialog_content = "Así que diría que sí.",
  ui_story_5022_50221601_121_dialog_content = "...Gracias.",
  ui_story_5022_50221601_122_dialog_content = "Aunque comparándonos con malas hierbas... Bueno, supongo que tienes razón.",
  ui_story_5022_50221601_123_dialog_content = "Ve a buscar joven Sinsa si quieres escuchar a alguien encerar poética, eso no es lo mío.",
  ui_story_5022_50221601_124_dialog_content = "¿Sigues llamándolo así? Puede que sea más joven que nosotros, pero ya es un líder capaz por derecho propio.",
  ui_story_5022_50221601_125_dialog_content = "¿En serio? Nuestro líder capaz solo estaba gimiendo para PlayerName junto a la fogata.",
  ui_story_5022_50221601_126_dialog_content = "Se quejaba de que todavía le das palmaditas en la cabeza y lo avergüenzas exponiendo todos los errores tontos cuando era solo un saltamontes verde.",
  ui_story_5022_50221601_127_dialog_content = "je. En definitiva, joven Sinsa no es tan confiable todavía. Al menos sus habilidades de actuación todavía tienen mucho margen de mejora.",
  ui_story_5022_50221601_128_dialog_content = "Hiciste que me siguiera, ¿no? Zeta me retó, y Sinsa y PlayerName me subí a mi auto...",
  ui_story_5022_50221601_129_dialog_content = "¿No me digas que incluso la apariencia del Coloso estaba en tus cálculos?",
  ui_story_5022_50221601_130_dialog_content = "Oye, sabes que no soy tan inteligente.",
  ui_story_5022_50221601_131_dialog_content = "Lo único que realmente planeé fue que tuvieras algunos compañeros este año por una vez.",
  ui_story_5022_50221601_132_dialog_content = "Quería mostrarte lo mucho que han crecido esos pequeños y toda la Llave Rediesel desde que te fuiste por tu cuenta.",
  ui_story_5022_50221601_133_dialog_content = "Entonces una cosa llevó a la otra…",
  ui_story_5022_50221601_134_dialog_content = "Estaba tan ansioso que casi vomité cuando tú y el Caelestite salieron volando del volcán...",
  ui_story_5022_50221601_135_dialog_content = "¿Mmm? ¡Qué extraño escuchar esto del hombre que me enseñó a usar Eclipsitas como colchón, y pendientes de arena como cinturón de aceleración, y mantener mi velocidad en las curvas cuesta abajo!",
  ui_story_5022_50221601_136_dialog_content = "jajaja Verdadero…",
  ui_story_5022_50221601_137_dialog_content = "Ese dragón fue una sorpresa total.",
  ui_story_5022_50221601_138_dialog_content = "Ojalá el malvado dragón pudiera permanecer en las historias solo para Zeta.",
  ui_story_5022_50221601_139_dialog_content = "Aunque las nuevas experiencias nos ayudan a crecer. Las lesiones son solo una parte del entrenamiento y un rito de iniciación para los miembros de Rediesel Wrench.",
  ui_story_5022_50221601_140_dialog_content = "Pero volvió sana y salva... Espera. ¿Será realmente Zeta la heroína elegida?",
  ui_story_5022_50221601_141_dialog_content = "En los cuentos de aventuras, los padres del protagonista siempre mueren al principio, lo que dice mucho sobre mi destino.",
  ui_story_5022_50221601_142_dialog_content = "¡Ay!",
  ui_story_5022_50221601_143_dialog_content = "Eso no es divertido. Zeta lloraría, y es ruidosa cuando lo hace. Ya lo he sufrido dos veces hoy.",
  ui_story_5022_50221601_144_dialog_content = "¿Cuándo se volvieron tan cercanos ustedes dos? No está mal... ¿Qué tal si la traes en tu próxima misión?",
  ui_story_5022_50221601_145_dialog_content = "¡Ni siquiera lo pienses! Primero tendrá que ganarme en el Blazing Tooth.",
  ui_story_5022_50221601_146_dialog_content = "¿Así que te apuntas al rally del año que viene?",
  ui_story_5022_50221601_147_dialog_content = "… Mmm. Supongo.",
  ui_story_5022_50221601_148_dialog_content = "¡Excelente! Las misiones del equipo de Exploración son importantes. Pero todos necesitamos relajarnos un poco de vez en cuando y vivir la vida al máximo.",
  ui_story_5022_50221601_149_dialog_content = "No tienes que enseñarme eso. Yo a veces...",
  ui_story_5022_50221601_150_dialog_content = "Encontrarse con Jona para beber el almacenamiento de la taberna local antes de conducir a la próxima ciudad para beber más? Realmente no puedo llamar a eso un pasatiempo saludable.",
  ui_story_5022_50221601_151_dialog_content = "Em...",
  ui_story_5022_50221601_152_dialog_content = "Es una pequeña mejora, pero me alegro de que estés de vuelta en las pistas.",
  ui_story_5022_50221601_153_dialog_content = "Siempre te ha gustado actuar duro...",
  ui_story_5022_50221601_154_dialog_content = "¿Y de dónde saqué eso? ¡Ninguno más que tú!",
  ui_story_5022_50221601_155_dialog_content = "… ¿Eh? ¿Es eso así?",
  ui_story_5022_50221601_156_dialog_content = "¡Tú eres el que debería estar sentado y dejar que los jóvenes tomen las riendas!",
  ui_story_5022_50221601_157_dialog_content = "<color=#e8d9bb>Bam... ¡Boom!</color>",
  ui_story_5022_50221601_158_dialog_content = "...",
  ui_story_5022_50221601_159_dialog_content = "...",
  ui_story_5022_50221601_160_dialog_content = "Wahahaha! ¡Las bengalas estallaron en todo el rostro de Regina! ¡Mira, jajaja!",
  ui_story_5022_50221601_161_dialog_content = "Brock, tu cara también está manchada.",
  ui_story_5022_50221601_162_dialog_content = "Barbara, ¡Voy a matarte!",
  ui_story_5022_50221601_163_dialog_content = "¡Guau! Esta bomba sería perfecta en el escenario. ¿No crees? Tiny One?",
  ui_story_5022_50221601_164_dialog_content = "Sí, pero tenemos que ajustar el radio de explosión. Déjame ver la estructura interior...",
  ui_story_5022_50221601_165_dialog_content = "¿Te gusta, te gusta? ¡Tengo más de la misma serie! ¡Se han mejorado!",
  ui_story_5022_50221601_166_dialog_content = "Solo quieres hacer estallar fuegos artificiales.",
  ui_story_5022_50221601_167_dialog_content = "¿No es esa la manera perfecta de terminar la fiesta de celebración? Incluso Lepidoz está moviendo la cola.",
  ui_story_5022_50221601_168_dialog_content = "¿Qué era lo que estabas diciendo? ¿\"Que los jóvenes tomen las riendas\" o algo así?",
  ui_story_5022_50221601_169_dialog_content = "Caray, estos mocosos...",
  ui_story_5022_50221601_170_dialog_content = "Jajaja, no es malo que se aferren a su juventud.",
  ui_story_5022_50221601_171_dialog_content = "Cae-les-tite! ¿Fuiste tú quien se comió mi postre?",
  ui_story_5022_50221601_172_dialog_content = "Incluso si me salvaste la vida, ¡robar el postre de alguien no se puede perdonar!",
  ui_story_5022_50221601_173_dialog_content = "¡No fui yo! fue la señorita Azure... Ella...",
  ui_story_5022_50221601_174_dialog_content = "¿A dónde fue? Extrañar Azure!",
  ui_story_5022_50221601_175_dialog_content = "Vaya, parece que tu pequeño compañero de equipo está en problemas. ¿No vas a intervenir?",
  ui_story_5022_50221601_176_dialog_content = "no subestimes PlayerName.",
  ui_story_5022_50221601_177_dialog_content = "Todavía hay cosas interesantes por venir para eso.",
  ui_story_5022_50221601_178_dialog_content = "La historia de Caelestite no terminará con pudín.",
  ui_story_5022_50221601_179_dialog_content = "Creo en esto.",
  ui_story_5022_50221601_180_dialog_content = "Sí, esa fue una gran frase que acabas de decir. Pero eso no cambia el hecho de que Caelestite está siendo perseguido por tu culpa.",
  ui_story_5022_50221601_181_dialog_content = "Azure! Roy!",
  ui_story_5022_50221601_182_dialog_content = "¡Ven aquí! ¡Es hora de fuegos artificiales!",
  ui_story_5022_50221601_183_dialog_content = "3——2——1——!"
}
return config
